-- paket 8: 4d3n-manado-highlights-tour
INSERT INTO `tour_translations` (`translatable_type`, `translatable_id`, `locale`, `title`, `description`, `inclusions`, `exclusions`, `created_at`, `updated_at`)
VALUES ('App\\Models\\ManadoTour', '8', 'fr', '4 Jours Incontournables de Manado', '<h2><strong>Circuit 4J/3N Incontournables de Manado : Découvrez les Merveilles de la Nature et de la Culture du Nord Sulawesi !</strong></h2><p>Embarquez pour une aventure inoubliable de 4 jours et 3 nuits à Manado et ses environs. Ce circuit combine une beauté sous-marine de classe mondiale, la fraîcheur des montagnes et une culture locale unique en un seul voyage exclusif pensé pour votre confort absolu.</p><h3><strong>Points forts :</strong></h3><ul><li><strong>Sites emblématiques :</strong> Visitez le temple historique <strong>Ban Hin Kiong</strong> et le majestueux <strong>Monument de Jésus Bénissant</strong> qui surplombe la ville.</li><li><strong>Paradis marin de Bunaken :</strong> Explorez le légendaire <strong>Parc marin national de Bunaken</strong>, refuge de récifs coralliens colorés et d\'une vie marine foisonnante.</li><li><strong>Charmes des hauts plateaux de Minahasa :</strong> Profitez de l\'air frais de Tomohon, découvrez l\'étonnant <strong>Marché Extrême</strong> et détendez-vous au bord du <strong>lac Linow</strong> aux couleurs changeantes.</li><li><strong>Spots dignes d\'Instagram :</strong> Capturez des vues à 360 degrés depuis la <strong>colline de Makatete</strong> et l\'esthétique palmeraie de <strong>Tuur Maasering</strong>.</li></ul>', '<ul><li data-list-item-id="e471204a79d04f381b4df48abd3568538">Transport climatisé adapté à la taille du groupe</li><li data-list-item-id="e5b23337d0965051bf73eab7da059f4d6">Bateau privé pour l\'<strong>île de Bunaken&nbsp;</strong></li><li data-list-item-id="ee8b3c0ce962717687e5c7022da4a5338">3 nuits d\'hébergement à l\'hôtel sélectionné – chambre twin/double</li><li data-list-item-id="eb352e4cf3b88e05f28979629bdbb9af3">Guide expérimenté &amp; chauffeur</li><li data-list-item-id="e15fdff726b9e0d6b7522d89e853d30c7">Frais d\'entrée aux sites touristiques &amp; frais de parking</li><li data-list-item-id="eea1816d36947b4e805dd272a628cdf0e">Repas selon le programme</li><li data-list-item-id="eb97366b44df314dee7b6f99ac3ca6044">Services de tour selon l\'itinéraire</li><li data-list-item-id="e15fff39ee2756b1703ce5cb3c6a898cf">Eau minérale 1 bouteille/pers/jour</li><li data-list-item-id="e96b7b72b91c673e978df24be855f3346">Service d\'accueil</li></ul>', '<ul><li data-list-item-id="e1dc181d36af8406f97796d1769568909">Billet d\'avion aller-retour</li><li data-list-item-id="e71726909053b640df3cf3fad15a8fa02">Pourboires pour le guide &amp; le chauffeur</li><li data-list-item-id="e11be5b6ad773248b059620b238aee9b8">Excursions optionnelles</li><li data-list-item-id="e2d93bfcb857f4cecda93f3d73f2629ee">Dépenses personnelles hors forfait (repas/boissons supplémentaires, etc.)</li><li data-list-item-id="ef7dd221a222f7b6c5b9e01cefa4cc2e4">Service de portage, taxe d\'aéroport &amp; frais de surpoids</li><li data-list-item-id="ebadfd3cab7dc05d402522ac0ce442654">Dépenses personnelles (blanchisserie, minibar, service en chambre, etc.)</li><li data-list-item-id="e81328aad0a1b986831eed337f4f20e9b">Assurance voyage</li><li data-list-item-id="e59c4a681478a9f8e689ec94ec3db1a1d">Autres frais non mentionnés dans le programme du tour</li></ul>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `inclusions` = VALUES(`inclusions`), `exclusions` = VALUES(`exclusions`), `updated_at` = NOW();

-- paket 9: 4d3n-manado-island-gateway
INSERT INTO `tour_translations` (`translatable_type`, `translatable_id`, `locale`, `title`, `description`, `inclusions`, `exclusions`, `created_at`, `updated_at`)
VALUES ('App\\Models\\ManadoTour', '9', 'fr', '4 Jours Évasion Insulaire de Manado', '<h2><strong>Circuit 4J/3N Évasion Insulaire de Manado : Explorez le Charme Tropical du Nord Sulawesi !</strong></h2><p>Vivez l\'évasion parfaite de 4 jours et 3 nuits à travers la beauté marine et la riche culture de Manado. De la majesté sous-marine de classe mondiale du <strong>Parc marin national de Bunaken</strong> au sable blanc et fin de l\'<strong>île de Lihaga</strong>, ce forfait est conçu pour des vacances inoubliables.</p><h3><strong>Points forts :</strong></h3><ul><li><strong>Sites emblématiques :</strong> Visitez <strong>Ban Hin Kiong</strong>, le plus ancien temple de Manado, et le majestueux <strong>Monument de Jésus Bénissant</strong>.</li><li><strong>Paradis marin :</strong> Explorez les récifs coralliens colorés de <strong>Bunaken</strong> et détendez-vous sur l\'île instagrammable de <strong>Lihaga</strong>.</li><li><strong>Panoramas à couper le souffle :</strong> Admirez la ville et les îles depuis la <strong>colline de Makatete</strong>, puis un coucher de soleil serein au <strong>village touristique de Budo</strong>.</li><li><strong>Saveurs locales :</strong> Goûtez le café authentique du Nord Sulawesi et faites vos emplettes de spécialités uniques de Manado.</li></ul>', '<ul><li data-list-item-id="e471204a79d04f381b4df48abd3568538">Transport climatisé adapté à la taille du groupe</li><li data-list-item-id="e5b23337d0965051bf73eab7da059f4d6">Bateau privé pour <strong>l\'île de Bunaken &amp; l\'île de Lihaga</strong></li><li data-list-item-id="ee8b3c0ce962717687e5c7022da4a5338">3 nuits d\'hébergement à l\'hôtel sélectionné – chambre twin/double</li><li data-list-item-id="eb352e4cf3b88e05f28979629bdbb9af3">Guide expérimenté &amp; chauffeur</li><li data-list-item-id="e15fdff726b9e0d6b7522d89e853d30c7">Frais d\'entrée aux sites touristiques &amp; frais de parking</li><li data-list-item-id="eea1816d36947b4e805dd272a628cdf0e">Repas selon le programme</li><li data-list-item-id="eb97366b44df314dee7b6f99ac3ca6044">Services de tour selon l\'itinéraire</li><li data-list-item-id="e15fff39ee2756b1703ce5cb3c6a898cf">Eau minérale 1 bouteille/pers/jour</li><li data-list-item-id="e96b7b72b91c673e978df24be855f3346">Service d\'accueil</li></ul>', '<ul><li data-list-item-id="e1dc181d36af8406f97796d1769568909">Billet d\'avion aller-retour</li><li data-list-item-id="e71726909053b640df3cf3fad15a8fa02">Pourboires pour le guide &amp; le chauffeur</li><li data-list-item-id="e11be5b6ad773248b059620b238aee9b8">Excursions optionnelles</li><li data-list-item-id="e2d93bfcb857f4cecda93f3d73f2629ee">Dépenses personnelles hors forfait (repas/boissons supplémentaires, etc.)</li><li data-list-item-id="ef7dd221a222f7b6c5b9e01cefa4cc2e4">Service de portage, taxe d\'aéroport &amp; frais de surpoids</li><li data-list-item-id="ebadfd3cab7dc05d402522ac0ce442654">Dépenses personnelles (blanchisserie, minibar, service en chambre, etc.)</li><li data-list-item-id="e81328aad0a1b986831eed337f4f20e9b">Assurance voyage</li><li data-list-item-id="e59c4a681478a9f8e689ec94ec3db1a1d">Autres frais non mentionnés dans le programme du tour</li></ul>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `inclusions` = VALUES(`inclusions`), `exclusions` = VALUES(`exclusions`), `updated_at` = NOW();

-- paket 10: 5d4n-tropical-wonders-of-manado
INSERT INTO `tour_translations` (`translatable_type`, `translatable_id`, `locale`, `title`, `description`, `inclusions`, `exclusions`, `created_at`, `updated_at`)
VALUES ('App\\Models\\ManadoTour', '10', 'fr', '5 Jours Merveilles Tropicales de Manado', '<h2><strong>Merveilles Tropicales de Manado : Une Exploration de 5 Jours des Paradis Exotiques du Nord Sulawesi</strong></h2><p>Découvrez l\'harmonie parfaite entre des aventures sous-marines de classe mondiale et la beauté sereine des hauts plateaux. Le forfait <strong>5J/4N Merveilles Tropicales de Manado</strong> est une invitation exclusive à explorer chaque coin magique du Nord Sulawesi — de l\'histoire de la vieille ville et des eaux cristallines de l\'île de Lihaga jusqu\'au symbole de paix de Bukit Kasih.</p><h3><strong>Points forts du circuit :</strong></h3><ul><li><strong>Exploration emblématique de la ville de Manado :</strong> Remontez le fil de l\'histoire à Ban Hin Kiong (le plus ancien temple de Manado), visitez le Monument de la Seconde Guerre mondiale, et admirez la majesté de la statue de Jésus Bénissant surplombant la mer.</li><li><strong>Merveilles marines de Bunaken :</strong> Profitez d\'une excursion au légendaire Parc marin de Bunaken, refuge de gigantesques murs de corail et de milliers d\'espèces de poissons tropicaux éclatants.</li><li><strong>L\'éclat de l\'île de Lihaga :</strong> Savourez un paradis insulaire inhabité au sable blanc poudreux et aux eaux cristallines — un lieu parfait pour se détendre et immortaliser des moments dignes d\'Instagram.</li><li><strong>Harmonie à Bukit Kasih (Colline de l\'Amour) :</strong> Respirez l\'air frais des hauts plateaux de Minahasa et visitez le centre de tolérance du Nord Sulawesi. Grimpez les marches jusqu\'au sommet pour voir cinq lieux de culte se dresser côte à côte, symbole d\'unité.</li><li><strong>Le charme du lac Linow :</strong> Terminez votre journée en vous relaxant au bord d\'un lac de soufre unique dont les eaux changent magiquement de couleur, créant une atmosphère profondément apaisante.</li></ul><h3><strong>Pourquoi choisir ce forfait ?</strong></h3><ul><li><strong>Destinations complètes :</strong> Combine le patrimoine urbain, les aventures d\'île en île et la beauté des hauts plateaux en un seul voyage fluide.</li><li><strong>Savoir local :</strong> Visitez des ateliers de production de café locaux et découvrez le processus authentique de fabrication des collations traditionnelles de Manado.</li><li><strong>Itinéraire équilibré :</strong> Un programme bien rythmé pour profiter de chaque destination sans jamais se sentir bousculé.</li></ul>', '<ul><li data-list-item-id="eea05a0fde3c9ad132dbf48ce720f5561">Transport climatisé adapté à la taille du groupe</li><li data-list-item-id="e35785e5ddfb6a5dbd4ed40faf695693a">Bateau privé pour <strong>l\'île de Bunaken &amp; l\'île de Lihaga</strong></li><li data-list-item-id="e11a26ee9d49a5ac1820047c130a6dfd5">4 nuits d\'hébergement à l\'hôtel sélectionné – chambre twin/double</li><li data-list-item-id="ed5854fe627dc7e654934ab1e976947b9">Guide expérimenté &amp; chauffeur</li><li data-list-item-id="e81a3939bb0ae47c432179a015b5820f9">Frais d\'entrée aux sites touristiques &amp; frais de parking</li><li data-list-item-id="eabab84f65a739c80174326ae687d6b04">Repas selon le programme</li><li data-list-item-id="ecc87f33179f708ea4e88eab3be33ec4b">Services de tour selon l\'itinéraire</li><li data-list-item-id="e103e760176de41ca65afc60d31e98ff4">Eau minérale 1 bouteille/pers/jour</li><li data-list-item-id="ef790cc1f991b5e82333a286a94bd3e06">Service d\'accueil</li></ul>', '<ul><li data-list-item-id="ef5d685346305b0f7f7808e0b74584d12">Billet d\'avion aller-retour</li><li data-list-item-id="e94d1cf8dad2496875a013333c9a2fb20">Pourboires pour le guide &amp; le chauffeur</li><li data-list-item-id="e78256fbdd7f99f311466b507bd7703f6">Excursions optionnelles</li><li data-list-item-id="e3cd0374398d870ebbfd590981eab8338">Dépenses personnelles hors forfait (repas/boissons supplémentaires, etc.)</li><li data-list-item-id="e863d09a2873702f66d5a57da029388d2">Service de portage, taxe d\'aéroport &amp; frais de surpoids</li><li data-list-item-id="ec55c74e4c2067333dd4c54aa28d879f1">Dépenses personnelles (blanchisserie, minibar, service en chambre, etc.)</li><li data-list-item-id="ee355dc061e586232a936ec63b0305405">Assurance voyage</li><li data-list-item-id="e321a09c3a477e2305453ecd7e331735d">Autres frais non mentionnés dans le programme du tour</li></ul>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `inclusions` = VALUES(`inclusions`), `exclusions` = VALUES(`exclusions`), `updated_at` = NOW();

-- paket 11: 4d3n-exotic-manado-explorer
INSERT INTO `tour_translations` (`translatable_type`, `translatable_id`, `locale`, `title`, `description`, `inclusions`, `exclusions`, `created_at`, `updated_at`)
VALUES ('App\\Models\\ManadoTour', '11', 'fr', '4 Jours Exploration Exotique de Manado', '<h2><strong>Manado Sans Limites : Un Voyage de 4 Jours vers des Paradis Cachés, des Hauts Plateaux à Lihaga</strong></h2><p>Êtes-vous prêt à vous évader vers un paradis tropical qui mêle merveilles sous-marines, collines verdoyantes et patrimoine culturel unique ? Le forfait <strong>4J/3N Exotic Manado Explorer</strong> est conçu avec soin pour celles et ceux qui recherchent des vacances complètes et mémorables. Du charme de la vieille ville aux îles exotiques au sable blanc et poudreux, nous vous emmenons explorer le meilleur du Nord Sulawesi.</p><h3><strong>Points forts du circuit :</strong></h3><ul><li><strong>Exploration urbaine emblématique :</strong> Visitez la majestueuse statue de Jésus Bénissant à CitraLand et remontez le fil de l\'histoire à Ban Hin Kiong, le plus ancien temple de Manado.</li><li><strong>Merveilles des hauts plateaux de Minahasa :</strong> Ressentez la brise fraîche de Tomohon, visitez le marché extrême mondialement connu, et détendez-vous avec un café ou un thé au bord des eaux changeantes du lac Linow.</li><li><strong>Paradis tropical de l\'île de Lihaga :</strong> Laissez-vous séduire par le sable blanc éblouissant et les eaux cristallines de l\'île de Lihaga — un endroit parfait pour le snorkeling, la plongée ou des clichés dignes d\'Instagram.</li><li><strong>Coucher de soleil au village touristique de Budo :</strong> Concluez votre aventure insulaire par un coucher de soleil à couper le souffle, en dégustant des bananes frites et de la noix de coco fraîche.</li><li><strong>Savoir-faire local authentique :</strong> Assistez à la production traditionnelle de la liqueur « Cap Tikus » et à des démonstrations de cuisine en direct de délicieuses collations locales de Manado</li></ul>', '<ul><li data-list-item-id="e11c918e1af328b6b0e6bd2c3d6c46e5d">Transport climatisé adapté à la taille du groupe</li><li data-list-item-id="ebc2761735faa295be9869faeba5ef9c3">Bateau privé pour l\'île de Lihaga</li><li data-list-item-id="e1f7e9ade1181eb30404b6c4f7263c2b1">3 nuits d\'hébergement à l\'hôtel sélectionné – chambre twin/double</li><li data-list-item-id="ebbdb40dd9308cc6ba65794e075cced2f">Guide expérimenté &amp; chauffeur</li><li data-list-item-id="e2279728b3feae8fdd9a4669a3cecffd3">Frais d\'entrée aux sites touristiques &amp; frais de parking</li><li data-list-item-id="e827fd57d3a5e570b5b508c9fc5e721fa">Repas selon le programme</li><li data-list-item-id="e8468f13ea9c16c3b266d42594e607992">Services de tour selon l\'itinéraire</li><li data-list-item-id="e10fb1ed65e37365dbfff95f53601fbdb">Eau minérale 1 bouteille/pers/jour</li><li data-list-item-id="ed4846e433289ae5057f860554a9f6f0d">Service d\'accueil</li></ul>', '<ul><li data-list-item-id="ef8f2361176c16ceca608dff85850a599">Billet d\'avion aller-retour</li><li data-list-item-id="ea8a90f748b0acc8d8c682bc6aba46c8f">Pourboires pour le guide &amp; le chauffeur</li><li data-list-item-id="e018e34ac8cbe045803a46d616e48d4aa">Excursions optionnelles</li><li data-list-item-id="ed2e1a8df37b435a7b0217ea2351babdd">Dépenses personnelles hors forfait (repas/boissons supplémentaires, etc.)</li><li data-list-item-id="e0b26c90da4e226af6c485c66f215a053">Service de portage, taxe d\'aéroport &amp; frais de surpoids</li><li data-list-item-id="e892a7a71628c913e7c40d29cad4c8939">Dépenses personnelles (blanchisserie, minibar, service en chambre, etc.)</li><li data-list-item-id="eb026a0cc55dc3225736ba4099fbe22c9">Assurance voyage</li><li data-list-item-id="e0d7036afa0726248cfb0462f1cd28859">Autres frais non mentionnés dans le programme du tour</li></ul>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `inclusions` = VALUES(`inclusions`), `exclusions` = VALUES(`exclusions`), `updated_at` = NOW();

-- paket 12: 3d2n-manado-bliss-gateway
INSERT INTO `tour_translations` (`translatable_type`, `translatable_id`, `locale`, `title`, `description`, `inclusions`, `exclusions`, `created_at`, `updated_at`)
VALUES ('App\\Models\\ManadoTour', '12', 'fr', '3 Jours Évasion dans les Hauts Plateaux de Manado', '<h2><strong>Évasion dans les Hauts Plateaux de Manado : Voyage entre Nature et Culture Minahasa (3J/2N)</strong></h2><p>Détendez-vous et respirez l\'air frais des montagnes du Nord Sulawesi lors d\'un voyage apaisant pour l\'âme. Ce forfait vous invite à explorer le patrimoine emblématique de la ville de Manado et la beauté à couper le souffle des hauts plateaux de Minahasa. Des vues majestueuses depuis les sommets aux lacs volcaniques sereins, chaque instant est pensé pour des vacances relaxantes et mémorables.</p><h3><strong>Points forts du circuit :</strong></h3><ul><li><strong>Sites emblématiques de Manado :</strong> Remontez le fil de l\'histoire au <strong>temple Ban Hin Kiong</strong> (le plus ancien de Manado), à l\'église Sentrum de l\'époque coloniale, et au magnifique <strong>Monument de Jésus Bénissant</strong>, symbole de protection de la ville.</li><li><strong>Panorama de la colline de Makatete :</strong> Profitez d\'une vue « à 360 degrés » depuis les hauteurs, surplombant la ville de Manado, les îles du Parc marin de Bunaken et le majestueux mont Klabat.</li><li><strong>La fraîche cité fleurie de Tomohon :</strong> Ressentez l\'air pur au pied du <strong>mont Mahawu</strong>. Visitez le <strong>lac Linow</strong>, un lac volcanique dont les eaux changent de couleur selon la lumière du soleil.</li><li><strong>Déjeuner au bord du lac Tondano :</strong> Savourez des plats locaux authentiques en contemplant les eaux tranquilles du lac Tondano, le plus grand lac du Nord Sulawesi, entouré de collines verdoyantes.</li><li><strong>Art de vivre &amp; shopping :</strong> Détendez-vous à <strong>SunBae</strong>, un lieu de rendez-vous tendance en bord de mer, et visitez un atelier de café local pour rapporter chez vous l\'arôme authentique de Sulawesi.</li></ul><p><strong>« Évadez-vous vers les hauteurs – Découvrez l\'âme de Minahasa et la sérénité des hauts plateaux. »</strong></p>', '<ul><li data-list-item-id="e8e6883a6e56a2407f008c457746ff1b6">Transport climatisé adapté à la taille du groupe</li><li data-list-item-id="e8de14905ae06a64f87cc60b7707f22d0">2 nuits d\'hébergement à l\'hôtel sélectionné – chambre twin/double</li><li data-list-item-id="e4bb6b6d5246389f96275d7a9a8a82136">Repas selon le programme</li><li data-list-item-id="eea1dca8498d90beff0733fbed2b12b77">Guide expérimenté &amp; chauffeur</li><li data-list-item-id="ec02237fe232f55cc706fb1297ad87fad">Frais d\'entrée aux sites touristiques &amp; frais de parking</li><li data-list-item-id="ed6a3feef8a8add362060ccd621024e6d">Services de tour selon l\'itinéraire</li><li data-list-item-id="ec668e506dcb5e72b186b8387ab536b9a">Eau minérale 1 bouteille/pers/jour</li><li data-list-item-id="e532893443396609a2ad9f6b124a36b95">Service d\'accueil</li></ul>', '<ul><li data-list-item-id="e3b523e8375ebb8c9d79946b95b626000">Billet d\'avion aller-retour</li><li data-list-item-id="ebb59df0fa48ba937a21926c9d7e1f3dd">Pourboires pour le guide &amp; le chauffeur</li><li data-list-item-id="e3ce39bff4df98057a82869976df231d7">Excursions optionnelles</li><li data-list-item-id="e3f219b92323c9770103f518bec22b1ba">Dépenses personnelles hors forfait (repas/boissons supplémentaires, etc.)</li><li data-list-item-id="e11ba73fd8e73eef138f3ca4ad9edebf4">Service de portage, taxe d\'aéroport &amp; frais de surpoids</li><li data-list-item-id="ec1219e9200318981e942067b191d0e19">Dépenses personnelles (blanchisserie, minibar, service en chambre, etc.)</li><li data-list-item-id="eeb6d510ef8ff5842d69e6e91a30b5aa4">Assurance voyage</li><li data-list-item-id="e0bf84136b233377c9c534be5adbe9757">Autres frais non mentionnés dans le programme du tour</li></ul>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `inclusions` = VALUES(`inclusions`), `exclusions` = VALUES(`exclusions`), `updated_at` = NOW();

-- paket 13: 3d2n-manado-highland-escape
INSERT INTO `tour_translations` (`translatable_type`, `translatable_id`, `locale`, `title`, `description`, `inclusions`, `exclusions`, `created_at`, `updated_at`)
VALUES ('App\\Models\\ManadoTour', '13', 'fr', '3 Jours Escapade Sereine de Manado', '<h2><strong>Escapade Sereine de Manado : Charme Urbain, Panoramas des Hauts Plateaux &amp; Merveilles Sous-Marines (3J/2N)</strong></h2><p>Explorez la magie du Nord Sulawesi lors d\'un séjour court mais mémorable ! Des sites historiques au cœur de Manado aux panoramas spectaculaires depuis les sommets, jusqu\'au célèbre Parc marin de Bunaken. Ce forfait est le choix parfait pour celles et ceux qui recherchent une harmonie entre culture, détente et aventure dans la nature.</p><h3><strong>Points forts du circuit :</strong></h3><ul><li><strong>Exploration historique &amp; culturelle :</strong> Remontez le passé de Manado au <strong>temple Ban Hin Kiong</strong> (le plus ancien temple, datant du 18e siècle), à l\'église Sentrum de l\'époque coloniale, et au magnifique <strong>Monument de Jésus Bénissant</strong> à CitraLand.</li><li><strong>Panoramas depuis la colline de Makatete :</strong> Profitez d\'une vue « à 360 degrés » sur la ville de Manado, l\'île de Bunaken et le mont Klabat depuis les hauteurs. Un endroit parfait pour la photographie et l\'air frais des montagnes.</li><li><strong>Magie sous-marine de Bunaken :</strong> Vivez une excursion en catamaran pour observer de superbes récifs coralliens et la vie marine sans vous mouiller, ou choisissez le snorkeling pour observer de plus près les tortues de mer et les poissons colorés.</li><li><strong>Art de vivre local :</strong> Détendez-vous à <strong>SunBae</strong>, un lieu de rendez-vous tendance en bord de mer, et visitez un atelier de café local pour goûter l\'arôme authentique du café de Sulawesi.</li><li><strong>Shopping souvenirs :</strong> Terminez votre voyage en dénichant de délicieuses collations et cadeaux traditionnels uniques de Manado avant de rentrer chez vous.</li></ul><p><strong>« Vivez la sérénité de Manado – là où histoire, hauteurs et eaux cristallines se rencontrent. »</strong></p>', '<ul><li data-list-item-id="e06181f8916c033d055bf431ea9bb507d">Transport climatisé adapté à la taille du groupe</li><li data-list-item-id="ec74f2f93cf89580ce2eba2c1def0a181">Bateau privé pour <strong>l\'île de Bunaken</strong></li><li data-list-item-id="e8e4a93b41c7a6ed50ed3813194bd6e59">2 nuits d\'hébergement à l\'hôtel sélectionné – chambre twin/double</li><li data-list-item-id="e91c056088dcfc8c669ef740833e245c5">Repas selon le programme</li><li data-list-item-id="e065c54e6af38a7ad1bd490f01b5b5818">Guide expérimenté &amp; chauffeur</li><li data-list-item-id="ee0e35b2c23993c0791e055d49f1f6f9d">Frais d\'entrée aux sites touristiques &amp; frais de parking</li><li data-list-item-id="e76df34d52a6a29e995f5d9be291dd79b">Services de tour selon l\'itinéraire</li><li data-list-item-id="e620b8eda8fdcede4f1fbaf8c0908a778">Eau minérale 1 bouteille/pers/jour</li><li data-list-item-id="e2640041a620be5c0b2575af63aa0074e">Service d\'accueil</li></ul>', '<ul><li data-list-item-id="e6fe90ccd0d08c5ebfa1c0966f14e1e37">Billet d\'avion aller-retour</li><li data-list-item-id="ee405bf5b6e9984c12726b290bcf96832">Pourboires pour le guide &amp; le chauffeur</li><li data-list-item-id="e54a6f1381c6ba9c3e26eb7685fcccedb">Excursions optionnelles</li><li data-list-item-id="e202c477f749dc16522c760ea26ce63fe">Dépenses personnelles hors forfait (repas/boissons supplémentaires, etc.)</li><li data-list-item-id="e3eee6b6c5ec03bcbabcb277307efbc5f">Service de portage, taxe d\'aéroport &amp; frais de surpoids</li><li data-list-item-id="edd02c634ddc4057311fbdaabd045c0cb">Dépenses personnelles (blanchisserie, minibar, service en chambre, etc.)</li><li data-list-item-id="e054a8fc0bec74542de93820aa5038d72">Assurance voyage</li><li data-list-item-id="ed8953b086fc7833fe1607e7f3df48f49">Autres frais non mentionnés dans le programme du tour</li></ul>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `inclusions` = VALUES(`inclusions`), `exclusions` = VALUES(`exclusions`), `updated_at` = NOW();

-- paket 14: paragliding-adventure-at-mount-tumpa
INSERT INTO `tour_translations` (`translatable_type`, `translatable_id`, `locale`, `title`, `description`, `inclusions`, `exclusions`, `created_at`, `updated_at`)
VALUES ('App\\Models\\ManadoTour', '14', 'fr', 'Aventure de Parapente au Mont Tumpa', '<h2><strong>Envolez-vous vers l\'Horizon : Aventure de Parapente au Mont Tumpa</strong></h2><p>Avez-vous déjà rêvé de voler librement comme un oiseau au-dessus d\'un paysage extraordinaire ? Réalisez ce rêve avec le <strong>parapente au mont Tumpa</strong>, la destination ultime pour faire monter votre adrénaline tout en régalant vos yeux de la ligne d\'horizon à couper le souffle du Nord Sulawesi.</p><h3><strong>Pourquoi tenter cette aventure ?</strong></h3><ul><li><strong>Un frisson à 1 000 mètres :</strong> Sentez votre cœur s\'accélérer en prenant votre envol à environ 1 000 mètres d\'altitude. Profitez d\'une liberté absolue en survolant de majestueux paysages montagneux.</li><li><strong>Panorama à triple vue :</strong> Depuis les airs, vous serez gratifié d\'une vue spectaculaire qui combine forêts luxuriantes, chaînes de montagnes et mer bleue cristalline au loin.</li><li><strong>Sûr pour débutants &amp; professionnels :</strong> Le mont Tumpa est réputé pour son climat stable et ses vents doux, ce qui en fait un lieu très sûr pour les débutants comme pour ceux qui souhaitent perfectionner leurs compétences.</li><li><strong>Encadrement professionnel :</strong> Votre sécurité est notre priorité. Vous serez accompagné d\'un instructeur de parapente certifié et équipé de matériel de sécurité aux normes internationales.</li></ul><p><strong>« Ressentez le frisson, admirez la beauté, et rendez votre voyage à Manado vraiment inoubliable ! »</strong></p>', '<ul><li data-list-item-id="ea1013fe641dbc74405bab4a89c5269d4">Instructeur professionnel de parapente</li><li data-list-item-id="e270763c5cc1b5c10062db7e71349a127">Frais d\'entrée aux sites</li><li data-list-item-id="e0c8e90b12db6655ee96a9b9c53a48929">Services de tour selon le programme</li></ul>', '<ul><li data-list-item-id="e09808b568f0f7cf8b77bb2460fbf04c1">Billet d\'avion</li><li data-list-item-id="e7861cd3a295b5e9e7e7e32ec1bb61a65">Voiture (dépose &amp; prise en charge) en option</li><li data-list-item-id="eb8cd71ddf1d59066b0fe144c54b66278">Taxe d\'aéroport</li><li data-list-item-id="e571d4f230715ed2fbe507807bb77544d">Portage&nbsp;</li><li data-list-item-id="e11238ef8ad6bdc98761802c20dafcd49">Hôtel</li><li data-list-item-id="edcff8a0aeff894bd3a8e1024cb208edb">Guide</li><li data-list-item-id="e68946d32764504f4bc586c60286973e8">Pourboire du chauffeur</li><li data-list-item-id="ed0f9917e71858b2d5a6c5bc0a3788568">Excursions optionnelles</li><li data-list-item-id="ea0fb1478644b3360fcfc07c2524c963e">Autres frais hors programme du tour</li></ul>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `inclusions` = VALUES(`inclusions`), `exclusions` = VALUES(`exclusions`), `updated_at` = NOW();

-- paket 15: tarsius-canoe-adventure-highland-sunset
INSERT INTO `tour_translations` (`translatable_type`, `translatable_id`, `locale`, `title`, `description`, `inclusions`, `exclusions`, `created_at`, `updated_at`)
VALUES ('App\\Models\\ManadoTour', '15', 'fr', 'Pirogue des Tarsiers &amp; Coucher de Soleil des Hauts Plateaux', '<h2><strong>Aventure en Pirogue &amp; Crépuscule : Pirogue des Tarsiers &amp; Coucher de Soleil des Hauts Plateaux</strong></h2><p>Découvrez une face cachée des merveilles naturelles du Nord Sulawesi lors d\'un voyage qui mêle exploration sereine des eaux et coucher de soleil à couper le souffle. De l\'observation du plus petit primate du monde au cœur d\'une mangrove à l\'heure dorée admirée depuis les hauts plateaux, ce forfait offre des moments vraiment inoubliables.</p><h3><strong>Points forts du circuit :</strong></h3><ul><li><strong>Exploration de la mangrove en pirogue :</strong> Vivez la tranquillité de glisser sur les eaux cristallines de la <strong>plage de Rap-Rap</strong> à bord d\'une pirogue traditionnelle. Laissez les sons de la nature vous accompagner à travers une mangrove luxuriante et préservée.</li><li><strong>Rencontrer le tarsier dans son habitat naturel :</strong> Profitez d\'une rare occasion d\'observer le <strong>tarsier</strong>, un fascinant petit primate aux grands yeux envoûtants, niché parmi les palétuviers. Vous êtes libre de capturer ces moments magiques autant que vous le souhaitez !</li><li><strong>Coucher de soleil emblématique au mont Tumpa :</strong> Terminez votre journée en admirant le soleil majestueux plonger sous l\'horizon depuis les hauteurs du <strong>mont Tumpa</strong>. Cette vue panoramique sur le littoral et l\'horizon est l\'une des plus belles de Manado.</li><li><strong>Saveurs locales :</strong> En attendant le coucher de soleil, offrez-vous diverses collations traditionnelles de Manado, comme les fameuses bananes frites à la sauce piquante roa ou la glace pilée aux haricots rouges (facultatif).</li></ul><p><strong>« Des mangroves silencieuses aux hauteurs dorées – découvrez l\'âme cachée du Nord Sulawesi. »</strong></p>', '<ul><li data-list-item-id="e7bc9e1165c9336d08f046154ec23b677">Transport climatisé selon le nombre de participants</li><li data-list-item-id="ea7af70bb2a82bcea77255af2e5bee5f8">Guide de mangrove expérimenté et chauffeur</li><li data-list-item-id="eae204140fa5bb1dcce46af8f50941376">Canoë</li><li data-list-item-id="e80f346479d08bc79ba631e2cd3b91eb6">Frais d\'entrée aux sites touristiques&nbsp;</li><li data-list-item-id="e464bfce6ecdcffccb9875ff5346cfc6b">Frais de parking</li><li data-list-item-id="e276d3b05d37581d3fd4159c5dd2f2075">1 bouteille d\'eau minérale par personne</li><li data-list-item-id="e285b78b0ee79f6f91b8f1fc2b17ac847">Services de tour selon le programme</li></ul>', '<ul><li data-list-item-id="e08be48cb4f21a5377ce9748c0ca49109">Billet d\'avion</li><li data-list-item-id="ed90b677285985025078bdb06a9cf6c45">Taxe d\'aéroport</li><li data-list-item-id="ea142622087caa49b2ff7e4c53a07b979">Portage</li><li data-list-item-id="eb25e5a10849163e000f250df28b0b66d">Repas</li><li data-list-item-id="e6afc882721d3368dc426447ed90c3af0">Hôtel</li><li data-list-item-id="edb5d4d26a2cfe5fde84d5a34dde54592">Pourboires guide &amp; chauffeur</li><li data-list-item-id="eab39da60f0dd66cad430d5382fc5acdc">Excursions optionnelles</li><li data-list-item-id="e4ce6a2be042d0929991d5051e57283ca">Autres frais hors programme du tour</li></ul>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `inclusions` = VALUES(`inclusions`), `exclusions` = VALUES(`exclusions`), `updated_at` = NOW();

-- paket 16: tangkoko-nature-reserve-tour-tunan-waterfall
INSERT INTO `tour_translations` (`translatable_type`, `translatable_id`, `locale`, `title`, `description`, `inclusions`, `exclusions`, `created_at`, `updated_at`)
VALUES ('App\\Models\\ManadoTour', '16', 'fr', 'Circuit de la Réserve Naturelle de Tangkoko &amp; Cascade de Tunan', '<h2><strong>Nature &amp; Faune Sauvage : Un Voyage à Tangkoko et Tunan</strong></h2><p>Préparez votre appareil photo et votre esprit d\'aventure ! Ce forfait vous emmène hors des sentiers battus, au cœur d\'une des plus belles zones de conservation d\'Indonésie et de merveilles cachées de cascades. Du plus petit primate du monde au grondement d\'une cascade de 86 mètres de haut, cette expérience sera le point d\'orgue de votre voyage au Nord Sulawesi.</p><h3><strong>Points forts du circuit :</strong></h3><ul><li><strong>La majesté de la cascade de Tunan :</strong> Commencez votre aventure au village de Talawaan. Ressentez la fraîche bruine d\'une cascade de 86 mètres de haut se déversant au cœur d\'une forêt préservée et intacte.</li><li><strong>Rencontrer les habitants originels de Tangkoko :</strong> Explorez la <strong>réserve naturelle de Tangkoko</strong>, refuge d\'une faune endémique unique. Découvrez le <strong>tarsier</strong> (le plus petit primate du monde, aux grands yeux adorables) et le <strong>Yaki</strong> (macaque noir de Sulawesi) évoluant en liberté.</li><li><strong>Une biodiversité foisonnante :</strong> Au-delà des tarsiers, préparez-vous à observer des calaos emblématiques et des couscous dans leur habitat naturel, guidé par des rangers forestiers professionnels.</li><li><strong>Un voyage apaisant :</strong> Profitez d\'un itinéraire pittoresque traversant de charmants petits villages, avec des vues apaisantes sur les vallées et les collines en route vers Bitung.</li></ul><p><strong>« Une rencontre rapprochée avec la nature – découvrez la faune unique et les cascades préservées du Nord Sulawesi. »</strong></p>', '<ul><li data-list-item-id="e3a6d5c7a95824505fcc7169d19c68b06">Transport climatisé selon le nombre de participants</li><li data-list-item-id="ec6d02de779b3cf721615c06630e5b3a2">Ranger à la réserve naturelle de Tangkoko</li><li data-list-item-id="eed59092e3fde448a5e5a4fb756ab6e44">Guide et chauffeur expérimentés</li><li data-list-item-id="e1fbf9e5db829006a3fc211fef7a86ec5">Frais d\'entrée aux sites touristiques</li><li data-list-item-id="ec1827a81cbe7feb5e6c155dc5f41899e">Frais de parking</li><li data-list-item-id="eb65edb1a96b3c032f8f825315f9c7209">Déjeuner</li><li data-list-item-id="e5971d7bd5ebcae0985b7b12074916355">Une bouteille d\'eau minérale par personne</li><li data-list-item-id="ef7e51ca1230476f54d606b374973afb1">Services de tour selon le programme</li></ul>', '<ul><li data-list-item-id="ed1003d6a37aa7b1fbafe39f48ba09598">Billet d\'avion</li><li data-list-item-id="e9101a0e59598b6ff7f1e74ede3ede14f">Taxe d\'aéroport</li><li data-list-item-id="efd4176d12238c02b80f1e80ada630810">Portage</li><li data-list-item-id="ea6ec6622fd640f8ae2aff46bc2e3b6e6">Hôtel,&nbsp;</li><li data-list-item-id="ee0e2b05c5dcca53d84e69986e0eec301">Pourboires pour le guide et le chauffeur</li><li data-list-item-id="e5de631515d01a36e9bf58f056fac2003">Excursions optionnelles</li><li data-list-item-id="eebc3a63adc6760f98d268bc5875c1aac">Tout autre frais hors programme du tour</li></ul>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `inclusions` = VALUES(`inclusions`), `exclusions` = VALUES(`exclusions`), `updated_at` = NOW();

-- paket 17: mt-lokon-volcano-trek
INSERT INTO `tour_translations` (`translatable_type`, `translatable_id`, `locale`, `title`, `description`, `inclusions`, `exclusions`, `created_at`, `updated_at`)
VALUES ('App\\Models\\ManadoTour', '17', 'fr', 'Trekking du Volcan Mont Lokon', '<h2><strong>Explorez le Cratère Actif : L\'Expérience de Trekking du Volcan Mont Lokon</strong></h2><p>Vivez le frisson de l\'ascension d\'un des volcans actifs les plus emblématiques du Nord Sulawesi. Le <strong>mont Lokon</strong> offre une véritable aventure de trekking pour ceux qui souhaitent observer la force brute de la nature à travers son cratère saisissant, sans une ascension trop extrême.</p><h3><strong>Points forts du circuit :</strong></h3><ul><li><strong>Exploration du cratère Tompaluan :</strong> Suivez un sentier de 2 heures menant au bord du <strong>cratère Tompaluan</strong>. Là, vous pourrez observer l\'activité volcanique depuis une distance sûre mais suffisamment proche pour en ressentir toute la grandeur.</li><li><strong>Panorama sur la ville de Tomohon :</strong> Profitez de vues rafraîchissantes sur la ville de Tomohon depuis les flancs de la montagne, offrant une perspective différente sur la beauté naturelle de Minahasa.</li><li><strong>Un défi équilibré :</strong> Situé à 1 580 mètres d\'altitude, le chemin vers le cratère convient aussi bien aux débutants qu\'aux randonneurs expérimentés en quête d\'une activité physique matinale ressourçante.</li><li><strong>Repos &amp; cuisine locale :</strong> Après votre randonnée, un délicieux déjeuner vous attend dans un restaurant local pour conclure parfaitement votre aventure.</li></ul>', '<ul><li data-list-item-id="e9e914bf2ff11c00c2a9db3b87ca22efe">Transport climatisé selon le nombre de participants</li><li data-list-item-id="e680c0b8aea08452cbae884c6d5e2d572">Guide et chauffeur expérimentés</li><li data-list-item-id="ebca155750890997c3be20cf7a2196305">Frais d\'entrée aux sites touristiques</li><li data-list-item-id="e8d8fd8ee171bb996d9ee4419d568d989">Frais de parking</li><li data-list-item-id="e8b60764be181f21f1778af2b47681999">Déjeuner</li><li data-list-item-id="ec2d301ad37ffc7057334aefa9fe2257e">Une bouteille d\'eau minérale par personne</li><li data-list-item-id="e041e6dc48bc42dd9524a3df956c00c0c">Services de tour selon le programme</li></ul>', '<ul><li data-list-item-id="e97188319fb5536c010e7d1ddc597336f">Billet d\'avion</li><li data-list-item-id="e23e09bdcb623c333c317c7b6299f8759">Taxe d\'aéroport</li><li data-list-item-id="e83a0664f8844283c0c4348456a9dfb3b">Portage</li><li data-list-item-id="e1bd92c6b00cb5ea95a1c37639c97543e">Hôtel</li><li data-list-item-id="ef148c59f0c1f718ac34fb13f0e1dbe4a">Pourboires pour le guide et le chauffeur</li><li data-list-item-id="e8cb793f90a845b4dfd6bf1f1b2b42a80">Excursions optionnelles</li><li data-list-item-id="e763128880b466113267e760ee5d194f5">Tout autre frais hors programme du tour.</li></ul>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `inclusions` = VALUES(`inclusions`), `exclusions` = VALUES(`exclusions`), `updated_at` = NOW();

-- paket 18: mt-mahawu-volcano-tetetana-hill
INSERT INTO `tour_translations` (`translatable_type`, `translatable_id`, `locale`, `title`, `description`, `inclusions`, `exclusions`, `created_at`, `updated_at`)
VALUES ('App\\Models\\ManadoTour', '18', 'fr', 'Volcan Mont Mahawu &amp; Colline de Tetetana', '<h2><strong>Les Sommets de Minahasa : Circuit du Mont Mahawu &amp; de la Colline de Tetetana</strong></h2><p>Profitez de la combinaison parfaite entre aventure légère et panoramas naturels extraordinaires. Ce forfait est conçu pour celles et ceux qui souhaitent vivre la sensation d\'être au sommet d\'un volcan et de collines luxuriantes, sans avoir besoin d\'une ascension épuisante.</p><h3><strong>Pourquoi choisir ce circuit ?</strong></h3><ul><li><strong>Randonnée accessible à tous :</strong> Explorez le <strong>mont Mahawu</strong> avec un accès facile. Environ 150 marches cimentées équipées de rambardes de sécurité permettent à chacun d\'atteindre facilement le sommet et d\'admirer son cratère unique.</li><li><strong>Horizon en trois dimensions :</strong> Du sommet du Mahawu, vous serez gratifié de vues spectaculaires sur l\'île de Manado Tua, Bunaken et l\'étendue urbaine de Manado.</li><li><strong>Le charme de la colline de Tetetana :</strong> Visitez le <strong>sommet de Tetetana</strong>, la dernière destination à la mode de Tomohon. Ici, vous pouvez surplomber simultanément quatre régions du Nord Sulawesi depuis un seul point, entouré de magnifiques jardins fleuris et d\'un air frais de montagne.</li><li><strong>Des moments photo esthétiques :</strong> Chaque recoin de ce voyage offre un décor digne d\'Instagram, du chemin d\'escalier verdoyant aux jardins fleuris de la colline.</li><li><strong>Délicieuse cuisine locale :</strong> Ressourcez-vous après l\'exploration avec un authentique déjeuner local dans un restaurant sélectionné.</li></ul>', '<ul><li data-list-item-id="ee0a07c9cb24323f7ce891a99fae8befb">Transport climatisé selon le nombre de participants</li><li data-list-item-id="e2294b9fea85a5bb7b3c381229d996538">Guide et chauffeur expérimentés, frais d\'entrée aux sites touristiques</li><li data-list-item-id="e91b0f8f940b1ae9746f796b2399f0b12">Frais de parking</li><li data-list-item-id="e68c9ac84e6c7d75451eaf1e0bd591748">Déjeuner</li><li data-list-item-id="e1a2d571799de05d946edbf79052260d1">Une bouteille d\'eau minérale par personne</li><li data-list-item-id="eeeb894126a0e2667e1c122b8daf2a097">Services selon le programme</li></ul>', '<ul><li data-list-item-id="ed040cc0dd81d42e795600e22a7bf6536">Billet d\'avion</li><li data-list-item-id="eb2e43bfc1813f79cdda31725bf97dbad">Taxe d\'aéroport</li><li data-list-item-id="eec4c3bc7fb908919a5b66c97cde714e5">Portage</li><li data-list-item-id="ef13b7599a238bc82e6bd5620370064d9">Hôtel</li><li data-list-item-id="e7a50082855dcc93d44a0d8bbcef795bb">Pourboires pour le guide et le chauffeur</li><li data-list-item-id="e2a39ca8ecbefd244e7980a1f24d1bb28">Excursions optionnelles</li><li data-list-item-id="efae7355dae9278ce19d7a043661cdfd1">Autres frais hors programme du tour</li></ul>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `inclusions` = VALUES(`inclusions`), `exclusions` = VALUES(`exclusions`), `updated_at` = NOW();

-- paket 19: white-water-rafting
INSERT INTO `tour_translations` (`translatable_type`, `translatable_id`, `locale`, `title`, `description`, `inclusions`, `exclusions`, `created_at`, `updated_at`)
VALUES ('App\\Models\\ManadoTour', '19', 'fr', 'Rafting en Eaux Vives', '<h2><strong>Défiez les Rapides : Aventure de Rafting sur la Rivière Nimanga</strong></h2><p>Préparez-vous pour l\'aventure aquatique la plus palpitante du Nord Sulawesi ! Naviguez à travers des rapides exigeants, entouré d\'une beauté naturelle à couper le souffle. Ce forfait est parfaitement conçu pour celles et ceux qui recherchent un mélange de défi physique, d\'excitation et de paysages tropicaux luxuriants.</p><h3><strong>Points forts du circuit :</strong></h3><ul><li><strong>Les rapides exigeants de Nimanga :</strong> Vivez le frisson d\'environ 90 minutes de rafting. Chaque méandre de la rivière offre de nouvelles surprises et défis qui feront battre votre cœur plus vite.</li><li><strong>Paysages du village de Timbukar :</strong> Situé à Sonder, le parcours de rafting offre des vues saisissantes sur des falaises abruptes et une végétation dense le long du cours d\'eau préservé.</li><li><strong>La sécurité avant tout :</strong> Avant le départ, vous recevrez un briefing de sécurité et une formation de base à la pagaie. Vous serez accompagné de deux guides de rafting professionnels tout au long du parcours.</li><li><strong>Équipement aux normes internationales :</strong> Nous assurons votre confort et votre sécurité en fournissant un équipement de rafting de haute qualité (bateaux, casques, gilets de sauvetage) conforme aux normes de sécurité internationales.</li></ul><p><strong>« Défiez les rapides, embrassez la nature sauvage, et conquérez la rivière Nimanga avec nous ! »</strong></p>', '<ul><li data-list-item-id="e8f9892615252c1f7113eb1af6758e23d">Transport climatisé selon le nombre de participants</li><li data-list-item-id="ea3a96d847da9f813d56ea1bf5e5091f0">Guide et chauffeur expérimentés</li><li data-list-item-id="e5f704714c2138eff93abd9ef0b451e7c">Équipement de rafting</li><li data-list-item-id="ebef7f400e0d2a286c3753c27ac6b35d5">Frais d\'entrée aux sites touristiques</li><li data-list-item-id="ee7e8a9cdd869251eacb4fee991736ba1">Frais de parking</li><li data-list-item-id="e51ee15f118665b0e2d33ac03bf6150d0">1 bouteille d\'eau minérale par personne</li><li data-list-item-id="e25c6d77eec5df59483c0f7d94f7d0753">Services selon le programme</li></ul>', '<ul><li data-list-item-id="e64a5c48756da8949a84fc99be24bd499">Billet d\'avion</li><li data-list-item-id="e0b3182e85d9f33acc157b85808347961">Taxe d\'aéroport</li><li data-list-item-id="e2cb5bdd5ecfc46fcb144d67bfbd8950f">Repas</li><li data-list-item-id="ef1153321326a82f3288f350ea4e12772">Portage</li><li data-list-item-id="e6657bb1483ae99b0ac50275b9a92fefa">Hôtel</li><li data-list-item-id="e90f5a9e0c8775eae0dd396d234c2ca6e">Pourboires pour le guide et le chauffeur</li><li data-list-item-id="e1bc758f69c0ff547e5c8f8aca100c99e">Excursions optionnelles</li><li data-list-item-id="ed4f1470355a4f65f457a776a07b216c9">Autres frais non mentionnés dans le programme du tour</li></ul>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `inclusions` = VALUES(`inclusions`), `exclusions` = VALUES(`exclusions`), `updated_at` = NOW();

-- paket 20: minahasa-highland-tour
INSERT INTO `tour_translations` (`translatable_type`, `translatable_id`, `locale`, `title`, `description`, `inclusions`, `exclusions`, `created_at`, `updated_at`)
VALUES ('App\\Models\\ManadoTour', '20', 'fr', 'Circuit des Hauts Plateaux de Minahasa', '<h2><strong>Charmes des Hauts Plateaux de Minahasa : Une Harmonie entre Culture &amp; Merveilles Naturelles</strong></h2><p>Échappez au tumulte de la ville et respirez l\'air frais des montagnes lors d\'un voyage d\'une journée complète à travers les hauts plateaux de Minahasa. Des marchés traditionnels uniques aux lacs de soufre apaisants, ce forfait offre un mélange parfait d\'aventure culturelle et de détente en pleine nature que vous ne trouverez nulle part ailleurs.</p><h3><strong>Points forts du circuit :</strong></h3><ul><li><strong>La cité fleurie et colorée :</strong> Régalez vos yeux au <strong>Taman Wisata Pelangi</strong> à Tomohon, un parc vibrant rempli de fleurs multicolores.</li><li><strong>Le marché extrême de Tomohon :</strong> Découvrez la culture locale au cœur de ce marché traditionnel emblématique, célèbre pour sa variété de viandes d\'animaux sauvages — une expérience unique pour les voyageurs du monde entier.</li><li><strong>Patrimoine &amp; délices culinaires :</strong> Observez la préparation en direct de gâteaux traditionnels de Manado et découvrez comment la liqueur locale « Cap Tikus » est fabriquée dans la palmeraie instagrammable de <strong>Tuur Maasering</strong>.</li><li><strong>Détente au bord du lac &amp; Bukit Kasih :</strong> Déjeunez au bord du <strong>lac Tondano</strong>, explorez les cratères de soufre actifs de <strong>Bukit Kasih</strong>, et terminez votre journée avec un café ou un thé chaud au bord des eaux changeantes du <strong>lac Linow</strong>.</li></ul>', '<ul><li data-list-item-id="e3a6d5c7a95824505fcc7169d19c68b06">Transport climatisé selon le nombre de participants</li><li data-list-item-id="eed59092e3fde448a5e5a4fb756ab6e44">Guide et chauffeur expérimentés</li><li data-list-item-id="e1fbf9e5db829006a3fc211fef7a86ec5">Frais d\'entrée aux sites touristiques</li><li data-list-item-id="ec1827a81cbe7feb5e6c155dc5f41899e">Frais de parking</li><li data-list-item-id="eb65edb1a96b3c032f8f825315f9c7209">Déjeuner</li><li data-list-item-id="e5971d7bd5ebcae0985b7b12074916355">Une bouteille d\'eau minérale par personne</li><li data-list-item-id="ef7e51ca1230476f54d606b374973afb1">Services de tour selon le programme</li></ul>', '<ul><li data-list-item-id="ed1003d6a37aa7b1fbafe39f48ba09598">Billet d\'avion</li><li data-list-item-id="e9101a0e59598b6ff7f1e74ede3ede14f">Taxe d\'aéroport</li><li data-list-item-id="efd4176d12238c02b80f1e80ada630810">Portage</li><li data-list-item-id="ea6ec6622fd640f8ae2aff46bc2e3b6e6">Hôtel,&nbsp;</li><li data-list-item-id="ee0e2b05c5dcca53d84e69986e0eec301">Pourboires pour le guide et le chauffeur</li><li data-list-item-id="e5de631515d01a36e9bf58f056fac2003">Excursions optionnelles</li><li data-list-item-id="eebc3a63adc6760f98d268bc5875c1aac">Tout autre frais hors programme du tour</li></ul>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `inclusions` = VALUES(`inclusions`), `exclusions` = VALUES(`exclusions`), `updated_at` = NOW();

-- paket 21: bunaken-island-sightseeing-tour
INSERT INTO `tour_translations` (`translatable_type`, `translatable_id`, `locale`, `title`, `description`, `inclusions`, `exclusions`, `created_at`, `updated_at`)
VALUES ('App\\Models\\ManadoTour', '21', 'fr', 'Circuit d\'Observation de l\'Île de Bunaken', '<h3><strong>Explorez un Paradis Sous-Marin : Forfait Circuit de l\'Île de Bunaken</strong></h3><p>Préparez-vous pour une aventure inoubliable dans le <strong>Parc marin de Bunaken</strong>, l\'une des destinations de tourisme marin les plus emblématiques au monde ! Profitez du mélange parfait entre récifs coralliens éclatants, eaux cristallines et ambiance apaisante de plage.</p><h3><strong>Pourquoi rejoindre ce circuit ?</strong></h3><ul><li><strong>Le nouveau visage de Bunaken :</strong> Visitez le <strong>nouveau quai touristique de Bunaken</strong>, désormais plus charmant et représentatif — le meilleur endroit pour capturer des photos et vidéos esthétiques avec une toile de fond insulaire à couper le souffle.</li><li><strong>Merveilles sous-marines :</strong> Découvrez des milliers d\'espèces de poissons tropicaux et des écosystèmes de récifs coralliens bien préservés grâce à des activités optionnelles de snorkeling ou de plongée.</li><li><strong>Détente au bord de l\'eau :</strong> Profitez de temps libre pour vous promener sur la plage ou simplement vous détendre en respirant l\'air marin frais.</li><li><strong>Déjeuner en bord de mer :</strong> Vivez la sensation d\'un délicieux déjeuner dans un restaurant local situé juste au bord de l\'eau.</li></ul>', '<ul><li data-list-item-id="e756cec54195116ff096865a21781571f"><p style="text-align:justify;">Bateau privé pour l\'île de Bunaken</p></li><li data-list-item-id="e00ba750ae031939e7c8465d501457022"><p style="text-align:justify;">Guide de tour expérimenté &amp; batelier</p></li><li data-list-item-id="ed4121d16075b5d5f88c9d38af15c2a27"><p style="text-align:justify;">Frais d\'entrée aux sites touristiques</p></li><li data-list-item-id="e2332fcb6ed90ad0ae25b1e33e756583a"><p style="text-align:justify;">Déjeuner dans un restaurant local</p></li><li data-list-item-id="ec3c758171f7de84f46c858a794205a03"><p style="text-align:justify;">Une bouteille d\'eau minérale par personne</p></li><li data-list-item-id="e8ced0664ba420cfbfb7f957585b5e359"><p style="text-align:justify;">Services de tour selon l\'itinéraire</p></li></ul>', '<ul><li data-list-item-id="e64a5c48756da8949a84fc99be24bd499">Billet d\'avion</li><li data-list-item-id="eeec1cfc460047b34d98ccaa46e7a7e79">Transport terrestre (voiture)</li><li data-list-item-id="e0b3182e85d9f33acc157b85808347961">Taxe d\'aéroport</li><li data-list-item-id="e2cb5bdd5ecfc46fcb144d67bfbd8950f">Repas</li><li data-list-item-id="ef1153321326a82f3288f350ea4e12772">Portage</li><li data-list-item-id="e6657bb1483ae99b0ac50275b9a92fefa">Hôtel</li><li data-list-item-id="e90f5a9e0c8775eae0dd396d234c2ca6e">Pourboires pour le guide et le chauffeur</li><li data-list-item-id="e1bc758f69c0ff547e5c8f8aca100c99e">Excursions optionnelles</li><li data-list-item-id="ed4f1470355a4f65f457a776a07b216c9">Autres frais non mentionnés dans le programme du tour</li></ul>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `inclusions` = VALUES(`inclusions`), `exclusions` = VALUES(`exclusions`), `updated_at` = NOW();

-- paket 22: manado-city-tour-luch-with-manados-special-dishes
INSERT INTO `tour_translations` (`translatable_type`, `translatable_id`, `locale`, `title`, `description`, `inclusions`, `exclusions`, `created_at`, `updated_at`)
VALUES ('App\\Models\\ManadoTour', '22', 'fr', 'Circuit de la Ville de Manado &amp; Déjeuner aux Plats Spéciaux de Manado', '<h2><strong>Explorez les Charmes de Manado : Un Voyage entre Histoire, Saveurs et Horizon</strong></h2><p>Vivez un voyage d\'une journée complète à travers le temps et la nature au cœur du Nord Sulawesi. Notre <strong>circuit de la ville de Manado</strong> vous invite à plonger dans un riche patrimoine culturel parfaitement mêlé à des panoramas majestueux depuis les sommets.</p><h3><strong>Points forts du circuit :</strong></h3><ul><li><strong>Sites historiques &amp; culturels :</strong> Visitez le <strong>temple Ban Hin Kiong</strong>, un site historique tricentenaire, ainsi que l\'<strong>église Sentrum</strong> et le <strong>Monument de la Seconde Guerre mondiale</strong>.</li><li><strong>Merveilles emblématiques :</strong> Admirez la grandeur du <strong>Monument de Jésus Bénissant</strong>, une statue « volante » unique qui sert de symbole à la ville.</li><li><strong>Saveurs authentiques :</strong> Régalez votre palais d\'un déjeuner traditionnel de <strong>thon à la manadaise</strong>, riche en épices locales.</li><li><strong>Hauteurs à couper le souffle :</strong> Terminez votre journée à la <strong>colline de Makatete</strong>. Depuis 200 mètres d\'altitude, profitez de vues spectaculaires sur la ville de Manado, le mont Klabat et les magnifiques îles de Bunaken et Siladen.</li></ul>', '<ul><li data-list-item-id="efa0326736a93dbe5b6f2f4886719f0ae"><p style="text-align:justify;">Transport climatisé selon le nombre de participants</p></li><li data-list-item-id="e6f7c213ce63967da3a7674f798318146"><p style="text-align:justify;">Guide expérimenté (parlant anglais) &amp; chauffeur</p></li><li data-list-item-id="e31e949b88b66a13c31a285d2ea0fe01b"><p style="text-align:justify;">Frais d\'entrée &amp; frais de parking</p></li><li data-list-item-id="e5d9e0c346d759e5a38f90442bd7731c9"><p style="text-align:justify;">Déjeuner dans un restaurant local</p></li><li data-list-item-id="e7b7a00f1ee67b67ec041223e00f34a09"><p style="text-align:justify;">Une bouteille d\'eau minérale par personne</p></li><li data-list-item-id="e364d522edd138b4fa0906d7379169caa"><p style="text-align:justify;">Services de tour selon le programme</p></li></ul>', '<ul><li data-list-item-id="e64a5c48756da8949a84fc99be24bd499">Billet d\'avion</li><li data-list-item-id="e0b3182e85d9f33acc157b85808347961">Taxe d\'aéroport</li><li data-list-item-id="e2cb5bdd5ecfc46fcb144d67bfbd8950f">Repas</li><li data-list-item-id="ef1153321326a82f3288f350ea4e12772">Portage</li><li data-list-item-id="e6657bb1483ae99b0ac50275b9a92fefa">Hôtel</li><li data-list-item-id="e90f5a9e0c8775eae0dd396d234c2ca6e">Pourboires pour le guide et le chauffeur</li><li data-list-item-id="e1bc758f69c0ff547e5c8f8aca100c99e">Excursions optionnelles</li><li data-list-item-id="ed4f1470355a4f65f457a776a07b216c9">Autres frais non mentionnés dans le programme du tour</li></ul>', NOW(), NOW())
