-- paket 23: 6d5n-tangkoko-adventure-tour
INSERT INTO `tour_translations` (`translatable_type`, `translatable_id`, `locale`, `title`, `description`, `inclusions`, `exclusions`, `created_at`, `updated_at`)
VALUES ('App\\Models\\ManadoTour', '23', 'fr', '6 Jours Circuit Aventure de Tangkoko', '<h2><strong>L\'Odyssée Ultime du Nord Sulawesi : Une Grande Aventure de 6 Jours à travers les Forêts Tropicales &amp; les Paradis Sous-Marins</strong></h2><p>Explorez le côté sauvage et magnifique du Nord Sulawesi avec notre forfait d\'expédition le plus complet ! L\'<strong>aventure 6J/5N à Tangkoko</strong> est bien plus que des vacances ; c\'est un voyage épique combinant merveilles terrestres, hauts plateaux majestueux et la beauté marine mondialement renommée de Bunaken. Conçu pour celles et ceux en quête d\'une aventure authentique, sans limites.</p><h3><strong>Points forts du circuit :</strong></h3><ul><li><strong>Expédition dans la jungle de Tangkoko :</strong> Passez deux nuits au cœur de Tangkoko dans une quête pour observer une faune rare — du charmant <strong>tarsier</strong> aux troupes exclusives de <strong>macaques noirs à crête</strong>.</li><li><strong>La merveille de la cascade de Tunan :</strong> Assistez à la force brute de la nature au pied d\'une cascade de 86 mètres, cachée au cœur d\'une forêt préservée et intacte.</li><li><strong>Charmes des hauts plateaux de Minahasa :</strong> Respirez l\'air frais de Tomohon, explorez le cratère du <strong>volcan Mahawu</strong>, et trouvez la sérénité au <strong>lac Linow</strong>, célèbre pour ses eaux changeant de trois couleurs.</li><li><strong>Un héritage culturel ancestral :</strong> Remontez le temps avec une visite de <strong>Waruga Sawangan</strong>, un ancien site de tombeaux megalithiques riche en histoire.</li><li><strong>Paradis marin de Bunaken :</strong> Concluez votre voyage par une détente totale sur l\'île de Bunaken. Faites du snorkeling ou de la plongée parmi des murs de corail géants et des milliers de poissons tropicaux éclatants.</li></ul>', '<ul><li data-list-item-id="e003cb081df381c6177f6f6ea22e70670">Transport climatisé&nbsp;</li><li data-list-item-id="e0d5c6e19f840ce309c7c0f35dcfac3f4">Bateau privé pour l\'île de Bunaken</li><li data-list-item-id="e4364960109bee572d3a8d9cae7ce2e96">Séjour de 5 nuits à l\'hôtel, occupation double</li><li data-list-item-id="e406c6b2a303d8fc371e9e36db30336f9">Guide expérimenté &amp; chauffeur</li><li data-list-item-id="ea83df9e88b4d60410713905d99b0773e">Billets d\'entrée aux sites touristiques &amp; frais de parking</li><li data-list-item-id="ea0513d38795aacb231a0d76a6e389665">Repas selon le programme du tour</li><li data-list-item-id="e1d347a24ac609ef4c151d1e191962bad">Services de tour selon le programme</li><li data-list-item-id="e03a02e72cc81325190c8b5844feec80c">Une bouteille d\'eau minérale par personne et par jour</li><li data-list-item-id="e38650055baf01af92b30e8be7c0377e6">Service d\'accueil</li></ul>', '<ul><li data-list-item-id="eb5eba377a627536111f5daaf42cb875e">Billet d\'avion aller-retour</li><li data-list-item-id="e9871e63b9fbb46e8e849ba04f66112b4">Pourboires pour le guide &amp; le chauffeur</li><li data-list-item-id="e141f97d4f43b25648e15d80a691fd2d7">Excursions optionnelles</li><li data-list-item-id="ecbb5c50e20d10d1311cd91fb730a72f6">Frais supplémentaires hors forfait (repas/boissons supplémentaires, etc.)</li><li data-list-item-id="ed9e6b7e4a9ad9f99209d34216e79ff72">Portage, taxe d\'aéroport &amp; excédent de bagages</li><li data-list-item-id="ee8836b89a60e07a22d2e2038bc73b07d">Dépenses personnelles (blanchisserie, minibar, service en chambre, etc.)</li><li data-list-item-id="e5dda5c1a16091383138fef6dd26df6ee">Assurance voyage</li><li data-list-item-id="ed1693c3ccea40a446251d042c65b75e9">Autres frais hors programme du tour</li></ul>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `inclusions` = VALUES(`inclusions`), `exclusions` = VALUES(`exclusions`), `updated_at` = NOW();

-- paket 24: tangkoko-adventure-4d3n
INSERT INTO `tour_translations` (`translatable_type`, `translatable_id`, `locale`, `title`, `description`, `inclusions`, `exclusions`, `created_at`, `updated_at`)
VALUES ('App\\Models\\ManadoTour', '24', 'fr', '4 Jours Aventure de Tangkoko', '<h2><strong>L\'Expédition Ultime de Tangkoko : Une Grande Aventure de 4 Jours dans les Terres Sauvages de Sulawesi</strong></h2><p>Êtes-vous prêt pour votre propre expérience « National Geographic » ? L\'<strong>aventure 4J/3N à Tangkoko</strong> est un voyage immersif qui vous emmène au cœur de la forêt tropicale préservée à la rencontre de certaines des créatures les plus uniques de la planète. Du grondement de cascades cachées au regard de l\'emblématique tarsier, cette aventure est un rêve pour tout amoureux de la nature et tout photographe.</p><h3><strong>Points forts du circuit :</strong></h3><ul><li><strong>La merveille de la cascade de Tunan :</strong> Débutez votre voyage à la cascade de Tunan, au village de Talawan. Ressentez la fraîche bruine d\'une cascade de 86 mètres nichée au cœur d\'une forêt préservée et intacte.</li><li><strong>À la recherche de « la grande star » :</strong> Partez pour une randonnée en fin d\'après-midi à la recherche de la star principale du parc : le <strong>tarsier</strong>, le plus petit primate du monde, qui n\'apparaît qu\'au coucher du soleil.</li><li><strong>Exploration de la faune endémique :</strong> Passez suffisamment de temps dans la réserve naturelle de Tangkoko pour observer le <strong>macaque noir à crête</strong>, les couscous et la plus forte densité de calaos au monde.</li><li><strong>Expédition en jungle profonde :</strong> Avec une durée de 4 jours, vous avez toutes les chances d\'explorer les recoins cachés de la forêt lors de randonnées matinales et en fin d\'après-midi guidées par des experts.</li><li><strong>Une vie de village authentique :</strong> Vivez une véritable hospitalité locale lors d\'un séjour au village de Batu Putih, offrant un repos paisible bercé par les sons de la nature.</li></ul>', '<ul><li data-list-item-id="ef32c0bfe5795561b9ab193cd44c60a01">Transport climatisé selon le nombre de participants</li><li data-list-item-id="e8b6758ced173cafd33eeb47088587315">2 nuits à Tangkoko &amp; 1 nuit à Tomohon (lit double/twin)</li><li data-list-item-id="e3b802aad9f6aaa8677df1b6542b2b753">Chauffeur &amp; guide expérimentés</li><li data-list-item-id="e0430266106efc4c83295f481a66a272e">Ranger du parc naturel de Tangkoko</li><li data-list-item-id="e6263d3892d15802d1cdbba1e1483fc4b">Billets d\'entrée aux sites &amp; frais de parking</li><li data-list-item-id="e41e80b8e04edeabc44a8949d6f46e507">Repas selon l\'itinéraire du tour</li><li data-list-item-id="e9424305b5471b1307a625f1e394473d3">Services de tour selon le programme</li><li data-list-item-id="e5160d2919b1850eff838c550505ea428">2 bouteilles d\'eau minérale par jour</li><li data-list-item-id="e7c5227391081bd816bd247709adc2fb1">Service d\'accueil</li></ul>', '<ul><li data-list-item-id="eab8e19d9005d7b92a3b55f83e6c406d5">Billet d\'avion aller-retour</li><li data-list-item-id="ec89859e61ce5257e8ce597e8b9ed8f95">Pourboires chauffeur &amp; guide</li><li data-list-item-id="eef1817701ed7d1b37d70094c2cf03414">Excursions optionnelles</li><li data-list-item-id="ecc81655adf3b9e759353573a80d75f4b">Frais hors forfait (repas/boissons supplémentaires, etc.)</li><li data-list-item-id="e36914624471dc30595049484fcb9c27e">Portage, taxe d\'aéroport &amp; excédent de bagages</li><li data-list-item-id="e0d1bbfc33f8e55265033264d9643f777">Dépenses personnelles (blanchisserie, minibar, service en chambre, etc.)</li><li data-list-item-id="e581cc90534790d4f6be55537e1415302">Assurance voyage</li><li data-list-item-id="ee3f094b58737eb29f43eb8a3427ef690">Et autres frais hors programme du tour</li></ul>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `inclusions` = VALUES(`inclusions`), `exclusions` = VALUES(`exclusions`), `updated_at` = NOW();

-- paket 25: tangkoko-adventure-3d2n
INSERT INTO `tour_translations` (`translatable_type`, `translatable_id`, `locale`, `title`, `description`, `inclusions`, `exclusions`, `created_at`, `updated_at`)
VALUES ('App\\Models\\ManadoTour', '25', 'fr', '3 Jours Aventure de Tangkoko', '<h2><strong>Odyssée Faune Sauvage &amp; Volcan : Un Voyage Épique de 3 Jours au Cœur de Tangkoko</strong></h2><p>Préparez votre âme d\'aventurier pour un voyage profond au cœur d\'une des réserves naturelles les plus uniques au monde ! Le forfait <strong>3J/2N Tangkoko Adventure</strong> est conçu pour les véritables amoureux de la nature souhaitant observer une faune endémique rare dans son habitat naturel, tout en profitant de la majesté des cratères volcaniques et du savoir culturel de Minahasa.</p><h3><strong>Points forts du circuit :</strong></h3><ul><li><strong>Le sommet du cratère Mahawu :</strong> Profitez d\'une courte randonnée de 10 minutes jusqu\'au bord du mont Mahawu pour admirer des panoramas spectaculaires sur Tomohon, Manado et les îles environnantes.</li><li><strong>Merveilles de la faune endémique :</strong> Entrez dans la réserve naturelle de Tangkoko à la rencontre du <strong>tarsier</strong> (le plus petit primate du monde), du <strong>macaque noir à crête</strong> (singe noir endémique), des couscous et de divers oiseaux exotiques comme les calaos.</li><li><strong>Détente au lac tricolore :</strong> Détendez-vous au bord du lac Linow, célèbre pour ses eaux changeant de couleur, tout en savourant un après-midi paisible avec un café ou un thé.</li><li><strong>Sur les traces du patrimoine de Minahasa :</strong> Visitez le village de Woloan, célèbre pour ses maisons en bois traditionnelles démontables, et découvrez les anciens tombeaux megalithiques de Waruga Sawangan.</li><li><strong>Un séjour au cœur de la nature :</strong> Vivez une nuitée authentique dans la région de Tangkoko, vous offrant un accès privilégié à la faune foisonnante de la forêt tropicale de Sulawesi.</li></ul>', '<ul><li data-list-item-id="eb8cd28a724737ab44cc88dd97a389dbe">Transport climatisé selon le nombre de participants</li><li data-list-item-id="e9bac968587895ffae01f8d49356df8d4">2 nuits à Tangkoko (lit double/twin)</li><li data-list-item-id="e48aac6bce52fc7428359e501ff729bba">Chauffeur &amp; guide expérimentés</li><li data-list-item-id="ed9fed75b7d0562e8bdb0b2bc32232277">Ranger du parc naturel de Tangkoko</li><li data-list-item-id="efc3381224ecde3190b545ad3376102fe">Billets d\'entrée aux sites &amp; frais de parking</li><li data-list-item-id="e41e80b8e04edeabc44a8949d6f46e507">Repas selon le programme</li><li data-list-item-id="e6d5acca76e2686e9f57b3b7b6aaf5f65">Services de tour selon le programme</li><li data-list-item-id="ef45128991ca24a9ae216cd6a2ce70a4a">2 bouteilles d\'eau minérale par jour</li><li data-list-item-id="ea837f120d87ebda8df3ec40c685d6f66">Service d\'accueil</li></ul>', '<ul><li data-list-item-id="e6b416fd5c6f77881ce45c46173dd1108">Billet d\'avion aller-retour</li><li data-list-item-id="ee0319e1248ebd87095dad0bfd8c7d9c9">Pourboires chauffeur &amp; guide</li><li data-list-item-id="eb78e7ef31eabb5138ac00798e975cc2f">&nbsp;Excursion optionnelle</li><li data-list-item-id="e7da4c8edc74e8fafda56c7e6740a2611">Frais hors forfait (repas/boissons supplémentaires, etc.)</li><li data-list-item-id="ed04c16639d33ef42e9159fc2d3d121c5">Portage, taxe d\'aéroport &amp; excédent de bagages</li><li data-list-item-id="eefc6702e5083bfaff7b21c733acbf043">Dépenses personnelles (blanchisserie, minibar, service en chambre, etc.)</li><li data-list-item-id="e0f2b3f55047546e4fdbba7daadab0de1">Assurance voyage</li><li data-list-item-id="ecc2d015d15e7b1ce5bbbd590e43ce691">Et autres frais hors programme du tour</li></ul>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `inclusions` = VALUES(`inclusions`), `exclusions` = VALUES(`exclusions`), `updated_at` = NOW();

-- paket 26: island-hopping-paradise-bunaken-siladen-nain-escape
INSERT INTO `tour_translations` (`translatable_type`, `translatable_id`, `locale`, `title`, `description`, `inclusions`, `exclusions`, `created_at`, `updated_at`)
VALUES ('App\\Models\\ManadoTour', '26', 'fr', 'Paradis d\'Île en Île : Évasion à Bunaken, Siladen &amp; Nain', '<h2 style="text-align:justify;"><strong>Paradis d\'Île en Île : Évasion à Bunaken, Siladen &amp; Nain&nbsp;</strong></h2><p style="text-align:justify;">Évadez-vous vers le paradis tropical du Nord Sulawesi et vivez une aventure inoubliable d\'île en île.<br>Découvrez la beauté mondialement connue du <strong>Parc marin de Bunaken</strong>, avec ses eaux cristallines, ses récifs coralliens colorés et des milliers de poissons tropicaux nageant autour de vous.</p><p style="text-align:justify;">Poursuivez l\'exploration de la beauté paisible de l\'<strong>île de Siladen</strong>, entourée de superbes vues sur l\'océan bleu et d\'une ambiance tropicale relaxante.<br>Puis découvrez la beauté unique du <strong>banc de sable de Nain</strong> — un paradis caché de sable blanc en pleine mer qui apparaît à marée basse et devient le spot photo esthétique par excellence.</p><p style="text-align:justify;">Bien plus qu\'une simple excursion, vous pourrez également faire du snorkeling, de la plongée, nager en nourrissant les poissons directement à la main, et vous imprégner de l\'ambiance tropicale insulaire ultime.</p><p style="text-align:justify;">Pourquoi choisir ce voyage ?<br>Parce qu\'en un seul périple, vous vivrez la combinaison parfaite entre :<br><strong>eau cristalline + îles tropicales + paradis sous-marin + vues sur le sable blanc + expériences marines inoubliables</strong>, réunies en une évasion à la fois relaxante et palpitante.</p><p style="text-align:justify;">Parfait pour vous si vous recherchez :</p><ul><li><p style="text-align:justify;">Une escapade tropicale esthétique</p></li><li><p style="text-align:justify;">Des expériences de snorkeling &amp; d\'île en île</p></li><li><p style="text-align:justify;">Un océan bleu limpide et une ambiance de ressourcement absolu</p></li></ul><h3 style="text-align:justify;"><strong>Eau bleue. Sable blanc. Ambiance tropicale infinie.</strong>&nbsp;</h3><p style="text-align:justify;">Prêt à explorer le plus beau paradis marin de Manado ?</p>', '<ul><li data-list-item-id="e873d778fd1724e641963f19753bd7153">Bateau privé pour 3 îles</li><li data-list-item-id="e7f8a545844508ac34789fff54c3bf4ec">Guide de tour expérimenté &amp; batelier</li><li data-list-item-id="e837639ed702b4b3d563d754b9784f201">Frais d\'entrée aux sites touristiques</li><li data-list-item-id="eb3047ce26dd07cba53731a349833c934">Frais de parking</li><li data-list-item-id="e17952c91bc59d3bf5bd394db5c31eba2">Déjeuner</li><li data-list-item-id="e8b809428954656d954fcd1a9e186a600">1 bouteille d\'eau minérale par personne</li><li data-list-item-id="e8b6d227b6ff4563e99f57d10b0c0fa1b">Services de tour selon l\'itinéraire</li></ul>', '<ul><li data-list-item-id="e8b156627fb0192d631973d4400759fd2">Transport terrestre (voiture)&nbsp;</li><li data-list-item-id="e64a5c48756da8949a84fc99be24bd499">Billets d\'avion aller-retour</li><li data-list-item-id="e0b3182e85d9f33acc157b85808347961">Taxe d\'aéroport</li><li data-list-item-id="e2cb5bdd5ecfc46fcb144d67bfbd8950f">Repas</li><li data-list-item-id="ef1153321326a82f3288f350ea4e12772">Portage</li><li data-list-item-id="e6657bb1483ae99b0ac50275b9a92fefa">Hôtel</li><li data-list-item-id="e90f5a9e0c8775eae0dd396d234c2ca6e">Pourboires pour le guide et le chauffeur</li><li data-list-item-id="e1bc758f69c0ff547e5c8f8aca100c99e">Excursions optionnelles</li><li data-list-item-id="ed4f1470355a4f65f457a776a07b216c9">Autres frais non mentionnés dans le programme du tour</li></ul>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `inclusions` = VALUES(`inclusions`), `exclusions` = VALUES(`exclusions`), `updated_at` = NOW();

-- paket 27: mount-soputan-trekking-experience
INSERT INTO `tour_translations` (`translatable_type`, `translatable_id`, `locale`, `title`, `description`, `inclusions`, `exclusions`, `created_at`, `updated_at`)
VALUES ('App\\Models\\ManadoTour', '27', 'fr', 'Expérience de Trekking au Mont Soputan', '<h2 style="text-align:justify;">Aventure de Trekking au Volcan Mont Soputan</h2><p style="text-align:justify;">Vivez le frisson d\'explorer l\'un des paysages volcaniques les plus spectaculaires du Nord Sulawesi, lors d\'une aventure qui vous emmène bien au-delà des sentiers touristiques habituels. Entouré d\'une nature intacte, de reliefs montagneux saisissants et de panoramas à couper le souffle, ce voyage offre une expérience de plein air véritablement authentique pour celles et ceux en quête de nature, d\'aventure et de découverte.</p><p style="text-align:justify;">À mesure que vous vous enfoncez dans les hauts plateaux, vous découvrirez une combinaison fascinante de forêts tropicales, de vastes paysages ouverts et d\'un relief volcanique escarpé, façonné par des siècles d\'activité géologique. Le paysage en perpétuel changement crée un sentiment d\'exploration et d\'excitation, faisant de chaque pas une partie de l\'aventure.</p><p style="text-align:justify;">Ce qui rend cette expérience véritablement spéciale, c\'est l\'occasion d\'assister à la force brute et à la beauté d\'un volcan actif, tout en profitant de certaines des vues de montagne les plus impressionnantes du Nord Sulawesi. Loin des destinations touristiques bondées, le mont Soputan offre une évasion paisible et gratifiante pour les voyageurs qui apprécient la nature dans sa forme la plus pure.</p><p style="text-align:justify;">Que vous soyez un passionné d\'aventure, un photographe, ou simplement à la recherche d\'une expérience de plein air unique, ce trekking promet des souvenirs inoubliables et des paysages extraordinaires que peu de visiteurs ont la chance de vivre.</p><h3 style="text-align:justify;">Pourquoi Vous Allez Adorer ce Circuit</h3><p style="text-align:justify;">✅ Faites l\'ascension d\'un des volcans actifs les plus emblématiques du Nord Sulawesi<br>✅ Profitez de panoramas spectaculaires sur les montagnes, les vallées et les paysages volcaniques<br>✅ Découvrez des terrains variés, entre forêts tropicales, prairies et champs de lave<br>✅ Parfait pour les amateurs d\'aventure, les amoureux de la nature et les photographes<br>✅ Échappez à la foule et découvrez un joyau naturel caché<br>✅ Une des expériences de trekking les plus gratifiantes du Nord Sulawesi</p><h3 style="text-align:justify;"><strong>Si vous recherchez un voyage qui combine aventure, accomplissement et beauté naturelle à couper le souffle, le mont Soputan offre une expérience inoubliable dans l\'un des environnements volcaniques les plus remarquables d\'Indonésie.</strong></h3>', '<ul><li data-list-item-id="ebd5f16f959211ad8d39562d748703cf6"><p style="text-align:justify;">Transport climatisé selon le nombre de participants</p></li><li data-list-item-id="ebd2a4a0200f3a42f13270b474708c55f"><p style="text-align:justify;">Guide et chauffeur expérimentés</p></li><li data-list-item-id="ea5540f1e4a6b85032cac1556af6c1e67"><p style="text-align:justify;">Frais d\'entrée aux sites touristiques</p></li><li data-list-item-id="ea7600709e3961af862f436ab5c48d340"><p style="text-align:justify;">Frais de parking &amp; de don&nbsp;</p></li><li data-list-item-id="e768ef758df3cfe68e0bef8f3aa45bebf"><p style="text-align:justify;">Une bouteille d\'eau minérale par personne&nbsp;</p></li><li data-list-item-id="e1f5a44dadf559c86177cde9fc918bc0b"><p style="text-align:justify;">Services de tour selon le programme</p></li></ul>', '<ul><li data-list-item-id="e64a5c48756da8949a84fc99be24bd499">Billet d\'avion</li><li data-list-item-id="e0b3182e85d9f33acc157b85808347961">Taxe d\'aéroport</li><li data-list-item-id="e2cb5bdd5ecfc46fcb144d67bfbd8950f">Repas</li><li data-list-item-id="ef1153321326a82f3288f350ea4e12772">Portage</li><li data-list-item-id="e6657bb1483ae99b0ac50275b9a92fefa">Hôtel</li><li data-list-item-id="e90f5a9e0c8775eae0dd396d234c2ca6e">Pourboires pour le guide et le chauffeur</li><li data-list-item-id="e1bc758f69c0ff547e5c8f8aca100c99e">Excursions optionnelles</li><li data-list-item-id="ed4f1470355a4f65f457a776a07b216c9">Autres frais non mentionnés dans le programme du tour</li></ul>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `inclusions` = VALUES(`inclusions`), `exclusions` = VALUES(`exclusions`), `updated_at` = NOW();

-- paket 28: 4-days-paradise-golf-lihaga-island-escape
INSERT INTO `tour_translations` (`translatable_type`, `translatable_id`, `locale`, `title`, `description`, `inclusions`, `exclusions`, `created_at`, `updated_at`)
VALUES ('App\\Models\\ManadoTour', '28', 'fr', '4 Jours Golf Paradis &amp; Évasion à l\'Île de Lihaga', '<h2 style="text-align:justify;">La Combinaison Parfaite entre Golf, Loisirs Insulaires et Détente Tropicale</h2><p style="text-align:justify;">Découvrez le meilleur du Nord Sulawesi lors d\'un voyage unique combinant golf de championnat, paysages insulaires préservés et hospitalité tropicale relaxante. Conçu pour les voyageurs recherchant plus qu\'un simple séjour golfique, ce forfait offre l\'équilibre parfait entre détente, nature et loisirs.</p><p style="text-align:justify;">Passez vos journées à profiter d\'un golf de qualité entouré de paysages tropicaux luxuriants et de brises marines rafraîchissantes, puis échappez-vous vers la beauté spectaculaire de l\'île de Lihaga, un paradis caché célèbre pour son sable blanc poudreux, ses eaux cristallines et son atmosphère paisible.</p><p style="text-align:justify;">Loin des destinations touristiques bondées, cette expérience vous permet de ralentir et d\'apprécier la beauté naturelle du Nord Sulawesi à votre propre rythme. Que vous soyez sur un parcours de golf pittoresque, en train de vous détendre sur la plage, de nager dans des eaux turquoise, ou simplement de profiter du confort du complexe, chaque instant est pensé pour ressourcer le corps et l\'esprit.</p><p style="text-align:justify;">Bien plus qu\'un simple forfait golf, ce voyage offre une évasion tropicale complète où sport, détente et aventure insulaire se rencontrent en une expérience inoubliable.</p><h3 style="text-align:justify;">Pourquoi Vous Allez Adorer ce Forfait</h3><p style="text-align:justify;">• Profitez d\'une combinaison unique entre golf et évasion insulaire</p><p style="text-align:justify;">• Jouez au golf dans un cadre tropical magnifique entouré de nature</p><p style="text-align:justify;">• Visitez les superbes plages de sable blanc de l\'île de Lihaga</p><p style="text-align:justify;">• Détendez-vous dans des eaux cristallines loin des zones touristiques bondées</p><p style="text-align:justify;">• Séjournez dans un complexe confortable au cadre paisible</p><p style="text-align:justify;">• Vivez des attractions terrestres et marines en un seul forfait</p><p style="text-align:justify;">• Découvrez une des plus belles destinations insulaires du Nord Sulawesi</p><p style="text-align:justify;">• Créez des souvenirs inoubliables dans un paradis tropical</p><h3 style="text-align:justify;">Points Forts du Circuit</h3><p style="text-align:justify;">• 3 nuits au Paradise Hotel &amp; Golf Resort</p><p style="text-align:justify;">• Expérience de golf 18 trous</p><p style="text-align:justify;">• Excursion en bateau privé vers l\'île de Lihaga</p><p style="text-align:justify;">• Escapade sur une plage de sable blanc</p><p style="text-align:justify;">• Eaux tropicales cristallines</p><p style="text-align:justify;">• Déjeuner de fruits de mer locaux frais</p><p style="text-align:justify;">• Transferts aéroport aller-retour inclus</p><p style="text-align:justify;">• Activités marines &amp; snorkeling en option</p><h3 style="text-align:justify;"><strong>Vivez le mélange parfait entre golf, détente et beauté insulaire tropicale. Des fairways luxuriants aux plages de sable blanc immaculées, chaque jour offre une nouvelle façon de profiter du charme naturel du Nord Sulawesi.</strong></h3>', '<ul><li data-list-item-id="e85fcfeb6216e5a3f9b99dd3a6a7c929c">Transfert aéroport</li><li data-list-item-id="e8de14905ae06a64f87cc60b7707f22d0">3 nuits d\'hébergement à l\'hôtel sélectionné – chambre twin/double</li><li data-list-item-id="eb71e5d213f9c14a6db516ba2d4f3f038">Green fee le jour 2</li><li data-list-item-id="ed12068b91276f3e93b42223230f12673">Voiturette de golf et frais de caddie (pourboire caddie exclu) le jour 2</li><li data-list-item-id="ed97e52152f7c86010c43d5fde2101b87">Bateau privé pour l\'île de Lihaga</li><li data-list-item-id="ec02237fe232f55cc706fb1297ad87fad">Frais d\'entrée aux sites touristiques &amp; frais de parking</li><li data-list-item-id="e54ee6c6a6a0738fa1e15a08e280faef7">Guide de tour professionnel le jour 3</li><li data-list-item-id="e4bb6b6d5246389f96275d7a9a8a82136">Repas selon le programme</li></ul>', '<ul><li data-list-item-id="e3b523e8375ebb8c9d79946b95b626000">Billet d\'avion aller-retour</li><li data-list-item-id="ebb59df0fa48ba937a21926c9d7e1f3dd">Pourboires pour le guide &amp; le chauffeur</li><li data-list-item-id="e3ce39bff4df98057a82869976df231d7">Excursions optionnelles</li><li data-list-item-id="e3f219b92323c9770103f518bec22b1ba">Dépenses personnelles hors forfait (repas/boissons supplémentaires, etc.)</li><li data-list-item-id="e11ba73fd8e73eef138f3ca4ad9edebf4">Service de portage, taxe d\'aéroport &amp; frais de surpoids</li><li data-list-item-id="ec1219e9200318981e942067b191d0e19">Dépenses personnelles (blanchisserie, minibar, service en chambre, etc.)</li><li data-list-item-id="eeb6d510ef8ff5842d69e6e91a30b5aa4">Assurance voyage</li><li data-list-item-id="e0bf84136b233377c9c534be5adbe9757">Autres frais non mentionnés dans le programme du tour</li></ul>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `inclusions` = VALUES(`inclusions`), `exclusions` = VALUES(`exclusions`), `updated_at` = NOW();

-- paket 29: 4-days-paradise-golf-bunaken-escape
INSERT INTO `tour_translations` (`translatable_type`, `translatable_id`, `locale`, `title`, `description`, `inclusions`, `exclusions`, `created_at`, `updated_at`)
VALUES ('App\\Models\\ManadoTour', '29', 'fr', '4 Jours Golf Paradis &amp; Évasion à Bunaken', '<h2 style="text-align:justify;">Découvrez le Meilleur Golf et Paradis Marin du Nord Sulawesi</h2><p style="text-align:justify;">Vivez le mélange parfait entre golf de championnat, détente tropicale et beauté marine mondialement renommée en un seul voyage inoubliable. Conçu pour les voyageurs en quête de plus qu\'un séjour traditionnel, ce forfait combine l\'élégance d\'un complexe de golf haut de gamme avec les merveilles naturelles à couper le souffle de l\'île de Bunaken.</p><p style="text-align:justify;">Niché le long du magnifique littoral du Nord Sulawesi, le Paradise Golf Resort offre une atmosphère relaxante où des fairways luxuriants rencontrent des vues océaniques rafraîchissantes. Profitez d\'une expérience de golf mémorable entourée de paysages tropicaux, d\'un cadre paisible et de l\'hospitalité chaleureuse qui fait du Nord Sulawesi une destination privilégiée pour les voyageurs de loisirs.</p><p style="text-align:justify;">Le voyage se poursuit vers la légendaire île de Bunaken, refuge de certains des paysages côtiers et environnements marins les plus spectaculaires d\'Indonésie. Connue pour ses eaux cristallines, son ambiance tropicale vibrante et ses vues océaniques à couper le souffle, Bunaken offre l\'occasion parfaite de découvrir la beauté du Nord Sulawesi au-delà du parcours de golf.</p><p style="text-align:justify;">Que vous profitiez d\'un parcours de golf relaxant, exploriez le charme côtier de l\'île, ou vous détendiez simplement dans un cadre tropical, chaque instant est pensé pour offrir confort, détente et souvenirs inoubliables.</p><p style="text-align:justify;">Bien plus qu\'un simple séjour, cette expérience combine sport, nature et loisirs en une évasion tropicale parfaitement fluide.</p><h3 style="text-align:justify;">Pourquoi Vous Allez Adorer ce Forfait</h3><p style="text-align:justify;">• Profitez d\'une combinaison unique entre golf et tourisme marin</p><p style="text-align:justify;">• Jouez au golf dans un cadre côtier pittoresque entouré de beauté tropicale</p><p style="text-align:justify;">• Visitez la célèbre île de Bunaken</p><p style="text-align:justify;">• Vivez des attractions terrestres et marines en un seul voyage</p><p style="text-align:justify;">• Séjournez dans des hôtels et complexes confortables aux excellentes installations</p><p style="text-align:justify;">• Détendez-vous dans une atmosphère tropicale paisible loin des destinations bondées</p><p style="text-align:justify;">• Équilibre parfait entre détente, visites et loisirs</p><p style="text-align:justify;">• Découvrez le meilleur du Nord Sulawesi en un seul forfait complet</p><h3 style="text-align:justify;">Points Forts du Circuit</h3><p style="text-align:justify;">• 2 nuits au Paradise Hotel &amp; Golf Resort</p><p style="text-align:justify;">• 1 nuit dans un hôtel sélectionné à Manado</p><p style="text-align:justify;">• Expérience de golf 18 trous</p><p style="text-align:justify;">• Green fee, voiturette de golf &amp; caddie inclus</p><p style="text-align:justify;">• Circuit d\'observation de l\'île de Bunaken</p><p style="text-align:justify;">• Transfert en bateau vers l\'île de Bunaken</p><p style="text-align:justify;">• Déjeuner de poisson grillé frais avec le dabu-dabu de Manado</p><p style="text-align:justify;">• Activités de snorkeling &amp; plongée en option</p><p style="text-align:justify;">• Transfert aéroport aller-retour inclus</p><h3 style="text-align:justify;">Le Nord Sulawesi est l\'une des rares destinations où vous pouvez profiter d\'une expérience de golf haut de gamme et explorer un paradis marin mondialement connu au cours du même voyage. Des fairways luxuriants surplombant la mer à la beauté spectaculaire de l\'île de Bunaken, ce forfait offre une évasion rafraîchissante combinant détente, aventure et paysages tropicaux inoubliables.</h3>', '<ul><li data-list-item-id="e85fcfeb6216e5a3f9b99dd3a6a7c929c">Transfert aéroport</li><li data-list-item-id="e8de14905ae06a64f87cc60b7707f22d0">3 nuits d\'hébergement à l\'hôtel sélectionné – chambre twin/double</li><li data-list-item-id="eb71e5d213f9c14a6db516ba2d4f3f038">Green fee le jour 2</li><li data-list-item-id="ed12068b91276f3e93b42223230f12673">Voiturette de golf et frais de caddie (pourboire caddie exclu) le jour 2</li><li data-list-item-id="ed97e52152f7c86010c43d5fde2101b87">Bateau privé pour l\'île de Bunaken</li><li data-list-item-id="ec02237fe232f55cc706fb1297ad87fad">Frais d\'entrée aux sites touristiques &amp; frais de parking</li><li data-list-item-id="e54ee6c6a6a0738fa1e15a08e280faef7">Guide de tour professionnel le jour 3</li><li data-list-item-id="e4bb6b6d5246389f96275d7a9a8a82136">Repas selon le programme</li></ul>', '<ul><li data-list-item-id="e3b523e8375ebb8c9d79946b95b626000">Billet d\'avion aller-retour</li><li data-list-item-id="ebb59df0fa48ba937a21926c9d7e1f3dd">Pourboires pour le guide &amp; le chauffeur</li><li data-list-item-id="e3ce39bff4df98057a82869976df231d7">Excursions optionnelles</li><li data-list-item-id="e3f219b92323c9770103f518bec22b1ba">Dépenses personnelles hors forfait (repas/boissons supplémentaires, etc.)</li><li data-list-item-id="e11ba73fd8e73eef138f3ca4ad9edebf4">Service de portage, taxe d\'aéroport &amp; frais de surpoids</li><li data-list-item-id="ec1219e9200318981e942067b191d0e19">Dépenses personnelles (blanchisserie, minibar, service en chambre, etc.)</li><li data-list-item-id="eeb6d510ef8ff5842d69e6e91a30b5aa4">Assurance voyage</li><li data-list-item-id="e0bf84136b233377c9c534be5adbe9757">Autres frais non mentionnés dans le programme du tour</li></ul>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `inclusions` = VALUES(`inclusions`), `exclusions` = VALUES(`exclusions`), `updated_at` = NOW();

-- paket 30: 4-days-paradise-golf-weekend-escape
INSERT INTO `tour_translations` (`translatable_type`, `translatable_id`, `locale`, `title`, `description`, `inclusions`, `exclusions`, `created_at`, `updated_at`)
VALUES ('App\\Models\\ManadoTour', '30', 'fr', '4 Jours Évasion Golf de Week-end au Paradis', '<h2 style="text-align:justify;">Une Escapade Golf Relaxante dans le Nord Sulawesi Tropical</h2><p style="text-align:justify;">Échappez à la routine et profitez d\'un séjour golfique rafraîchissant entouré de la beauté naturelle du Nord Sulawesi. Combinant golf de qualité, hébergement confortable en complexe et atmosphère tropicale paisible, ce forfait est conçu pour les voyageurs qui apprécient à la fois le sport et la détente.</p><p style="text-align:justify;">Niché le long d\'un littoral pittoresque, le Paradise Golf Resort offre un cadre accueillant où fairways luxuriants, brises marines fraîches et vues panoramiques créent le décor parfait pour une expérience de golf inoubliable. Chaque partie est rehaussée par la tranquillité des environs, vous permettant de vous concentrer sur le jeu tout en profitant de la beauté de la nature.</p><p style="text-align:justify;">Au-delà du parcours, le complexe offre une retraite confortable où les hôtes peuvent se détendre, se ressourcer et savourer un rythme de vie plus lent. Que vous voyagiez avec des amateurs de golf, des amis, des collègues ou en famille, ce voyage offre l\'équilibre idéal entre sport et loisirs.</p><p style="text-align:justify;">Avec plusieurs parties de golf, des installations haut de gamme et le charme des paysages tropicaux du Nord Sulawesi, ce forfait est parfait pour celles et ceux en quête d\'une escapade golfique qui va au-delà de l\'ordinaire.</p><h3 style="text-align:justify;">Pourquoi Vous Allez Adorer ce Forfait</h3><p style="text-align:justify;">• Profitez de deux parties de golf dans un cadre tropical pittoresque</p><p style="text-align:justify;">• Séjournez dans un complexe de golf confortable en front de mer</p><p style="text-align:justify;">• Découvrez des brises marines fraîches et un magnifique environnement naturel</p><p style="text-align:justify;">• Détendez-vous loin de l\'agitation de la vie citadine</p><p style="text-align:justify;">• Transferts aéroport pratiques inclus</p><p style="text-align:justify;">• Activités marines en option disponibles au complexe</p><p style="text-align:justify;">• Une combinaison idéale entre sport, confort et détente</p><p style="text-align:justify;">• Découvrez une des destinations de golf les plus agréables du Nord Sulawesi</p><h3 style="text-align:justify;">Points Forts du Circuit</h3><p style="text-align:justify;">• 3 nuits au Paradise Hotel &amp; Golf Resort</p><p style="text-align:justify;">• 2 parties de golf (36 trous au total)</p><p style="text-align:justify;">• Green fee inclus</p><p style="text-align:justify;">• Voiturette de golf &amp; caddie inclus</p><p style="text-align:justify;">• Transferts aéroport aller-retour</p><p style="text-align:justify;">• Environnement paisible de complexe tropical</p><p style="text-align:justify;">• Activités de snorkeling en option</p><p style="text-align:justify;">• Expérience de bateau à fond de verre en option</p><h3 style="text-align:justify;"><strong>Bien plus qu\'un simple séjour golfique, Paradise Golf Weekend Escape offre l\'occasion de profiter d\'un golf de classe mondiale dans un cadre tropical tranquille. Des fairways parfaitement entretenus et des vues océaniques rafraîchissantes aux soirées relaxantes au complexe, chaque détail est pensé pour créer une escapade mémorable et gratifiante dans le Nord Sulawesi.</strong></h3>', '<ul><li data-list-item-id="e85fcfeb6216e5a3f9b99dd3a6a7c929c">Transfert aéroport</li><li data-list-item-id="e8de14905ae06a64f87cc60b7707f22d0">3 nuits d\'hébergement à l\'hôtel sélectionné – chambre twin/double</li><li data-list-item-id="eb71e5d213f9c14a6db516ba2d4f3f038">Green fee les jours 2 &amp; 3</li><li data-list-item-id="ed12068b91276f3e93b42223230f12673">Voiturette de golf et frais de caddie (pourboire caddie exclu)&nbsp;</li><li data-list-item-id="e4bb6b6d5246389f96275d7a9a8a82136">Repas selon le programme</li></ul>', '<ul><li data-list-item-id="e3b523e8375ebb8c9d79946b95b626000">Billet d\'avion aller-retour</li><li data-list-item-id="ebb59df0fa48ba937a21926c9d7e1f3dd">Pourboires pour le guide &amp; le chauffeur</li><li data-list-item-id="e3ce39bff4df98057a82869976df231d7">Excursions optionnelles</li><li data-list-item-id="e3f219b92323c9770103f518bec22b1ba">Dépenses personnelles hors forfait (repas/boissons supplémentaires, etc.)</li><li data-list-item-id="e11ba73fd8e73eef138f3ca4ad9edebf4">Service de portage, taxe d\'aéroport &amp; frais de surpoids</li><li data-list-item-id="ec1219e9200318981e942067b191d0e19">Dépenses personnelles (blanchisserie, minibar, service en chambre, etc.)</li><li data-list-item-id="eeb6d510ef8ff5842d69e6e91a30b5aa4">Assurance voyage</li><li data-list-item-id="e0bf84136b233377c9c534be5adbe9757">Autres frais non mentionnés dans le programme du tour</li></ul>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `inclusions` = VALUES(`inclusions`), `exclusions` = VALUES(`exclusions`), `updated_at` = NOW();

-- paket 31: 3-days-paradise-golf-weekend-escape
INSERT INTO `tour_translations` (`translatable_type`, `translatable_id`, `locale`, `title`, `description`, `inclusions`, `exclusions`, `created_at`, `updated_at`)
VALUES ('App\\Models\\ManadoTour', '31', 'fr', '3 Jours Évasion Golf de Week-end au Paradis', '<h2 style="text-align:justify;">Là où le Grand Golf Rencontre la Sérénité Tropicale</h2><p style="text-align:justify;">Évadez-vous vers une destination où golf de championnat, paysages côtiers et détente tropicale se rencontrent en parfaite harmonie. Niché le long du magnifique littoral du Nord Sulawesi, le Paradise Golf Resort offre bien plus qu\'un simple séjour golfique — il propose une retraite rafraîchissante conçue pour ressourcer le corps et l\'esprit.</p><p style="text-align:justify;">Imaginez vous réveiller dans un air marin frais, poser le pied sur des fairways luxuriants encadrés de paysages tropicaux, et savourer chaque swing sous un ciel bleu et dans un cadre paisible. Loin des villes bondées et des emplois du temps chargés, c\'est un lieu où le temps ralentit et où chaque instant peut être vécu à votre propre rythme.</p><p style="text-align:justify;">Que vous soyez un golfeur passionné en quête d\'une escapade de week-end relaxante, ou simplement à la recherche d\'une expérience de loisirs unique, le Paradise Golf Resort offre le cadre parfait. Hébergement confortable, vues pittoresques et atmosphère accueillante créent un équilibre idéal entre sport, détente et hospitalité tropicale.</p><p style="text-align:justify;">Au-delà du parcours de golf, les hôtes peuvent profiter de l\'environnement côtier tranquille, se détendre au complexe, ou choisir parmi des activités marines optionnelles disponibles à proximité. Chaque élément de ce voyage est pensé pour offrir une évasion mémorable dans l\'une des destinations les plus paisibles du Nord Sulawesi.</p><h3 style="text-align:justify;">Pourquoi Vous Allez Adorer ce Forfait</h3><p style="text-align:justify;">• Profitez d\'un séjour golfique relaxant dans un cadre côtier magnifique</p><p style="text-align:justify;">• Découvrez un des complexes de golf les plus agréables du Nord Sulawesi</p><p style="text-align:justify;">• Jouez au milieu de paysages tropicaux luxuriants et de brises marines rafraîchissantes</p><p style="text-align:justify;">• Séjournez dans un complexe paisible loin des zones touristiques bondées</p><p style="text-align:justify;">• Équilibre parfait entre détente et loisirs</p><p style="text-align:justify;">• Transferts aéroport pratiques inclus</p><p style="text-align:justify;">• Activités marines en option pour des expériences de loisirs supplémentaires</p><p style="text-align:justify;">• Idéal pour les passionnés de golf, les couples, les amis et les groupes d\'entreprise</p><h3 style="text-align:justify;">Points Forts du Circuit</h3><p style="text-align:justify;">• 2 nuits au Paradise Hotel &amp; Golf Resort</p><p style="text-align:justify;">• 1 partie de golf (18 trous)</p><p style="text-align:justify;">• Green fee inclus</p><p style="text-align:justify;">• Voiturette de golf &amp; caddie inclus</p><p style="text-align:justify;">• Transferts aéroport aller-retour</p><p style="text-align:justify;">• Atmosphère de complexe côtier tropical</p><p style="text-align:justify;">• Vues pittoresques sur le parcours de golf</p><p style="text-align:justify;">• Activités de snorkeling &amp; bateau à fond de verre en option</p><h3 style="text-align:justify;"><strong>Bien plus qu\'une simple courte escapade, Paradise Golf Weekend Escape est une occasion de ralentir, de renouer avec la nature et de profiter de moments de qualité dans un cadre tropical. De votre arrivée jusqu\'à votre départ, vous vivrez le mélange parfait entre golf, confort et détente qui fait du Nord Sulawesi une destination véritablement unique.</strong></h3>', '<ul><li data-list-item-id="e85fcfeb6216e5a3f9b99dd3a6a7c929c">Transfert aéroport</li><li data-list-item-id="e8de14905ae06a64f87cc60b7707f22d0">2 nuits d\'hébergement à l\'hôtel sélectionné – chambre twin/double</li><li data-list-item-id="eb71e5d213f9c14a6db516ba2d4f3f038">Green fee les jours 2 &amp; 3</li><li data-list-item-id="ed12068b91276f3e93b42223230f12673">Voiturette de golf et frais de caddie (pourboire caddie exclu)&nbsp;</li><li data-list-item-id="e4bb6b6d5246389f96275d7a9a8a82136">Repas selon le programme</li></ul>', '<ul><li data-list-item-id="e3b523e8375ebb8c9d79946b95b626000">Billet d\'avion aller-retour</li><li data-list-item-id="ebb59df0fa48ba937a21926c9d7e1f3dd">Pourboires pour le guide &amp; le chauffeur</li><li data-list-item-id="e3ce39bff4df98057a82869976df231d7">Excursions optionnelles</li><li data-list-item-id="e3f219b92323c9770103f518bec22b1ba">Dépenses personnelles hors forfait (repas/boissons supplémentaires, etc.)</li><li data-list-item-id="e11ba73fd8e73eef138f3ca4ad9edebf4">Service de portage, taxe d\'aéroport &amp; frais de surpoids</li><li data-list-item-id="ec1219e9200318981e942067b191d0e19">Dépenses personnelles (blanchisserie, minibar, service en chambre, etc.)</li><li data-list-item-id="eeb6d510ef8ff5842d69e6e91a30b5aa4">Assurance voyage</li><li data-list-item-id="e0bf84136b233377c9c534be5adbe9757">Autres frais non mentionnés dans le programme du tour</li></ul>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `inclusions` = VALUES(`inclusions`), `exclusions` = VALUES(`exclusions`), `updated_at` = NOW();

-- paket 32: 5-days-bangka-archipelago-diving-escape
INSERT INTO `tour_translations` (`translatable_type`, `translatable_id`, `locale`, `title`, `description`, `inclusions`, `exclusions`, `created_at`, `updated_at`)
VALUES ('App\\Models\\ManadoTour', '32', 'fr', '5 Jours Évasion Plongée à l\'Archipel de Bangka', '<h2 style="text-align:justify;">Découvrez le Paradis Caché de Plongée du Nord Sulawesi</h2><p style="text-align:justify;">Évadez-vous vers l\'une des destinations sous-marines les plus remarquables du Nord Sulawesi, où jardins de corail vibrants, paysages sous-marins saisissants et biodiversité marine extraordinaire se rencontrent pour une expérience de plongée véritablement inoubliable.</p><p style="text-align:justify;">Situé entre le célèbre Parc marin de Bunaken et le légendaire détroit de Lembeh, l\'archipel de Bangka offre une combinaison unique de plongées murales spectaculaires, de récifs coralliens colorés et d\'une fascinante vie marine macro. Ce mélange rare crée un terrain de jeu sous-marin qui séduit aussi bien les plongeurs expérimentés que ceux qui découvrent pour la première fois les merveilles du monde marin indonésien.</p><p style="text-align:justify;">Entouré d\'eaux cristallines et d\'îles tropicales préservées, Bangka abrite une incroyable variété d\'environnements de plongée. Explorez d\'imposants pitons sous-marins, des murailles de récif abruptes, des cavernes cachées, des prairies d\'herbiers marins et des jardins de corail vibrants et foisonnants de vie. Chaque plongée révèle quelque chose de différent, des bancs de poissons tropicaux et des tortues de mer aux espèces macro rares recherchées par les photographes sous-marins du monde entier.</p><p style="text-align:justify;">Au-delà de la plongée, profitez de la tranquillité de la vie insulaire dans un complexe en front de mer où couchers de soleil à couper le souffle, brises marines fraîches et cadre paisible créent l\'atmosphère parfaite pour se détendre entre deux plongées.</p><p style="text-align:justify;">Avec un accès facile à de nombreux sites de plongée de classe mondiale et certains des écosystèmes marins les plus riches d\'Indonésie, l\'archipel de Bangka offre une évasion inoubliable pour celles et ceux en quête d\'aventure sous la surface et de sérénité au-dessus.</p><h3 style="text-align:justify;">Pourquoi Vous Allez Adorer ce Forfait</h3><p style="text-align:justify;">• Explorez un des secrets de plongée les mieux gardés du Nord Sulawesi</p><p style="text-align:justify;">• Vivez la combinaison unique entre plongée murale façon Bunaken et muck diving façon Lembeh</p><p style="text-align:justify;">• Découvrez des récifs coralliens vibrants et une biodiversité marine exceptionnelle</p><p style="text-align:justify;">• Plongez parmi des pitons sous-marins, des murailles de récif, des cavernes et des pentes sablonneuses</p><p style="text-align:justify;">• Séjournez dans un centre de plongée paisible en front de mer</p><p style="text-align:justify;">• Accédez à de nombreux sites de plongée situés à quelques minutes seulement du complexe</p><p style="text-align:justify;">• Idéal pour les passionnés de photographie sous-marine</p><p style="text-align:justify;">• Profitez d\'un équilibre parfait entre aventure et détente insulaire</p><h3 style="text-align:justify;"><strong>Bien plus qu\'un simple séjour de plongée, l\'exploration de l\'archipel de Bangka est une occasion de découvrir l\'un des environnements marins les plus diversifiés d\'Indonésie. Des jardins de corail colorés et des paysages sous-marins saisissants au charme paisible d\'une retraite insulaire tropicale, chaque instant est pensé pour vous laisser inspiré par la beauté du Nord Sulawesi.</strong></h3>', '<ul><li data-list-item-id="eebc7b4e396e8f7cf17ef8a660054c9c3"><p style="text-align:justify;">Transfert aéroport&nbsp;</p></li><li data-list-item-id="e07c8a95ee6f8b05f18abc3c068904131"><p style="text-align:justify;">Chambre (occupation double – lits double/twin)</p></li><li data-list-item-id="ea72b4950372c034d71b5bc788568f7af"><p style="text-align:justify;">Repas en pension complète</p></li><li data-list-item-id="e9a36fb5e11ed7803755e801175a21ca7"><p style="text-align:justify;">Forfait pension complète (basé sur 2 plongées matinales par jour sur 3 jours de plongée)</p></li></ul>', '<ul><li data-list-item-id="ec756b43cc417da86cc09e4d40b5fccf2">Location d\'équipement</li><li data-list-item-id="e18ed9b2769f68528af4b1df7bdda657a">Recharges nitrox</li><li data-list-item-id="e652fe22505f77dc5bb8cba9be6dee4a2">Plongées de nuit &amp; du poisson-grenouille mandarin</li><li data-list-item-id="ec89e22491c828ef51748a289e4e276f7">Excursions &amp; activités optionnelles</li><li data-list-item-id="ecb84cba1c33800eb790ef4ec86aa3847">Dépenses personnelles</li><li data-list-item-id="e8eb11ebbeab17718fad53293458bf0da">Taxe d\'aéroport &amp; excédent de bagages</li><li data-list-item-id="e973813f562b295b4abff7069d5a3fe14">Assurance voyage</li><li data-list-item-id="e415d746c3ce9f9f2b62c339ce9d53907">Tout service non mentionné ci-dessus</li></ul>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `inclusions` = VALUES(`inclusions`), `exclusions` = VALUES(`exclusions`), `updated_at` = NOW();

-- paket 33: 5-days-diving-the-wonders-of-lembeh-strait
INSERT INTO `tour_translations` (`translatable_type`, `translatable_id`, `locale`, `title`, `description`, `inclusions`, `exclusions`, `created_at`, `updated_at`)
VALUES ('App\\Models\\ManadoTour', '33', 'fr', '5 Jours Plongée dans les Merveilles du Détroit de Lembeh', '<h2 style="text-align:justify;">Explorez la Destination de Plongée Macro la Plus Fascinante au Monde</h2><p style="text-align:justify;">Découvrez un monde sous-marin sans équivalent sur Terre. Célèbre parmi les plongeurs, biologistes marins et photographes sous-marins, le détroit de Lembeh est largement considéré comme la première destination mondiale pour le muck diving et les rencontres avec une vie marine rare.</p><p style="text-align:justify;">Sous ses eaux calmes se cache un univers où prospèrent certaines des créatures les plus extraordinaires de l\'océan. Des poissons-grenouilles insaisissables et des hippocampes délicats aux nudibranches colorés et aux créatures étranges rarement observées ailleurs, chaque plongée révèle quelque chose d\'inattendu et de remarquable.</p><p style="text-align:justify;">Ce qui rend Lembeh véritablement spécial, ce n\'est pas la taille de sa vie marine, mais son incroyable diversité. Le fond marin de sable noir volcanique crée un écosystème unique qui attire une variété étonnante d\'espèces macro, faisant de chaque descente une passionnante chasse au trésor sous la surface.</p><p style="text-align:justify;">Que vous soyez un photographe sous-marin expérimenté, un passionné de macro, ou simplement curieux de découvrir la face cachée de l\'océan, Lembeh offre une expérience de plongée à la fois captivante et inoubliable. Avec des conditions calmes, des profils de plongée faciles et des sites de classe mondiale à quelques minutes seulement du complexe, c\'est la destination idéale pour ralentir, observer la nature et apprécier la beauté extraordinaire des petites choses.</p><p style="text-align:justify;">Au-delà de la plongée, profitez de l\'atmosphère paisible d\'une retraite insulaire tropicale où couchers de soleil spectaculaires, brises marines fraîches et hospitalité chaleureuse complètent parfaitement vos aventures sous-marines.</p><h3 style="text-align:justify;">Pourquoi Vous Allez Adorer ce Forfait</h3><p style="text-align:justify;">• Plongez dans une des destinations de plongée macro les plus célèbres au monde</p><p style="text-align:justify;">• Rencontrez des créatures marines rares et fascinantes qu\'on ne trouve nulle part ailleurs</p><p style="text-align:justify;">• Parfait pour les passionnés de photographie sous-marine et de vie marine</p><p style="text-align:justify;">• Explorez des écosystèmes uniques de sable noir volcanique</p><p style="text-align:justify;">• Profitez de conditions de plongée calmes adaptées à tous les niveaux d\'expérience</p><p style="text-align:justify;">• Séjournez dans un confortable centre de plongée en front de mer</p><p style="text-align:justify;">• Vivez une destination célébrée par les plongeurs du monde entier</p><p style="text-align:justify;">• Combinez aventure, détente et découverte marine en un seul voyage</p><h3 style="text-align:justify;"><strong>Bien plus qu\'un simple séjour de plongée, plonger dans les merveilles du détroit de Lembeh est une occasion d\'explorer l\'un des écosystèmes sous-marins les plus extraordinaires de la planète. Chaque plongée offre une nouvelle découverte, chaque rencontre raconte une histoire, et chaque instant vous rapproche de la remarquable biodiversité qui a fait de Lembeh une destination légendaire parmi les plongeurs du monde entier.</strong></h3>', '<ul><li data-list-item-id="eebc7b4e396e8f7cf17ef8a660054c9c3"><p style="text-align:justify;">Transfert aéroport&nbsp;</p></li><li data-list-item-id="e07c8a95ee6f8b05f18abc3c068904131"><p style="text-align:justify;">Chambre (occupation double – lits double/twin)</p></li><li data-list-item-id="ea72b4950372c034d71b5bc788568f7af"><p style="text-align:justify;">Repas en pension complète</p></li><li data-list-item-id="e9a36fb5e11ed7803755e801175a21ca7"><p style="text-align:justify;">Forfait pension complète (basé sur 2 plongées matinales par jour sur 3 jours de plongée)</p></li></ul>', '<ul><li data-list-item-id="ec756b43cc417da86cc09e4d40b5fccf2">Location d\'équipement</li><li data-list-item-id="e18ed9b2769f68528af4b1df7bdda657a">Recharges nitrox</li><li data-list-item-id="e652fe22505f77dc5bb8cba9be6dee4a2">Plongées de nuit &amp; du poisson-grenouille mandarin</li><li data-list-item-id="ec89e22491c828ef51748a289e4e276f7">Excursions &amp; activités optionnelles</li><li data-list-item-id="ecb84cba1c33800eb790ef4ec86aa3847">Dépenses personnelles</li><li data-list-item-id="e8eb11ebbeab17718fad53293458bf0da">Taxe d\'aéroport &amp; excédent de bagages</li><li data-list-item-id="e973813f562b295b4abff7069d5a3fe14">Assurance voyage</li><li data-list-item-id="e415d746c3ce9f9f2b62c339ce9d53907">Tout service non mentionné ci-dessus</li></ul>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `inclusions` = VALUES(`inclusions`), `exclusions` = VALUES(`exclusions`), `updated_at` = NOW();

-- paket 34: 5-days-bunaken-tangkoko-nature-escape
INSERT INTO `tour_translations` (`translatable_type`, `translatable_id`, `locale`, `title`, `description`, `inclusions`, `exclusions`, `created_at`, `updated_at`)
VALUES ('App\\Models\\ManadoTour', '34', 'fr', '5 Jours Évasion Nature à Bunaken &amp; Tangkoko', '<h2 style="text-align:justify;">Explorez le Nord Sulawesi, sur Terre et sous l\'Eau</h2><p style="text-align:justify;">Découvrez un voyage qui combine deux des plus grands trésors naturels du Nord Sulawesi — le monde sous-marin spectaculaire du Parc marin de Bunaken et la faune extraordinaire de la réserve naturelle de Tangkoko.</p><p style="text-align:justify;">Cette aventure unique est conçue pour les voyageurs en quête de plus qu\'un simple séjour de plongée. Sous les eaux cristallines de Bunaken se cache l\'un des écosystèmes marins les plus célébrés au monde, où murs de corail saisissants, récifs vibrants, tortues de mer et innombrables poissons tropicaux créent une expérience sous-marine inoubliable.</p><p style="text-align:justify;">Au-delà de l\'océan, l\'aventure se poursuit dans les forêts tropicales luxuriantes de Tangkoko, l\'un des sanctuaires de faune sauvage les plus importants d\'Indonésie. Ici, les passionnés de nature ont la rare occasion d\'observer certaines des espèces endémiques les plus emblématiques de Sulawesi, notamment le fascinant tarsier, le macaque noir à crête, les calaos et les couscous dans leur habitat naturel.</p><p style="text-align:justify;">Des jardins de corail colorés et d\'une biodiversité marine à couper le souffle aux forêts tropicales peuplées d\'une faune unique, ce voyage révèle l\'incroyable diversité qui fait du Nord Sulawesi une des destinations les plus remarquables d\'Indonésie.</p><p style="text-align:justify;">Que vous soyez plongeur, passionné de faune sauvage, photographe ou amoureux de la nature, cette expérience offre la combinaison parfaite entre exploration marine, découverte de la forêt tropicale et détente tropicale.</p><h3 style="text-align:justify;">Pourquoi Vous Allez Adorer ce Forfait</h3><p style="text-align:justify;">• Vivez deux des attractions naturelles les plus emblématiques du Nord Sulawesi en un seul voyage</p><p style="text-align:justify;">• Plongez dans le célèbre Parc marin de Bunaken</p><p style="text-align:justify;">• Rencontrez des tortues de mer, des murs de corail et une biodiversité marine vibrante</p><p style="text-align:justify;">• Explorez la forêt tropicale de la réserve naturelle de Tangkoko</p><p style="text-align:justify;">• Observez une faune endémique rare, présente uniquement à Sulawesi</p><p style="text-align:justify;">• Idéal pour les passionnés de photographie sous-marine et de faune sauvage</p><p style="text-align:justify;">• Combinez aventure marine et exploration de la forêt tropicale</p><p style="text-align:justify;">• Profitez d\'un équilibre parfait entre nature, aventure et détente</p><h3 style="text-align:justify;"><strong>Bien plus qu\'un simple séjour, l\'aventure plongée à Bunaken &amp; faune sauvage à Tangkoko offre l\'occasion de découvrir le meilleur du Nord Sulawesi. Des paysages sous-marins à couper le souffle aux rencontres extraordinaires avec la faune, chaque journée révèle une facette différente de ce fascinant paradis tropical.</strong></h3>', '<ul><li data-list-item-id="eebc7b4e396e8f7cf17ef8a660054c9c3"><p style="text-align:justify;">Transfert aéroport&nbsp;</p></li><li data-list-item-id="e07c8a95ee6f8b05f18abc3c068904131"><p style="text-align:justify;">Chambre (occupation double – lits double/twin)</p></li><li data-list-item-id="ea72b4950372c034d71b5bc788568f7af"><p style="text-align:justify;">Repas en pension complète</p></li><li data-list-item-id="e9a36fb5e11ed7803755e801175a21ca7"><p style="text-align:justify;">Forfait pension complète (basé sur 2 plongées matinales par jour sur 3 jours de plongée)</p><p><i><strong>Tour Tangkoko</strong></i>:&nbsp;</p></li><li data-list-item-id="ee940554db6d2888b5bb336fc3adcacdd">Ranger du parc naturel de Tangkoko</li><li data-list-item-id="ee45511db7425bb0a055e829f59fba41b">Transport vers Tangkoko &amp; la cascade de Tunan</li><li data-list-item-id="e30412c6835047afc69dff857179d3527">1x déjeuner dans un restaurant local</li><li data-list-item-id="ea8818d92b289888451c817f79249fabe">Guide expérimenté &amp; chauffeur</li><li data-list-item-id="ec3ec6d7bb147e07c82d795805c6ecbc9">Tous les frais d\'entrée&nbsp;</li><li data-list-item-id="e5a9edd557416c1a3372568c67fdfc9a5">Une bouteille d\'eau minérale par personne.</li></ul>', '<ul><li data-list-item-id="ec756b43cc417da86cc09e4d40b5fccf2">Location d\'équipement de plongée</li><li data-list-item-id="e18ed9b2769f68528af4b1df7bdda657a">Recharges nitrox</li><li data-list-item-id="e652fe22505f77dc5bb8cba9be6dee4a2">Plongées de nuit &amp; du poisson-grenouille mandarin</li><li data-list-item-id="ec89e22491c828ef51748a289e4e276f7">Excursions &amp; activités optionnelles</li><li data-list-item-id="ecb84cba1c33800eb790ef4ec86aa3847">Dépenses personnelles</li><li data-list-item-id="e8eb11ebbeab17718fad53293458bf0da">Taxe d\'aéroport &amp; excédent de bagages</li><li data-list-item-id="e973813f562b295b4abff7069d5a3fe14">Assurance voyage</li><li data-list-item-id="e415d746c3ce9f9f2b62c339ce9d53907">Tout service non mentionné ci-dessus</li></ul>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `inclusions` = VALUES(`inclusions`), `exclusions` = VALUES(`exclusions`), `updated_at` = NOW();

-- paket 35: 4-days-discover-bangkas-underwater-paradise
INSERT INTO `tour_translations` (`translatable_type`, `translatable_id`, `locale`, `title`, `description`, `inclusions`, `exclusions`, `created_at`, `updated_at`)
VALUES ('App\\Models\\ManadoTour', '35', 'fr', '4 Jours Découverte du Paradis Sous-Marin de Bangka', '<h2 style="text-align:justify;">Découvrez un Paradis de Plongée Caché du Nord Sulawesi</h2><p style="text-align:justify;">Évadez-vous vers les eaux tranquilles de l\'archipel de Bangka, une destination insulaire tropicale où récifs préservés, mers cristallines et biodiversité marine extraordinaire créent une aventure sous-marine inoubliable.</p><p style="text-align:justify;">Niché entre le légendaire Parc marin de Bunaken et le détroit de Lembeh mondialement renommé, Bangka offre une rare combinaison de plongées murales spectaculaires, de jardins de corail vibrants, d\'une fascinante vie macro et de paysages sous-marins saisissants. Ce mélange unique fait de l\'archipel une des destinations les plus gratifiantes du Nord Sulawesi pour les plongeurs de tous niveaux d\'expérience.</p><p style="text-align:justify;">Sous la surface, découvrez des récifs de corail mou et dur colorés, d\'imposants pitons sous-marins, des cavernes cachées, des prairies d\'herbiers marins et des écosystèmes marins foisonnants. Chaque plongée offre une nouvelle perspective sur l\'océan, des bancs de poissons tropicaux et des tortues de mer aux espèces macro rares qui attirent les photographes sous-marins du monde entier.</p><p style="text-align:justify;">Au-dessus de l\'eau, découvrez le charme paisible de la vie insulaire. Entouré de mers turquoise et de paysages tropicaux intacts, Bangka offre le cadre parfait pour se détendre, renouer avec la nature et savourer un rythme plus lent, loin des destinations touristiques bondées.</p><p style="text-align:justify;">Que vous soyez un plongeur expérimenté, un passionné de vie marine, ou simplement en quête d\'une évasion insulaire tropicale, l\'archipel de Bangka offre un mélange exceptionnel d\'aventure, de beauté naturelle et de détente.</p><h3 style="text-align:justify;">Pourquoi Vous Allez Adorer ce Forfait</h3><p style="text-align:justify;">• Découvrez un des secrets de plongée les mieux gardés du Nord Sulawesi</p><p style="text-align:justify;">• Vivez à la fois plongée murale et plongée macro en une seule destination</p><p style="text-align:justify;">• Explorez des récifs coralliens vibrants et une riche biodiversité marine</p><p style="text-align:justify;">• Accédez à de nombreux sites de plongée situés près du complexe</p><p style="text-align:justify;">• Adapté aux plongeurs débutants comme expérimentés</p><p style="text-align:justify;">• Profitez d\'une atmosphère insulaire tropicale paisible</p><p style="text-align:justify;">• Idéal pour les passionnés de photographie sous-marine</p><p style="text-align:justify;">• Combinez une plongée de classe mondiale avec la détente insulaire</p><h3 style="text-align:justify;"><strong>Bien plus qu\'un simple séjour de plongée, l\'exploration de l\'archipel de Bangka vous invite à découvrir la remarquable diversité du monde marin du Nord Sulawesi. Des récifs coralliens colorés et des rencontres marines fascinantes à la sérénité d\'une retraite insulaire tropicale, chaque instant est pensé pour inspirer, détendre et créer des souvenirs durables.</strong></h3>', '<ul><li data-list-item-id="eebc7b4e396e8f7cf17ef8a660054c9c3"><p style="text-align:justify;">Transfert aéroport&nbsp;</p></li><li data-list-item-id="e07c8a95ee6f8b05f18abc3c068904131"><p style="text-align:justify;">Chambre (occupation double – lits double/twin)</p></li><li data-list-item-id="ea72b4950372c034d71b5bc788568f7af"><p style="text-align:justify;">Repas en pension complète</p></li><li data-list-item-id="e9a36fb5e11ed7803755e801175a21ca7"><p style="text-align:justify;">Forfait pension complète (basé sur 2 plongées matinales par jour sur 2 jours de plongée)</p></li></ul>', '<ul><li data-list-item-id="ec756b43cc417da86cc09e4d40b5fccf2">Location d\'équipement</li><li data-list-item-id="e18ed9b2769f68528af4b1df7bdda657a">Recharges nitrox</li><li data-list-item-id="e652fe22505f77dc5bb8cba9be6dee4a2">Plongées de nuit &amp; du poisson-grenouille mandarin</li><li data-list-item-id="ec89e22491c828ef51748a289e4e276f7">Excursions &amp; activités optionnelles</li><li data-list-item-id="ecb84cba1c33800eb790ef4ec86aa3847">Dépenses personnelles</li><li data-list-item-id="e8eb11ebbeab17718fad53293458bf0da">Taxe d\'aéroport &amp; excédent de bagages</li><li data-list-item-id="e973813f562b295b4abff7069d5a3fe14">Assurance voyage</li><li data-list-item-id="e415d746c3ce9f9f2b62c339ce9d53907">Tout service non mentionné ci-dessus</li></ul>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `inclusions` = VALUES(`inclusions`), `exclusions` = VALUES(`exclusions`), `updated_at` = NOW();

-- paket 36: 4-days-lembeh-macro-diving-escape
INSERT INTO `tour_translations` (`translatable_type`, `translatable_id`, `locale`, `title`, `description`, `inclusions`, `exclusions`, `created_at`, `updated_at`)
VALUES ('App\\Models\\ManadoTour', '36', 'fr', '4 Jours Évasion Plongée Macro à Lembeh', '<h2 style="text-align:justify;">Découvrez la Capitale Mondiale de la Plongée Macro</h2><p style="text-align:justify;">Plongez dans l\'un des environnements sous-marins les plus extraordinaires de la Terre, où chaque plongée révèle un monde caché de vie marine rare, de comportements fascinants et de découvertes inoubliables.</p><p style="text-align:justify;">Situé entre le continent du Nord Sulawesi et l\'île de Lembeh, le légendaire détroit de Lembeh a acquis une reconnaissance mondiale en tant que première destination au monde pour le muck diving et la photographie macro sous-marine. Sous ses eaux calmes se cache un écosystème remarquable où le sable noir volcanique offre l\'habitat parfait à certaines des créatures les plus insolites et recherchées de l\'océan.</p><p style="text-align:justify;">Contrairement aux destinations de plongée traditionnelles connues pour leurs grandes espèces pélagiques, Lembeh offre quelque chose de totalement différent. Ici, l\'excitation vient de la découverte des détails extraordinaires du monde sous-marin. Des poissons-grenouilles parfaitement camouflés et des hippocampes pygmées délicats aux nudibranches colorés et à d\'innombrables créatures rares, chaque plongée devient une fascinante chasse au trésor sous la surface.</p><p style="text-align:justify;">Réputé auprès des photographes sous-marins, des biologistes marins et des plongeurs expérimentés du monde entier, Lembeh offre une expérience qui combine exploration, patience et le frisson de rencontrer des espèces marines rarement observées ailleurs.</p><p style="text-align:justify;">Au-delà de la plongée, profitez de l\'atmosphère paisible d\'une retraite insulaire tropicale. Entouré d\'eaux tranquilles et de paysages côtiers luxuriants, Lembeh offre le cadre parfait pour se détendre entre deux plongées et s\'immerger pleinement dans la beauté du Nord Sulawesi.</p><p style="text-align:justify;">Que vous soyez photographe sous-marin, plongeur passionné, ou simplement curieux des merveilles cachées de l\'océan, le détroit de Lembeh promet un voyage inoubliable au cœur de l\'un des écosystèmes marins les plus uniques de la planète.</p><h3 style="text-align:justify;">Pourquoi Vous Allez Adorer ce Forfait</h3><p style="text-align:justify;">• Plongez dans une des destinations de muck diving les plus célèbres au monde</p><p style="text-align:justify;">• Rencontrez des espèces marines rares présentes en très peu d\'endroits sur Terre</p><p style="text-align:justify;">• Explorez l\'écosystème unique de sable noir volcanique du détroit de Lembeh</p><p style="text-align:justify;">• Idéal pour la photographie macro et les passionnés de vie marine sous-marine</p><p style="text-align:justify;">• Découvrez poissons-grenouilles, hippocampes, nudibranches et autres créatures marines fascinantes</p><p style="text-align:justify;">• Profitez de conditions de plongée calmes adaptées à tous les niveaux d\'expérience</p><p style="text-align:justify;">• Séjournez dans un environnement insulaire tropical paisible</p><p style="text-align:justify;">• Vivez une destination célébrée par les plongeurs et photographes du monde entier</p><h3 style="text-align:justify;">Bien plus qu\'un simple séjour de plongée, plonger dans les merveilles du détroit de Lembeh offre l\'occasion d\'apercevoir une face cachée de l\'océan que peu de gens ont la chance de vivre. Des rencontres marines extraordinaires à la sérénité de la vie insulaire, chaque instant révèle pourquoi Lembeh reste l\'une des destinations de plongée les plus respectées au monde.</h3>', '<ul><li data-list-item-id="eebc7b4e396e8f7cf17ef8a660054c9c3"><p style="text-align:justify;">Transfert aéroport&nbsp;</p></li><li data-list-item-id="e07c8a95ee6f8b05f18abc3c068904131"><p style="text-align:justify;">Chambre (occupation double – lits double/twin)</p></li><li data-list-item-id="ea72b4950372c034d71b5bc788568f7af"><p style="text-align:justify;">Repas en pension complète</p></li><li data-list-item-id="e9a36fb5e11ed7803755e801175a21ca7"><p style="text-align:justify;">Forfait pension complète (basé sur 2 plongées matinales par jour sur 2 jours de plongée)</p></li></ul>', '<ul><li data-list-item-id="ec756b43cc417da86cc09e4d40b5fccf2">Location d\'équipement</li><li data-list-item-id="e18ed9b2769f68528af4b1df7bdda657a">Recharges nitrox</li><li data-list-item-id="e652fe22505f77dc5bb8cba9be6dee4a2">Plongées de nuit &amp; du poisson-grenouille mandarin</li><li data-list-item-id="ec89e22491c828ef51748a289e4e276f7">Excursions &amp; activités optionnelles</li><li data-list-item-id="ecb84cba1c33800eb790ef4ec86aa3847">Dépenses personnelles</li><li data-list-item-id="e8eb11ebbeab17718fad53293458bf0da">Taxe d\'aéroport &amp; excédent de bagages</li><li data-list-item-id="e973813f562b295b4abff7069d5a3fe14">Assurance voyage</li><li data-list-item-id="e415d746c3ce9f9f2b62c339ce9d53907">Tout service non mentionné ci-dessus</li></ul>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `inclusions` = VALUES(`inclusions`), `exclusions` = VALUES(`exclusions`), `updated_at` = NOW();

-- paket 37: 4-days-bunaken-marine-park-experience
INSERT INTO `tour_translations` (`translatable_type`, `translatable_id`, `locale`, `title`, `description`, `inclusions`, `exclusions`, `created_at`, `updated_at`)
VALUES ('App\\Models\\ManadoTour', '37', 'fr', '4 Jours Expérience du Parc Marin de Bunaken', '<h2 style="text-align:justify;">Découvrez le Paradis Sous-Marin Mondialement Renommé du Nord Sulawesi</h2><p style="text-align:justify;">Vivez la beauté à couper le souffle du Parc marin de Bunaken, une des destinations de plongée les plus célébrées d\'Indonésie et un véritable paradis pour les amoureux de l\'océan.</p><p style="text-align:justify;">Entouré d\'eaux tropicales cristallines, Bunaken est réputé pour ses murs sous-marins saisissants, ses récifs coralliens vibrants et son extraordinaire biodiversité marine. Sous la surface se trouve un écosystème foisonnant où les tortues de mer glissent sans effort dans le bleu, où des poissons de récif colorés peuplent les jardins de corail, et où des paysages sous-marins spectaculaires créent des expériences de plongée inoubliables.</p><p style="text-align:justify;">Reconnu comme l\'une des zones de conservation marine les plus importantes d\'Asie du Sud-Est, Bunaken offre une visibilité exceptionnelle et une incroyable variété d\'environnements de plongée. Des murs de corail verticaux et des systèmes de récifs foisonnants à la fascinante vie macro cachée parmi les coraux, chaque plongée révèle une perspective différente de ce monde merveilleux sous-marin.</p><p style="text-align:justify;">Au-delà de l\'océan, profitez de l\'atmosphère paisible d\'une évasion insulaire tropicale. Détendez-vous au bord d\'eaux turquoise, admirez des couchers de soleil superbes, et découvrez le rythme plus lent de la vie insulaire entouré de la beauté naturelle du Nord Sulawesi.</p><p style="text-align:justify;">Que vous soyez plongeur certifié, photographe sous-marin, ou simplement quelqu\'un qui apprécie la beauté de la mer, Bunaken offre un voyage inoubliable au cœur de l\'un des écosystèmes marins les plus remarquables au monde.</p><h3 style="text-align:justify;">Pourquoi Vous Allez Adorer ce Forfait</h3><p style="text-align:justify;">• Plongez dans un des parcs marins les plus célèbres d\'Indonésie</p><p style="text-align:justify;">• Explorez des murs de corail spectaculaires et des systèmes de récifs colorés</p><p style="text-align:justify;">• Rencontrez des tortues de mer et une abondante vie marine tropicale</p><p style="text-align:justify;">• Profitez d\'eaux cristallines à l\'excellente visibilité</p><p style="text-align:justify;">• Vivez une des premières destinations de plongée d\'Asie du Sud-Est</p><p style="text-align:justify;">• Adapté aux plongeurs débutants comme expérimentés</p><p style="text-align:justify;">• Parfait pour les passionnés de photographie sous-marine</p><p style="text-align:justify;">• Combinez une plongée de classe mondiale avec la détente insulaire tropicale</p><h3 style="text-align:justify;"><strong>Bien plus qu\'un simple séjour de plongée, l\'évasion plongée à l\'île de Bunaken vous invite à découvrir l\'incroyable biodiversité marine et la beauté naturelle qui ont fait de Bunaken une destination légendaire parmi les plongeurs du monde entier. Chaque plongée, chaque coucher de soleil et chaque instant passé dans ce paradis tropical créent des souvenirs qui dureront toute une vie.</strong></h3>', '<ul><li data-list-item-id="eebc7b4e396e8f7cf17ef8a660054c9c3"><p style="text-align:justify;">Transfert aéroport&nbsp;</p></li><li data-list-item-id="e07c8a95ee6f8b05f18abc3c068904131"><p style="text-align:justify;">Chambre (occupation double – lits double/twin)</p></li><li data-list-item-id="ea72b4950372c034d71b5bc788568f7af"><p style="text-align:justify;">Repas en pension complète</p></li><li data-list-item-id="e9a36fb5e11ed7803755e801175a21ca7"><p style="text-align:justify;">Forfait pension complète (basé sur 2 plongées matinales par jour sur 2 jours de plongée)</p></li></ul>', '<ul><li data-list-item-id="ec756b43cc417da86cc09e4d40b5fccf2">Location d\'équipement</li><li data-list-item-id="e18ed9b2769f68528af4b1df7bdda657a">Recharges nitrox</li><li data-list-item-id="e652fe22505f77dc5bb8cba9be6dee4a2">Plongées de nuit &amp; du poisson-grenouille mandarin</li><li data-list-item-id="ec89e22491c828ef51748a289e4e276f7">Excursions &amp; activités optionnelles</li><li data-list-item-id="ecb84cba1c33800eb790ef4ec86aa3847">Dépenses personnelles</li><li data-list-item-id="e8eb11ebbeab17718fad53293458bf0da">Taxe d\'aéroport &amp; excédent de bagages</li><li data-list-item-id="e973813f562b295b4abff7069d5a3fe14">Assurance voyage</li><li data-list-item-id="e415d746c3ce9f9f2b62c339ce9d53907">Tout service non mentionné ci-dessus</li></ul>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `inclusions` = VALUES(`inclusions`), `exclusions` = VALUES(`exclusions`), `updated_at` = NOW();

-- paket 38: lihaga-island-white-sand-escape
INSERT INTO `tour_translations` (`translatable_type`, `translatable_id`, `locale`, `title`, `description`, `inclusions`, `exclusions`, `created_at`, `updated_at`)
VALUES ('App\\Models\\ManadoTour', '38', 'fr', 'Évasion Sable Blanc de l\'Île de Lihaga', '<h2 style="text-align:justify;">Évadez-vous vers le Paradis Tropical Caché du Nord Sulawesi</h2><p style="text-align:justify;">Découvrez la beauté intacte de l\'île de Lihaga, un paradis tropical isolé où sable blanc poudreux, eaux turquoise cristallines et paysages insulaires à couper le souffle créent l\'évasion parfaite loin du quotidien.</p><p style="text-align:justify;">Entourée des eaux immaculées de Likupang, l\'une des principales destinations touristiques d\'Indonésie, l\'île de Lihaga offre un cadre idyllique pour les voyageurs en quête de tranquillité, de beauté naturelle et d\'expériences tropicales inoubliables. Sans foule, sans circulation, rien d\'autre que le doux bruit de l\'océan, chaque instant vous invite à ralentir et à embrasser le rythme paisible de la vie insulaire.</p><p style="text-align:justify;">L\'île est réputée pour sa plage de sable blanc éblouissante et ses eaux exceptionnellement claires qui révèlent des récifs coralliens vibrants et une vie marine colorée sous la surface. Que vous choisissiez de nager dans la mer tropicale chaude, de faire du snorkeling parmi des jardins de corail foisonnants, de pagayer dans le lagon calme, ou simplement de vous détendre à l\'ombre des cocotiers, Lihaga offre une expérience insulaire véritablement ressourçante.</p><p style="text-align:justify;">Au-delà de sa beauté naturelle, l\'île de Lihaga est aussi un paradis pour les photographes et les amoureux de la plage. D\'infinies étendues de sable blanc, des vues panoramiques sur l\'océan et de spectaculaires nuances de bleu créent d\'innombrables moments dignes d\'une carte postale tout au long de la journée. Chaque coin de l\'île ressemble à une carte postale attendant d\'être capturée.</p><p style="text-align:justify;">Pensée pour les couples, les familles, les amis et les voyageurs solo, cette évasion insulaire combine détente, aventure tropicale et beauté préservée du Nord Sulawesi en un seul voyage inoubliable.</p><h3 style="text-align:justify;">Pourquoi Vous Allez Adorer ce Forfait</h3><p style="text-align:justify;">• Détendez-vous sur une des plus belles îles de sable blanc du Nord Sulawesi</p><p style="text-align:justify;">• Nagez dans des eaux turquoise cristallines</p><p style="text-align:justify;">• Découvrez des récifs coralliens colorés et une vie marine tropicale</p><p style="text-align:justify;">• Profitez d\'une atmosphère insulaire paisible loin de la foule</p><p style="text-align:justify;">• Parfait pour le snorkeling, la baignade et la détente sur la plage</p><p style="text-align:justify;">• Capturez de superbes paysages tropicaux et des photos inoubliables</p><p style="text-align:justify;">• Découvrez la beauté naturelle de la région touristique de Likupang</p><p style="text-align:justify;">• Idéal pour les couples, les familles, les jeunes mariés et les amoureux de la plage</p><h3 style="text-align:justify;"><strong>Bien plus qu\'une simple escapade à la plage, l\'évasion sable blanc de l\'île de Lihaga offre l\'occasion de renouer avec la nature sur une des plus belles îles cachées du Nord Sulawesi. Des plages immaculées et des eaux turquoise aux paysages tropicaux inoubliables, chaque instant devient un souvenir que vous chérirez longtemps après la fin de votre voyage.</strong></h3>', '<ul><li data-list-item-id="ea23d3c92112e60644e5e2271e3753532"><p style="text-align:justify;">Transport terrestre</p></li><li data-list-item-id="e0ea594d6a88f73886434e73627cfc1ef"><p style="text-align:justify;">Bateau privé pour l\'île de Lihaga</p></li><li data-list-item-id="eade732e4827ee2d27bca1f6a14016d45"><p style="text-align:justify;">Guide de tour expérimenté</p></li><li data-list-item-id="e688d27ccc1439077a5068c64e476b6ad"><p style="text-align:justify;">Chauffeur &amp; batelier</p></li><li data-list-item-id="ef25650808aa3c32de3a1e39199920a06"><p style="text-align:justify;">Frais d\'entrée aux sites touristiques &amp; frais de parking</p></li><li data-list-item-id="e7ac148cecef0bb392af14db4b9f574d4"><p style="text-align:justify;">Déjeuner &amp; 1 bouteille d\'eau minérale par personne</p></li><li data-list-item-id="eccc9556eef6a2fa87c897c5c43a32269"><p style="text-align:justify;">Services de tour selon l\'itinéraire</p></li></ul>', '<ul><li data-list-item-id="ed040cc0dd81d42e795600e22a7bf6536">Billet d\'avion</li><li data-list-item-id="eb2e43bfc1813f79cdda31725bf97dbad">Taxe d\'aéroport</li><li data-list-item-id="eec4c3bc7fb908919a5b66c97cde714e5">Portage</li><li data-list-item-id="ef13b7599a238bc82e6bd5620370064d9">Hôtel</li><li data-list-item-id="e7a50082855dcc93d44a0d8bbcef795bb">Pourboires pour le guide et le chauffeur</li><li data-list-item-id="e2a39ca8ecbefd244e7980a1f24d1bb28">Excursions optionnelles</li><li data-list-item-id="efae7355dae9278ce19d7a043661cdfd1">Autres frais hors programme du tour</li></ul>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `inclusions` = VALUES(`inclusions`), `exclusions` = VALUES(`exclusions`), `updated_at` = NOW();

-- paket 39: gangga-lihaga-snorkeling-escape
INSERT INTO `tour_translations` (`translatable_type`, `translatable_id`, `locale`, `title`, `description`, `inclusions`, `exclusions`, `created_at`, `updated_at`)
VALUES ('App\\Models\\ManadoTour', '39', 'fr', 'Évasion Snorkeling à Gangga &amp; Lihaga', '<h2 style="text-align:justify;">Découvrez Deux Paradis Tropicaux en un Seul Voyage Inoubliable</h2><p style="text-align:justify;">Évadez-vous vers la beauté à couper le souffle du Nord Sulawesi et découvrez deux des îles tropicales les plus spectaculaires de Likupang en une seule journée. Entourée d\'eaux cristallines, de récifs coralliens vibrants et de plages de sable blanc poudreux, cette aventure d\'île en île offre la combinaison parfaite entre exploration marine et détente tropicale.</p><p style="text-align:justify;">Situées dans la région touristique mondialement renommée de Likupang, l\'île de Gangga et l\'île de Lihaga possèdent chacune leur propre charme unique. Sous la surface, des jardins de corail colorés et une vie marine diversifiée créent une expérience de snorkeling inoubliable, tandis qu\'au-dessus de l\'eau, des plages immaculées et d\'infinies nuances de turquoise offrent le cadre idéal pour se détendre et renouer avec la nature.</p><p style="text-align:justify;">L\'île de Gangga est célébrée pour sa riche biodiversité sous-marine et ses eaux calmes et cristallines, ce qui en fait une des meilleures destinations de snorkeling du Nord Sulawesi. À seulement une courte traversée en bateau, l\'île de Lihaga accueille les visiteurs avec sa plage de sable blanc intacte, son atmosphère paisible et ses paysages dignes d\'une carte postale qui donnent l\'impression d\'un paradis tropical privé.</p><p style="text-align:justify;">Que vous nagiez dans des eaux tropicales chaudes, admiriez des paysages côtiers spectaculaires, capturiez des photographies inoubliables, ou profitiez simplement du rythme paisible de la vie insulaire, chaque instant est pensé pour créer des souvenirs durables.</p><p style="text-align:justify;">Pensée pour les couples, les familles, les groupes d\'amis et les voyageurs solo, cette expérience réunit le meilleur de la beauté marine, du charme insulaire et de l\'atmosphère tropicale relaxante de Likupang en une escapade extraordinaire.</p><h3 style="text-align:justify;">Pourquoi Vous Allez Adorer ce Forfait</h3><p style="text-align:justify;">• Visitez deux des plus belles îles tropicales de Likupang en une seule journée</p><p style="text-align:justify;">• Faites du snorkeling parmi des récifs coralliens vibrants et une vie marine tropicale colorée</p><p style="text-align:justify;">• Détendez-vous sur des plages de sable blanc immaculées entourées d\'eaux turquoise</p><p style="text-align:justify;">• Découvrez l\'atmosphère paisible des îles cachées du Nord Sulawesi</p><p style="text-align:justify;">• Profitez de paysages insulaires spectaculaires et de vues océaniques cristallines</p><p style="text-align:justify;">• Capturez d\'incroyables paysages tropicaux et des photographies inoubliables</p><p style="text-align:justify;">• Combinez snorkeling, île en île et détente sur la plage en un seul voyage</p><p style="text-align:justify;">• Parfait pour les couples, les familles, les jeunes mariés et les amoureux de la nature</p><h3 style="text-align:justify;">Bien plus qu\'une simple excursion insulaire, <strong>l\'évasion des deux îles – Gangga &amp; Lihaga</strong> est une invitation à découvrir la beauté tropicale de Likupang à son meilleur. Des écosystèmes sous-marins vibrants aux plages de sable blanc intactes, chaque destination révèle une raison supplémentaire pour laquelle le Nord Sulawesi est une des escapades insulaires les plus captivantes d\'Indonésie.</h3>', '<ul><li data-list-item-id="ec841ebd5e4cd2f22a9ab973c51cd4294"><p style="text-align:justify;">Transport terrestre</p></li><li data-list-item-id="e0fd2b212b9f3647f5b39e969d280b5b9"><p style="text-align:justify;">Bateau privé pour les îles de Gangga &amp; Lihaga</p></li><li data-list-item-id="e1955e0bd0b95f1e58e091f47a0f210fd"><p style="text-align:justify;">Équipement de snorkeling</p></li><li data-list-item-id="ef86508779b01af9d5d07a6933e8c8b71"><p style="text-align:justify;">Guide de tour, chauffeur &amp; batelier expérimentés</p></li><li data-list-item-id="e6053e10c115a87007b280508a6f4332d"><p style="text-align:justify;">Frais d\'entrée aux sites touristiques &amp; frais de parking</p></li><li data-list-item-id="e9615cc9e5ef3f391f33ab1e8faff78dd"><p style="text-align:justify;">Déjeuner &amp; 1 bouteille d\'eau minérale par personne</p></li><li data-list-item-id="e8d83387ff5232b493198cf3640575fe4"><p style="text-align:justify;">Services de tour selon l\'itinéraire</p></li></ul>', '<ul><li data-list-item-id="ed040cc0dd81d42e795600e22a7bf6536">Billet d\'avion</li><li data-list-item-id="eb2e43bfc1813f79cdda31725bf97dbad">Taxe d\'aéroport</li><li data-list-item-id="eec4c3bc7fb908919a5b66c97cde714e5">Portage</li><li data-list-item-id="ef13b7599a238bc82e6bd5620370064d9">Hôtel</li><li data-list-item-id="e7a50082855dcc93d44a0d8bbcef795bb">Pourboires pour le guide et le chauffeur</li><li data-list-item-id="e2a39ca8ecbefd244e7980a1f24d1bb28">Excursions optionnelles</li><li data-list-item-id="efae7355dae9278ce19d7a043661cdfd1">Autres frais hors programme du tour</li></ul>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `inclusions` = VALUES(`inclusions`), `exclusions` = VALUES(`exclusions`), `updated_at` = NOW();

-- paket 40: manado-tua-island-trekking-bunaken-escape
INSERT INTO `tour_translations` (`translatable_type`, `translatable_id`, `locale`, `title`, `description`, `inclusions`, `exclusions`, `created_at`, `updated_at`)
VALUES ('App\\Models\\ManadoTour', '40', 'fr', 'Trekking à l\'Île de Manado Tua &amp; Évasion à Bunaken', '<h3 style="text-align:justify;">De la Forêt Tropicale aux Merveilles Sous-Marines de Bunaken</h3><p style="text-align:justify;">Vivez deux des environnements naturels les plus remarquables du Nord Sulawesi en une seule journée inoubliable — le paysage volcanique luxuriant de Manado Tua et le monde marin spectaculaire de Bunaken.</p><p style="text-align:justify;">S\'élevant des eaux juste au large de Manado, Manado Tua offre une rare occasion de découvrir le côté le plus sauvage du Nord Sulawesi. Sa forêt tropicale, son paysage volcanique et son cadre paisible créent une évasion immersive loin de la ville, tandis que la possibilité de rencontrer la faune endémique de Sulawesi ajoute un excitant élément de découverte à l\'aventure.</p><p style="text-align:justify;">L\'expérience se poursuit sous la surface à Bunaken, une des destinations marines les plus célébrées du Nord Sulawesi. Entouré d\'eaux tropicales claires et d\'un paysage sous-marin extraordinaire, Bunaken offre un cadre idéal pour découvrir la beauté de l\'écosystème marin de la région grâce au snorkeling ou à la plongée en option.</p><p style="text-align:justify;">Ce qui rend cette expérience spéciale, c\'est le contraste entre deux mondes complètement différents. Un instant, vous êtes entouré de forêt tropicale et de paysages volcaniques ; l\'instant suivant, vous explorez l\'environnement sous-marin vibrant d\'une des destinations marines réputées d\'Indonésie.</p><p style="text-align:justify;">Que vous recherchiez une aventure légère, une évasion nature, ou une découverte de la diversité naturelle du Nord Sulawesi, ce voyage offre une manière passionnante de découvrir <strong>la terre et la mer en une seule journée</strong>.</p><h3 style="text-align:justify;">Pourquoi Vous Allez Adorer cette Expérience</h3><p style="text-align:justify;">• Découvrez la beauté naturelle de l\'île volcanique de Manado Tua</p><p style="text-align:justify;">• Vivez l\'atmosphère de la forêt tropicale du Nord Sulawesi</p><p style="text-align:justify;">• Ayez la chance de rencontrer la faune endémique de Sulawesi</p><p style="text-align:justify;">• Poursuivez votre aventure dans l\'environnement marin spectaculaire de Bunaken</p><p style="text-align:justify;">• Profitez du snorkeling ou de la plongée en option à Bunaken</p><p style="text-align:justify;">• Découvrez deux facettes complètement différentes du Nord Sulawesi en un seul voyage</p><p style="text-align:justify;">• Idéal pour les amoureux de la nature, les amateurs d\'aventure, les photographes et les voyageurs actifs</p><p style="text-align:justify;">• Une combinaison mémorable entre exploration de la forêt tropicale et découverte marine</p><h3 style="text-align:justify;">Bien plus qu\'une simple sortie de trekking ou de snorkeling, <strong>trekking à l\'île de Manado Tua &amp; évasion à Bunaken</strong> réunit les deux facettes de la beauté naturelle du Nord Sulawesi — les paysages sauvages au-dessus de l\'eau et le monde marin extraordinaire en dessous.</h3>', '<ul><li data-list-item-id="e00fb6c1118e49e21a7f97503eaf992e5"><p style="text-align:justify;">Transport terrestre privé (voiture)&nbsp;</p></li><li data-list-item-id="e6716471c34f5fc9b3179bcb936fa58c3"><p style="text-align:justify;">Bateau pour l\'île de Manado Tua - l\'île de Bunaken</p></li><li data-list-item-id="e7dbd5d5b9349e351d2566cfe3d45e1f5"><p style="text-align:justify;">Guide de tour expérimenté&nbsp;</p></li><li data-list-item-id="ee7e0b2f9144abb63771706ac469d1409"><p style="text-align:justify;">Chauffeur &amp; batelier&nbsp;</p></li><li data-list-item-id="e5f742e4e693df53a07f0d451ed536d14"><p style="text-align:justify;">Frais d\'entrée aux sites touristiques</p></li><li data-list-item-id="e16a242b2af99118485dc893e4c9eb32e"><p style="text-align:justify;">Frais de parking, panier-repas&nbsp;</p></li><li data-list-item-id="e4ee5b7dc98d3b764f8675efcd7904bc8"><p style="text-align:justify;">1 bouteille d\'eau minérale par personne&nbsp;</p></li><li data-list-item-id="e19afe33283d9f5a1420ae129e922a3cd"><p style="text-align:justify;">Services de tour selon l\'itinéraire</p></li></ul>', '<ul><li data-list-item-id="e369b588efdeecf96f0f185253b99bd9d">Billet d\'avion&nbsp;</li><li data-list-item-id="ee1063332712c6f3757ec551ca5a90c42">Taxe d\'aéroport</li><li data-list-item-id="e76eb00c159fe609d319cbf81974ed8fd">Service de portage</li><li data-list-item-id="e1cc4535135e2d767b6fafc8aa29d78af">Hébergement à l\'hôtel&nbsp;</li><li data-list-item-id="eaf01991d1adab37bf2ca6f7fd2e7f0bf">Pourboires guide &amp; chauffeur</li><li data-list-item-id="e1cadc73e8b1505883ffb1bf721a2db91">Excursions optionnelles &amp; autres dépenses personnelles non mentionnées dans le programme</li></ul>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `inclusions` = VALUES(`inclusions`), `exclusions` = VALUES(`exclusions`), `updated_at` = NOW();

-- paket 41: waruga-heritage-batu-angus-coastal-escape
INSERT INTO `tour_translations` (`translatable_type`, `translatable_id`, `locale`, `title`, `description`, `inclusions`, `exclusions`, `created_at`, `updated_at`)
VALUES ('App\\Models\\ManadoTour', '41', 'fr', 'Patrimoine de Waruga &amp; Évasion Côtière à Batu Angus', '<h2 style="text-align:justify;">Découvrez le Patrimoine Culturel et la Beauté Volcanique du Nord Sulawesi</h2><p style="text-align:justify;">Allez au-delà des visites habituelles et découvrez deux facettes fascinantes du Nord Sulawesi en une seule expérience mémorable. Ce voyage réunit le riche patrimoine culturel du peuple Minahasa avec le paysage volcanique saisissant et la vie marine vibrante de Batu Angus.</p><p style="text-align:justify;">Commencez votre découverte par le fascinant patrimoine de <strong>Waruga Sawangan</strong>, où des sarcophages de pierre traditionnels offrent un aperçu de l\'histoire et des traditions culturelles du peuple Minahasa. Bien plus qu\'un ancien site funéraire, Waruga offre un lien unique avec les traditions et les récits qui ont façonné la communauté locale depuis des générations.</p><p style="text-align:justify;">L\'expérience se poursuit ensuite vers le paysage côtier saisissant de <strong>Batu Angus</strong>, où d\'anciennes coulées de lave volcanique ont créé un environnement naturel distinctif le long du littoral. Le contraste entre les formations volcaniques sombres, l\'environnement tropical et les eaux claires de la mer crée un paysage véritablement unique au Nord Sulawesi.</p><p style="text-align:justify;">Sous la surface, Batu Angus révèle une autre facette de sa beauté naturelle. Ses eaux côtières claires offrent l\'occasion de découvrir des récifs coralliens colorés, des poissons tropicaux et une vie marine diversifiée tout en profitant d\'une expérience de snorkeling relaxante.</p><p style="text-align:justify;">Ce qui rend ce voyage spécial, c\'est la combinaison de <strong>culture, géologie, nature et exploration marine</strong> en une seule journée. C\'est une manière idéale de découvrir une facette du Nord Sulawesi qui va au-delà de ses plages célèbres et des visites touristiques traditionnelles.</p><h3 style="text-align:justify;">Pourquoi Vous Allez Adorer cette Expérience</h3><p style="text-align:justify;">• Découvrez le fascinant patrimoine culturel du peuple Minahasa</p><p style="text-align:justify;">• Explorez le site historique de Waruga Sawangan</p><p style="text-align:justify;">• Découvrez le paysage volcanique unique de Batu Angus</p><p style="text-align:justify;">• Découvrez des récifs coralliens colorés et une vie marine tropicale</p><p style="text-align:justify;">• Profitez du snorkeling dans des eaux côtières claires</p><p style="text-align:justify;">• Vivez le contraste entre un patrimoine ancestral et un paysage naturel saisissant</p><p style="text-align:justify;">• Combinez découverte culturelle, nature et aventure marine en un seul voyage</p><p style="text-align:justify;">• Idéal pour les amoureux de culture, les passionnés de nature, les photographes et les voyageurs actifs</p><h3 style="text-align:justify;">Bien plus qu\'une simple visite touristique, <strong>patrimoine de Waruga &amp; snorkeling à Batu Angus</strong> offre un voyage fascinant à travers les récits, les paysages et la beauté naturelle du Nord Sulawesi. Du patrimoine ancestral minahasa aux littoraux volcaniques et à la vie sous la mer, chaque expérience révèle une facette différente de cette destination remarquable.</h3>', '<ul><li data-list-item-id="ee44c315611f4315dc32a35e8ba7a8932"><p style="text-align:justify;">Transport&nbsp;</p></li><li data-list-item-id="e9aebf7e500b9218ae96e4a9735b5887c"><p style="text-align:justify;">Bateau &amp; équipement de snorkeling</p></li><li data-list-item-id="ea78c4cba10fab0194db11ca30051e78c"><p style="text-align:justify;">Guide de tour, chauffeur &amp; batelier expérimentés</p></li><li data-list-item-id="e763a6a58cf17409d04eff769ee730b2b"><p style="text-align:justify;">Frais d\'entrée aux sites touristiques &amp; frais de parking</p></li><li data-list-item-id="ea46383f45241738ea5e48e7cbee46faa"><p style="text-align:justify;">Déjeuner &amp; 1 bouteille d\'eau minérale par personne</p></li><li data-list-item-id="e867486aa2ffffd707bde11fb9e6db2af"><p style="text-align:justify;">Services de tour selon l\'itinéraire</p></li></ul>', '<ul><li data-list-item-id="e369b588efdeecf96f0f185253b99bd9d">Billet d\'avion&nbsp;</li><li data-list-item-id="ee1063332712c6f3757ec551ca5a90c42">Taxe d\'aéroport</li><li data-list-item-id="e76eb00c159fe609d319cbf81974ed8fd">Service de portage</li><li data-list-item-id="e1cc4535135e2d767b6fafc8aa29d78af">Hébergement à l\'hôtel&nbsp;</li><li data-list-item-id="eaf01991d1adab37bf2ca6f7fd2e7f0bf">Pourboires guide &amp; chauffeur</li><li data-list-item-id="e1cadc73e8b1505883ffb1bf721a2db91">Excursions optionnelles &amp; autres dépenses personnelles non mentionnées dans le programme</li></ul>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `inclusions` = VALUES(`inclusions`), `exclusions` = VALUES(`exclusions`), `updated_at` = NOW();

-- paket 21 hari 1 (itinerary 2749)
INSERT INTO `itinerary_translations` (`itinerary_id`, `locale`, `title`, `description`, `created_at`, `updated_at`)
VALUES ('2749', 'fr', 'Itinéraire', '<p style="text-align:justify;">Rendez-vous à 8h00 avec le guide au <strong>quai de Megamas </strong>pour une excursion d\'une journée vers l\'<strong>île de Bunaken</strong>. Depuis le quai de Megamas, traversez vers l\'<strong>île de Bunaken </strong>en bateau (environ 30 minutes). Bunaken a désormais été magnifiquement rénovée avec son nouveau <strong>quai touristique de Bunaken (New Bunaken)</strong>, plus représentatif, où les participants pourront capturer de superbes photos et vidéos avec des vues panoramiques sur l\'île.&nbsp;</p><p style="text-align:justify;">&nbsp;</p><p style="text-align:justify;">Découvrez la beauté sous-marine du Parc marin de Bunaken, refuge de récifs coralliens vibrants et de poissons tropicaux colorés, à travers des activités <i>en option </i>de snorkeling ou de plongée. Les participants pourront également profiter de temps libre pour se détendre et explorer l\'atmosphère paisible de la plage de l\'île. Le déjeuner sera servi dans un restaurant local en bord de mer.&nbsp;</p><p style="text-align:justify;">&nbsp;</p><p style="text-align:justify;">Après le déjeuner, profitez de plus de temps libre ou poursuivez le snorkeling/la plongée (en option). Dans l\'après-midi, retour au quai de Megamas, Manado. Fin de l\'excursion.</p>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `updated_at` = NOW();

-- paket 19 hari 1 (itinerary 2751)
INSERT INTO `itinerary_translations` (`itinerary_id`, `locale`, `title`, `description`, `created_at`, `updated_at`)
VALUES ('2751', 'fr', 'Itinéraire', '<p style="text-align:justify;">Les participants seront pris en charge au point de rendez-vous le matin et transférés vers le <strong>lieu de rafting </strong>au <strong>village de Timbukar,</strong> à Sonder. Avant de commencer l\'activité de rafting, les participants recevront une brève formation, incluant les mouvements de base et les consignes de sécurité pour maintenir leur équilibre sur le canot pneumatique.&nbsp;</p><p style="text-align:justify;">&nbsp;</p><p style="text-align:justify;">Pendant l\'excursion de rafting, les participants seront accompagnés de deux guides de rafting expérimentés équipés de matériel de sécurité aux normes internationales. En naviguant les rapides palpitants de la rivière Nimanga, les participants pourront également profiter du magnifique paysage naturel tout au long des quelque 90 minutes de parcours.&nbsp;</p><p style="text-align:justify;">&nbsp;</p><p style="text-align:justify;">Retour ensuite à la ville de Manado avec dépose au point de rendez-vous. Fin de l\'excursion.</p>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `updated_at` = NOW();

-- paket 17 hari 1 (itinerary 2753)
INSERT INTO `itinerary_translations` (`itinerary_id`, `locale`, `title`, `description`, `created_at`, `updated_at`)
VALUES ('2753', 'fr', 'Itinéraire', '<p style="text-align:justify;"><strong>Le mont Lokon</strong> est l\'une des plus grandes montagnes de Tomohon, un volcan actif s\'élevant à 1 580 mètres d\'altitude. Comme son nom l\'indique, « Lokon » signifie le plus ancien et le plus grand. Son cratère actif, connu sous le nom de <strong>cratère Tompaluan</strong>, se trouve à la base de la montagne.&nbsp;</p><p style="text-align:justify;">&nbsp;</p><p style="text-align:justify;">Depuis le point de prise en charge, vous roulerez jusqu\'à Tomohon ou au pied du mont Lokon (environ 1 heure 30), puis poursuivrez avec une randonnée d\'environ 2 heures pour atteindre le bord du cratère. Actuellement, le sentier ne va pas au-delà du cratère, situé à peu près à mi-chemin du sommet.&nbsp;</p><p style="text-align:justify;">&nbsp;</p><p style="text-align:justify;">Le mont Lokon offre un paysage naturel spectaculaire et un défi palpitant pour les randonneurs. Le long du sentier, vous pourrez admirer des vues à couper le souffle, y compris le magnifique panorama de la ville de Tomohon.&nbsp;</p><p style="text-align:justify;">&nbsp;</p><p style="text-align:justify;">Après cette aventure de trekking, direction un restaurant local pour le déjeuner. Après le repas, retour à la ville de Manado avec dépose au point indiqué. Fin de l\'excursion.</p>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `updated_at` = NOW();

-- paket 15 hari 1 (itinerary 2755)
INSERT INTO `itinerary_translations` (`itinerary_id`, `locale`, `title`, `description`, `created_at`, `updated_at`)
VALUES ('2755', 'fr', 'Itinéraire', '<p style="text-align:justify;">Les participants seront pris en charge le matin pour une excursion à la plage de Rap-Rap. À l\'arrivée, ils vivront une expérience unique sur cette magnifique plage, en commençant par une balade en pirogue à travers les eaux calmes entourant la mangrove luxuriante. En quelques minutes, les participants partiront à la recherche du <strong>tarsier</strong>, un fascinant petit primate souvent observé parmi les palétuviers.&nbsp;</p><p style="text-align:justify;">&nbsp;</p><p style="text-align:justify;">L\'atmosphère naturelle sereine et les sons de la forêt accompagnent ce voyage, créant un moment inoubliable au cœur de la beauté de la nature du Nord Sulawesi. En apercevant le <strong>tarsier</strong>, les participants sont libres de prendre des photos et de capturer ce moment.&nbsp;</p><p style="text-align:justify;">&nbsp;</p><p style="text-align:justify;">Ensuite, l\'excursion reprend vers le littoral de Rap-Rap avant de rejoindre les hauteurs du mont Tumpa, où les participants pourront admirer un magnifique <strong>coucher de soleil</strong> depuis les contreforts tout en dégustant <strong>diverses collations traditionnelles de Manado</strong> comme la banane frite au sambal roa, la patate douce frite au sucre de palme et la glace pilée aux haricots rouges <i>(en option, à la charge du participant)</i>. Les participants seront ensuite reconduits au point de rendez-vous. Fin de l\'excursion.</p>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `updated_at` = NOW();

-- paket 14 hari 1 (itinerary 2756)
INSERT INTO `itinerary_translations` (`itinerary_id`, `locale`, `title`, `description`, `created_at`, `updated_at`)
VALUES ('2756', 'fr', 'Itinéraire', '<p style="text-align:justify;">Rendez-vous au mont Tumpa à 10h00.</p><p style="text-align:justify;">&nbsp;</p><p style="text-align:justify;">Le parapente au <strong>mont Tumpa </strong>est une expérience inoubliable pour les amateurs d\'aventure comme pour les passionnés de nature. En vol à environ 1 000 mètres d\'altitude, vous ressentirez la sensation grisante de planer librement comme un oiseau tout en admirant des vues à couper le souffle sur le paysage montagneux, les forêts verdoyantes et la mer bleue cristalline en contrebas.&nbsp;</p><p style="text-align:justify;">&nbsp;</p><p style="text-align:justify;">Le site de parapente du mont Tumpa est également un lieu sûr et idéal pour les débutants comme pour ceux qui souhaitent perfectionner leurs compétences, grâce à des conditions météorologiques stables et des vents doux. Vous serez accompagné d\'instructeurs de parapente professionnels et équipé de matériel de sécurité adéquat.&nbsp;</p><p style="text-align:justify;">&nbsp;</p><p style="text-align:justify;">Le parapente au mont Tumpa est une expérience à la fois palpitante et magnifique qui rendra votre voyage à Manado véritablement inoubliable.</p>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `updated_at` = NOW();

-- paket 27 hari 1 (itinerary 4915)
INSERT INTO `itinerary_translations` (`itinerary_id`, `locale`, `title`, `description`, `created_at`, `updated_at`)
VALUES ('4915', 'fr', 'Itinéraire', '<p style="text-align:justify;">Après le petit-déjeuner à votre hôtel de Manado, départ vers le <strong>mont Soputan</strong>, l\'un des volcans les plus actifs du Nord Sulawesi, célèbre pour son paysage volcanique saisissant et ses panoramas naturels à couper le souffle.</p><p style="text-align:justify;">🕐 <strong>Temps de trajet de Manado au pied du mont Soputan :</strong> environ <strong>2,5 à 3 heures en voiture</strong>, selon la circulation et les conditions météorologiques.</p><p style="text-align:justify;">Tout au long du trajet, profitez de paysages campagnards pittoresques, de plantations de cocotiers et des magnifiques reliefs montagneux du Nord Sulawesi, faisant du trajet lui-même une partie de l\'expérience.</p><p style="text-align:justify;">À l\'arrivée au point de départ du trekking, préparez-vous pour une ascension palpitante vers le <strong>mont Soputan</strong>. L\'itinéraire de trekking combine de manière unique des sentiers forestiers luxuriants, une savane ouverte, des formations rocheuses volcaniques et des paysages spectaculaires façonnés par une ancienne activité volcanique.</p><p style="text-align:justify;">🕐 <strong>Durée estimée du trekking (aller-retour) :</strong> environ <strong>4 à 5 heures</strong>, selon les conditions météorologiques, le niveau de forme physique et le rythme de marche.</p><p style="text-align:justify;">📸 Profitez de panoramas époustouflants et d\'un relief volcanique saisissant tout au long du parcours — une expérience gratifiante pour les amoureux de la nature, les photographes et les amateurs d\'aventure.</p><p style="text-align:justify;">Après le trekking, retour au véhicule et transfert vers votre hôtel à Manado pour un repos bien mérité.</p>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `updated_at` = NOW();

-- paket 26 hari 1 (itinerary 5010)
INSERT INTO `itinerary_translations` (`itinerary_id`, `locale`, `title`, `description`, `created_at`, `updated_at`)
VALUES ('5010', 'fr', 'Itinéraire', '<p style="text-align:justify;">Rendez-vous à 8h00 avec le guide au <strong>quai de Megamas </strong>pour une excursion d\'une journée d\'<strong>île en île. </strong>Depuis le quai de Megamas, traversez vers l\'<strong>île de Bunaken </strong>en bateau (environ 30 minutes).&nbsp;</p><p style="text-align:justify;">&nbsp;</p><p style="text-align:justify;">À l\'arrivée, les visiteurs découvriront le <strong>Parc marin de Bunaken</strong>, réputé pour ses magnifiques récifs coralliens et ses milliers d\'espèces de poissons colorés autour de l\'<strong>île de Bunaken</strong>. L\'<strong>île de Bunaken</strong> dispose désormais d\'une zone plus attrayante et bien aménagée, incluant le <strong>quai touristique de Bunaken</strong>, où les participants peuvent prendre des photos avec leur famille et leurs amis.&nbsp;</p><p style="text-align:justify;">&nbsp;</p><p style="text-align:justify;">Ensuite, les visiteurs pourront profiter d\'activités optionnelles de snorkeling ou de plongée ; ils pourront également nager en nourrissant les poissons directement à la main. Le déjeuner sera servi dans un restaurant local sur l\'<strong>île de Bunaken</strong>.&nbsp;</p><p style="text-align:justify;">&nbsp;</p><p style="text-align:justify;">Après le déjeuner, direction l\'<strong>île de Siladen</strong> et le <strong>banc de sable de Nain</strong>. Sur chaque île, les participants pourront capturer des moments en photo ou en vidéo, se promener, et profiter de la beauté naturelle de l\'<strong>île de Siladen</strong> et du <strong>banc de sable de Nain</strong>.&nbsp;</p><p style="text-align:justify;">&nbsp;</p><p style="text-align:justify;">Dans l\'après-midi, retour au quai de Megamas, Manado. Fin de l\'excursion.</p>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `updated_at` = NOW();

-- paket 22 hari 1 (itinerary 5018)
INSERT INTO `itinerary_translations` (`itinerary_id`, `locale`, `title`, `description`, `created_at`, `updated_at`)
VALUES ('5018', 'fr', 'Itinéraire', '<p style="text-align:justify;">Les participants seront pris en charge par le guide au point de prise en charge et commenceront immédiatement le circuit urbain : direction le centre-ville de Manado, le quartier chinois, et le <strong>temple Ban Hin Kiong</strong> (le plus ancien temple de Manado, construit au 18e siècle, environ 300 ans).&nbsp;</p><p style="text-align:justify;">&nbsp;</p><p style="text-align:justify;">Le circuit passera également par l\'<strong>église Sentrum</strong> (la première église protestante du Nord Sulawesi, vestige de l\'époque coloniale néerlandaise) et le Monument de la Seconde Guerre mondiale (rappel de la destruction de la ville de Manado en 1942 par les troupes japonaises). Le déjeuner sera servi dans un <strong>restaurant local proposant une spécialité de thon</strong>, cuisinée selon la tradition manadaise.&nbsp;</p><p style="text-align:justify;">&nbsp;</p><p style="text-align:justify;">Ensuite, le circuit se dirige vers la zone de Ring Road CitraLand pour admirer de plus près le charme du <strong>Monument de Jésus Bénissant</strong> — une statue de Jésus construite dans une position flottante unique, face à la ville de Manado. Le circuit se poursuit ensuite vers la <strong>colline de Makatete</strong> — un sommet à 200 mètres d\'altitude offrant des vues sur la ville de Manado, l\'île de Manado, l\'île de Bunaken, l\'île de Siladen, l\'immensité de la mer, et le mont Klabat, la plus haute montagne du Nord Sulawesi.&nbsp;</p><p style="text-align:justify;">&nbsp;</p><p style="text-align:justify;">Le dîner est en option. Après le dîner, les participants seront redéposés au point de prise en charge. Le circuit se termine.</p>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `updated_at` = NOW();

-- paket 20 hari 1 (itinerary 5019)
INSERT INTO `itinerary_translations` (`itinerary_id`, `locale`, `title`, `description`, `created_at`, `updated_at`)
VALUES ('5019', 'fr', 'Itinéraire', '<p style="text-align:justify;">Les participants du circuit seront pris en charge le matin par le guide pour un voyage vers les <strong>hauts plateaux de Minahasa</strong>, en passant par la zone de <strong>Tinoor</strong> où les participants pourront profiter d\'une vue sur la ville de Manado depuis une altitude de 500 mètres. À l\'arrivée à Tomohon, le groupe visitera le <strong>Taman Wisata Pelangi</strong>, où ils pourront admirer la beauté de diverses fleurs colorées.&nbsp;</p><p style="text-align:justify;">&nbsp;</p><p style="text-align:justify;">L\'étape suivante est le <strong>marché extrême de Tomohon</strong>, où les participants pourront observer de près divers types de viandes d\'animaux sauvages, comme <i><strong>le paniki (chauve-souris), les rats des forêts, les serpents et d\'autres animaux sauvages</strong></i>. Sur un autre site, les participants auront également l\'occasion d\'assister à la <strong>préparation en direct</strong> de gâteaux traditionnels de Manado comme le <strong>cucur, l\'apang au sucre de palme, le dodol</strong>, et d\'autres douceurs locales.&nbsp;</p><p style="text-align:justify;">&nbsp;</p><p style="text-align:justify;">Ensuite, l\'excursion se dirige vers la <strong>palmeraie d\'aren</strong> avec des spots photo dignes d\'Instagram à <strong>Tuur Maasering</strong>. Outre ces spots photo intéressants, les participants observeront également le processus de fabrication de la liqueur <i><strong>locale </strong></i><strong>« Cap Tikus »</strong>, produite par fermentation et distillation de la sève de l\'arbre aren.&nbsp;</p><p style="text-align:justify;">&nbsp;</p><p style="text-align:justify;">Le déjeuner sera servi dans un restaurant local au bord du <strong>lac Tondano</strong>. Après le déjeuner, le voyage se poursuit vers <strong>Bukit Kasih</strong>, une attraction naturelle unique dotée de cratères de soufre actifs et d\'escaliers menant au sommet de la colline, offrant des vues panoramiques et une expérience culturelle distinctive. La zone possède également des sources chaudes soufrées naturelles où les visiteurs peuvent se baigner ou se tremper les pieds pour se détendre (en option).&nbsp;</p><p style="text-align:justify;">&nbsp;</p><p style="text-align:justify;">Le voyage se poursuit vers le <strong>lac Linow</strong>, un lac de soufre connu pour ses eaux changeant de couleur et son paysage magnifique et paisible (café ou thé servi). Retour ensuite à la ville de Manado. Le dîner est en option. Après le dîner, les participants seront transférés au point de dépose indiqué. Fin de l\'excursion.</p>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `updated_at` = NOW();

-- paket 30 hari 1 (itinerary 5156)
INSERT INTO `itinerary_translations` (`itinerary_id`, `locale`, `title`, `description`, `created_at`, `updated_at`)
VALUES ('5156', 'fr', 'Arrivée à Manado - Paradise Golf Resort', '<p style="text-align:justify;">Dès l\'arrivée à l\'aéroport international Sam Ratulangi de Manado, notre équipe vous accueillera et vous transférera directement au Paradise Hotel &amp; Golf Resort. Le trajet offre l\'atmosphère calme et rafraîchissante de la côte du Nord Sulawesi.</p><p style="text-align:justify;">À l\'arrivée au complexe, enregistrement et le reste de la journée est libre pour vous détendre avec les installations de l\'hôtel, les vues sur le parcours de golf, ou simplement le cadre tropical confortable. Le premier jour est conçu comme un moment pour se détendre avant que l\'expérience de golf ne débute le matin suivant.</p><p style="text-align:justify;">Nuit au Paradise Hotel &amp; Golf Resort.</p>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `updated_at` = NOW();

-- paket 30 hari 2 (itinerary 5157)
INSERT INTO `itinerary_translations` (`itinerary_id`, `locale`, `title`, `description`, `created_at`, `updated_at`)
VALUES ('5157', 'fr', 'Expérience Paradise Golf (18 Trous)', '<p style="text-align:justify;">Après le petit-déjeuner à l\'hôtel, profitez d\'une partie au Paradise Golf Course, qui combine des fairways stimulants avec un paysage naturel saisissant.</p><p style="text-align:justify;">La partie de 18 trous inclut le green fee, la voiturette de golf et le caddie, afin que vous puissiez vous concentrer sur votre jeu en toute tranquillité. Après la partie, le temps libre peut être consacré à la détente au complexe ou aux activités en option disponibles autour de la zone de l\'hôtel.</p><p style="text-align:justify;">Nuit au Paradise Hotel &amp; Golf Resort.</p>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `updated_at` = NOW();

-- paket 30 hari 3 (itinerary 5158)
INSERT INTO `itinerary_translations` (`itinerary_id`, `locale`, `title`, `description`, `created_at`, `updated_at`)
VALUES ('5158', 'fr', 'Expérience Paradise Golf (18 Trous)', '<p style="text-align:justify;">Petit-déjeuner à l\'hôtel avant la deuxième session de golf. Aujourd\'hui est l\'occasion de rejouer le parcours et d\'apprécier le caractère unique de chaque trou, dans le cadre tropical calme et l\'air frais caractéristiques du Nord Sulawesi.</p><p style="text-align:justify;">Après la partie, profitez de temps libre pour vous reposer, utiliser les installations du complexe, ou vous joindre à des activités en option comme le snorkeling ou le bateau à fond de verre disponibles dans la zone du complexe.</p><p style="text-align:justify;">Nuit au Paradise Hotel &amp; Golf Resort.</p>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `updated_at` = NOW();

-- paket 30 hari 4 (itinerary 5159)
INSERT INTO `itinerary_translations` (`itinerary_id`, `locale`, `title`, `description`, `created_at`, `updated_at`)
VALUES ('5159', 'fr', 'Départ de Manado', '<p style="text-align:justify;">Après le petit-déjeuner et l\'enregistrement de départ à l\'hôtel, vous aurez du temps libre avant le départ.</p><p style="text-align:justify;">À l\'heure convenue, notre équipe vous transférera vers l\'aéroport international Sam Ratulangi de Manado pour votre vol de continuation. Alors que ce voyage touche à sa fin, nous espérons que votre golf au Paradise Golf Resort restera un souvenir agréable de votre séjour au Nord Sulawesi.</p><p style="text-align:justify;"><strong>Fin du Programme</strong></p>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `updated_at` = NOW();

-- paket 29 hari 1 (itinerary 5160)
INSERT INTO `itinerary_translations` (`itinerary_id`, `locale`, `title`, `description`, `created_at`, `updated_at`)
VALUES ('5160', 'fr', 'Arrivée à Manado - Paradise Golf Resort', '<p style="text-align:justify;">Dès l\'arrivée à l\'aéroport international Sam Ratulangi de Manado, notre équipe vous accueillera et vous transférera au Paradise Hotel &amp; Golf Resort sur la côte du Nord Sulawesi. Le trajet dure environ 60 à 90 minutes, avec de belles campagnes et un littoral en chemin.</p><p style="text-align:justify;">À l\'arrivée au complexe, enregistrement et le reste de la journée est libre pour vous détendre dans son cadre paisible, profiter des installations de l\'hôtel, ou admirer les vues sur le parcours de golf surplombant la mer. Le premier jour est conçu comme un moment pour se détendre avant que les activités principales ne débutent le matin suivant.</p><p style="text-align:justify;">Nuit au Paradise Hotel &amp; Golf Resort.</p>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `updated_at` = NOW();

-- paket 29 hari 2 (itinerary 5161)
INSERT INTO `itinerary_translations` (`itinerary_id`, `locale`, `title`, `description`, `created_at`, `updated_at`)
VALUES ('5161', 'fr', 'Expérience Paradise Golf (18 Trous)', '<p style="text-align:justify;">Après le petit-déjeuner, profitez d\'une partie sur l\'un des plus beaux parcours de golf du Nord Sulawesi. Le parcours combine des fairways stimulants avec l\'air marin frais et des panoramas tropicaux qu\'il est agréable de traverser.</p><p style="text-align:justify;">La partie de 18 trous inclut le green fee, la voiturette de golf et le caddie, afin que vous puissiez jouer en toute tranquillité. Ensuite, le temps libre peut être consacré au repos, à l\'utilisation des installations du complexe, ou simplement à la détente dans le cadre tropical apaisant.</p><p style="text-align:justify;">Nuit au Paradise Hotel &amp; Golf Resort.</p>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `updated_at` = NOW();

-- paket 29 hari 3 (itinerary 5162)
INSERT INTO `itinerary_translations` (`itinerary_id`, `locale`, `title`, `description`, `created_at`, `updated_at`)
VALUES ('5162', 'fr', 'Expérience d\'Observation de l\'Île de Bunaken', '<p style="text-align:justify;">Après le petit-déjeuner et l\'enregistrement de départ du complexe, poursuite vers la ville de Manado et le quai de Megamas. De là, vous traverserez en bateau vers l\'île de Bunaken, un trajet d\'environ 45 minutes.</p><p style="text-align:justify;">À l\'arrivée à Bunaken, profitez d\'un moment pour explorer la zone rénovée de New Bunaken, avec ses nombreux endroits attrayants donnant directement sur la mer bleue de Sulawesi. L\'île offre de magnifiques paysages de plage, une atmosphère tropicale calme, et de nombreux lieux idéaux pour la photographie et simplement pour profiter de la beauté naturelle.</p><p style="text-align:justify;">Pour celles et ceux qui souhaitent explorer davantage, snorkeling et plongée sont disponibles en option pour découvrir le célèbre Parc Marin de Bunaken. Le déjeuner est servi avec du poisson grillé frais et le sambal dabu-dabu signature de Manado.</p><p style="text-align:justify;">Dans l\'après-midi, retour à Manado et poursuite vers votre hôtel sélectionné au centre-ville pour l\'enregistrement et le repos.</p><p style="text-align:justify;">Nuit dans un hôtel sélectionné à Manado.</p>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `updated_at` = NOW();

-- paket 29 hari 4 (itinerary 5163)
INSERT INTO `itinerary_translations` (`itinerary_id`, `locale`, `title`, `description`, `created_at`, `updated_at`)
VALUES ('5163', 'fr', 'Départ de Manado', '<p style="text-align:justify;">Après le petit-déjeuner à l\'hôtel, vous aurez du temps libre avant le départ. À l\'heure convenue, notre équipe viendra vous chercher et vous transférera vers l\'aéroport international Sam Ratulangi de Manado pour votre vol de continuation.</p><p style="text-align:justify;">Alors que ce voyage touche à sa fin, nous espérons que le golf en bord de mer et la beauté de l\'île de Bunaken resteront un souvenir agréable de vos vacances au Nord Sulawesi.</p><p style="text-align:justify;"><strong>Fin du Programme</strong></p>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `updated_at` = NOW();

-- paket 32 hari 1 (itinerary 5221)
INSERT INTO `itinerary_translations` (`itinerary_id`, `locale`, `title`, `description`, `created_at`, `updated_at`)
VALUES ('5221', 'fr', 'Arrivée à Manado – Transfert vers l\'Île de Bangka', '<p style="text-align:justify;">Dès l\'arrivée à l\'aéroport international Sam Ratulangi de Manado, notre équipe vous accueillera et débutera le trajet vers le quai pour la traversée vers l\'île de Bangka. Le transfert combiné par route et par mer vers le complexe dure environ 2 heures, en suivant la magnifique côte nord de Sulawesi avec vue sur la mer et ses charmantes îles tropicales.</p><p style="text-align:justify;">À l\'arrivée au <strong>Dive Resort</strong>, enregistrement et temps libre pour vous détendre, vous promener dans les environs, ou profiter de l\'atmosphère paisible de la plage. Le dîner est servi au complexe avant que vous vous reposiez et vous prépariez pour l\'aventure sous-marine qui débute le matin suivant.</p>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `updated_at` = NOW();

-- paket 32 hari 2 (itinerary 5222)
INSERT INTO `itinerary_translations` (`itinerary_id`, `locale`, `title`, `description`, `created_at`, `updated_at`)
VALUES ('5222', 'fr', 'Expérience de Plongée à Bangka', '<p style="text-align:justify;">Après le petit-déjeuner, profitez de la plongée sur une sélection de sites autour de l\'archipel de Bangka, une zone connue pour sa combinaison de coraux mous colorés, de coraux durs sains, et d\'une biodiversité marine extraordinaire.</p><p style="text-align:justify;">Les eaux de Bangka offrent un caractère unique qui combine la plongée sur paroi caractéristique de Bunaken avec le muck diving réputé de Lembeh Strait. Pendant les plongées, vous aurez l\'occasion de rencontrer diverses espèces de poissons tropicaux, de la vie marine macro, et des formations sous-marines spectaculaires.</p><p style="text-align:justify;">Une fois la plongée du jour terminée, retour au complexe et temps libre pour vous détendre dans le cadre paisible de l\'île.</p>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `updated_at` = NOW();

-- paket 32 hari 3 (itinerary 5223)
INSERT INTO `itinerary_translations` (`itinerary_id`, `locale`, `title`, `description`, `created_at`, `updated_at`)
VALUES ('5223', 'fr', 'Expérience de Plongée à Bangka', '<p style="text-align:justify;">Petit-déjeuner au complexe avant de poursuivre l\'exploration du monde sous-marin de Bangka. Aujourd\'hui vous visiterez différents sites de plongée offrant des paysages variés, des récifs colorés et pitons sous-marins aux parois submergées abritant une grande variété d\'espèces marines tropicales.</p><p style="text-align:justify;">Avec plus de 40 sites de plongée répartis dans l\'archipel de Bangka, chaque plongée apporte quelque chose de nouveau pour les débutants comme pour les plongeurs expérimentés.</p><p style="text-align:justify;">Retour au complexe dans l\'après-midi et temps libre pour vous détendre sur la plage ou aux installations du complexe.</p>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `updated_at` = NOW();

-- paket 32 hari 4 (itinerary 5224)
INSERT INTO `itinerary_translations` (`itinerary_id`, `locale`, `title`, `description`, `created_at`, `updated_at`)
VALUES ('5224', 'fr', 'Expérience de Plongée à Bangka', '<p style="text-align:justify;">Après le petit-déjeuner, poursuite de l\'aventure de plongée pour explorer davantage la beauté sous-marine de l\'archipel de Bangka. La zone est considérée comme une des meilleures destinations de plongée du Nord Sulawesi, avec des eaux claires et un écosystème marin qui reste remarquablement bien préservé.</p><p style="text-align:justify;">Profitez de cette dernière occasion pour observer la richesse de la vie marine tropicale, les récifs coralliens sains, et les panoramas sous-marins qui font de Bangka un joyau caché pour les amoureux de plongée en Indonésie.</p><p style="text-align:justify;">Après les plongées, retour au complexe pour un après-midi détendu et votre dernier dîner sur l\'île.</p>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `updated_at` = NOW();

-- paket 32 hari 5 (itinerary 5225)
INSERT INTO `itinerary_translations` (`itinerary_id`, `locale`, `title`, `description`, `created_at`, `updated_at`)
VALUES ('5225', 'fr', 'Île de Bangka - Départ', '<p style="text-align:justify;">Après le petit-déjeuner et l\'enregistrement de départ, le voyage de retour vers Manado débute par un transfert en bateau vers le continent, puis poursuite vers l\'aéroport international Sam Ratulangi de Manado ou votre hôtel sélectionné en ville.</p><p style="text-align:justify;">Alors que ce voyage touche à sa fin, nous espérons que l\'exploration de la beauté sous-marine de l\'archipel de Bangka restera un souvenir inoubliable et une nouvelle histoire de l\'une des meilleures destinations de plongée du Nord Sulawesi.</p><p style="text-align:justify;"><strong>Fin du Programme</strong></p>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `updated_at` = NOW();

