VALUES ('5226', 'fr', 'Arrivée à Manado - Transfert vers l\'Île de Lembeh', '<p style="text-align:justify;">Dès l\'arrivée à l\'aéroport international Sam Ratulangi de Manado, notre équipe vous accueillera et débutera directement le trajet vers le quai pour la traversée vers l\'île de Lembeh. Le transfert vers le complexe dure environ 1 heure 40, combinant trajet routier et transfert en bateau le long de la magnifique côte du Nord Sulawesi.</p><p style="text-align:justify;">À l\'arrivée au complexe, enregistrement et temps libre pour vous reposer, vous promener dans les environs, ou profiter du calme de l\'île de Lembeh, connue comme une des meilleures destinations de plongée au monde. Le dîner sera servi au complexe avant que vous vous reposiez et vous prépariez pour l\'aventure sous-marine qui débute le matin suivant.</p><p style="text-align:justify;">&nbsp;</p>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `updated_at` = NOW();

-- paket 33 hari 2 (itinerary 5227)
INSERT INTO `itinerary_translations` (`itinerary_id`, `locale`, `title`, `description`, `created_at`, `updated_at`)
VALUES ('5227', 'fr', 'Expérience de Plongée au Détroit de Lembeh', '<p style="text-align:justify;">Après le petit-déjeuner, l\'aventure de plongée débute sur une sélection de sites du détroit de Lembeh, réputé comme un des meilleurs lieux de muck diving au monde. Son fond de sable noir volcanique crée un habitat unique qui abrite une variété étonnante d\'espèces marines rares et exotiques.</p><p style="text-align:justify;">Pendant les plongées, vous pourrez rencontrer diverses créatures prisées par les photographes sous-marins, des poissons-grenouilles et nudibranches aux espèces qu\'il est difficile de rencontrer ailleurs. Après deux plongées matinales, retour au complexe pour un après-midi détendu et le dîner.</p>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `updated_at` = NOW();

