INSERT INTO `itinerary_translations` (`itinerary_id`, `locale`, `title`, `description`, `created_at`, `updated_at`)
VALUES ('5228', 'fr', 'Aventure de Plongée Macro à Lembeh', '<p style="text-align:justify;">Petit-déjeuner au complexe avant de poursuivre l\'exploration du monde sous-marin du détroit de Lembeh. Aujourd\'hui vous retournerez sur une sélection de sites de plongée offrant une extraordinaire vie marine macro et une plongée confortable dans des courants relativement calmes.</p><p style="text-align:justify;">Chaque plongée apporte la chance de trouver quelque chose de différent, ce qui fait de Lembeh un lieu favori des photographes sous-marins et des plongeurs qui souhaitent découvrir une facette de la vie marine rarement rencontrée ailleurs. Après les plongées, retour au complexe et après-midi détendu sur la plage.</p>', NOW(), NOW())
