-- paket 39 hari 1 (itinerary 6223)
INSERT INTO `itinerary_translations` (`itinerary_id`, `locale`, `title`, `description`, `created_at`, `updated_at`)
VALUES ('6223', 'fr', 'Itinéraire', '<p style="text-align:justify;">Après le petit-déjeuner, notre équipe viendra vous chercher à votre hôtel de la ville de Manado. Le trajet se poursuit vers le quai de Serei Likupang, avec des paysages côtiers et campagnards typiques du Nord Sulawesi tout au long du chemin. À l\'arrivée au quai, embarquez sur un bateau privé vers les eaux entourant l\'île de Gangga, l\'une des meilleures destinations de snorkeling de la région de Likupang. Ici, vous pourrez profiter de récifs coralliens intacts, d\'une multitude de poissons tropicaux colorés et d\'une eau claire offrant une excellente visibilité.</p><p style="text-align:justify;">Après le snorkeling, poursuite vers l\'île de Lihaga, connue pour son sable blanc fin et sa mer turquoise. Profitez d\'un moment pour nager, vous détendre sur le rivage, faire le tour de l\'île, ou capturer l\'instant dans les nombreux spots photo au décor tropical saisissant. Le déjeuner est servi sur l\'île de Lihaga dans un cadre calme et naturel.</p><p style="text-align:justify;">Dans l\'après-midi, retour en bateau vers le quai de Serei Likupang avant de poursuivre par voie terrestre vers la ville de Manado. Avant de retourner à votre hôtel, arrêt au centre de souvenirs de Manado pour acheter des spécialités locales, de l\'artisanat et des souvenirs. Vous serez ensuite transféré à votre hôtel, avec une expérience inoubliable de deux des plus belles îles tropicales de Likupang.</p><p style="text-align:justify;"><strong>Fin de l\'Excursion</strong></p>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `updated_at` = NOW();

-- paket 24 hari 1 (itinerary 6888)
INSERT INTO `itinerary_translations` (`itinerary_id`, `locale`, `title`, `description`, `created_at`, `updated_at`)
VALUES ('6888', 'fr', 'Arrivée – Cascade de Tunan – Réserve Naturelle de Tangkoko', '<p style="text-align:justify;">Arrivée à Manado le matin. Rencontre avec notre guide, puis prise en charge pour se rendre à la <strong>cascade de Tunan</strong>, cette cascade se trouve au <strong>village de Talawan</strong>. La source de la <strong>cascade de Tunan</strong> provient de la rivière en amont de la montagne qui s\'écoule assez rapidement à travers des falaises abruptes d\'une hauteur d\'environ 86 mètres. L\'atmosphère de la forêt naturelle encore intacte et préservée ajoute à la beauté autour du site touristique naturel de la <strong>cascade de Tunan</strong>.&nbsp;</p><p style="text-align:justify;">&nbsp;</p><p style="text-align:justify;">Nous roulons directement vers le <strong>Parc National de Tangkoko</strong> (si vous arrivez dans l\'après-midi, passez l\'excursion à la cascade de Tunan et rendez-vous directement au village de Batu Putih à Tangkoko). En fin d\'après-midi, une courte randonnée dans la forêt à la recherche de la grande vedette du parc : le tarsier, le plus petit mammifère de la planète. Le homestay de Tangkoko sera votre lieu de résidence pour la nuit.</p>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `updated_at` = NOW();

-- paket 24 hari 2 (itinerary 6889)
INSERT INTO `itinerary_translations` (`itinerary_id`, `locale`, `title`, `description`, `created_at`, `updated_at`)
VALUES ('6889', 'fr', 'Journée Complète à Tangkoko', '<p style="text-align:justify;">Après le petit-déjeuner au homestay, commencez à explorer les espèces endémiques du Nord Sulawesi à la réserve naturelle de Tangkoko. Recherchez le macaque noir à crête (singe noir indigène du Nord Sulawesi), un autre tarsier (le plus petit primate du monde), l\'ours couscous, et de nombreux oiseaux. Le parc national abrite la plus forte densité de calaos au monde, incluant le calao rhinocéros. Après le déjeuner, nous partirons pour une autre excursion dans la jungle de Tangkoko dans l\'après-midi. Nuit au homestay.&nbsp;</p>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `updated_at` = NOW();

-- paket 24 hari 3 (itinerary 6890)
INSERT INTO `itinerary_translations` (`itinerary_id`, `locale`, `title`, `description`, `created_at`, `updated_at`)
VALUES ('6890', 'fr', 'Waruga Sawangan – Circuit des Hauts Plateaux de Minahasa', '<p style="text-align:justify;">Après le petit-déjeuner, départ et route vers les hauts plateaux, puis direction <strong>Waruga Sawangan</strong>, avec un arrêt à l\'ancienne tombe du peuple Minahasa (âge de pierre géant). Déjeuner au <strong>lac Tondano</strong>. Poursuite vers Tomohon pour voir le <strong>marché traditionnel</strong>, puis l\'industrie des maisons en bois démontables du <strong>village de Woloan</strong> (les habitants y créent de magnifiques maisons en bois de style minahasa qui sont démontées et expédiées hors du village), et <strong>Kai\'santi Tomohon</strong> qui est un arrêt photo avec en toile de fond le mont Lokon et de verdoyantes rizières.&nbsp;</p><p style="text-align:justify;">&nbsp;</p><p style="text-align:justify;">Nous passons l\'après-midi au <strong>lac Linow</strong> à déguster un café ou un thé. Enregistrement dans votre chambre dans un complexe hôtelier à Tomohon.&nbsp;</p>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `updated_at` = NOW();

-- paket 24 hari 4 (itinerary 6891)
INSERT INTO `itinerary_translations` (`itinerary_id`, `locale`, `title`, `description`, `created_at`, `updated_at`)
VALUES ('6891', 'fr', 'Mont Mahawu – Transfert vers l\'Aéroport', '<p style="text-align:justify;">Après le petit-déjeuner à l\'hôtel, départ. Rencontre avec notre guide, puis direction le <strong>cratère du mont Mahawu</strong>. Après une randonnée de 10 minutes jusqu\'au bord du cratère, vous serez récompensé par une vue à couper le souffle sur Tomohon et Manado, ainsi que sur les îles au-delà ; au fond du cratère, les visiteurs peuvent apercevoir un lac fumant et sentir le soufre s\'échappant des bassins. Ensuite, vous serez accompagné par notre guide vers l\'aéroport pour le transfert de départ.&nbsp;</p>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `updated_at` = NOW();

-- paket 25 hari 1 (itinerary 6892)
INSERT INTO `itinerary_translations` (`itinerary_id`, `locale`, `title`, `description`, `created_at`, `updated_at`)
VALUES ('6892', 'fr', 'Arrivée – Hauts Plateaux de Minahasa – Réserve Naturelle de Tangkoko', '<p style="text-align:justify;">Arrivée à Manado le matin. Rencontre avec notre guide, puis direction le <strong>cratère du mont Mahawu</strong>. Après une randonnée de 10 minutes jusqu\'au bord du cratère, vous serez récompensé par une vue à couper le souffle sur Tomohon et Manado, ainsi que sur les îles au-delà. Ensuite, visite du <strong>village de Woloan</strong>, centre de l\'industrie des maisons traditionnelles démontables, puis arrêt au <strong>temple bouddhiste Pagode</strong>, qui est un arrêt photo avec en toile de fond le mont Lokon. Moment de détente au <strong>lac Linow</strong> et à ses magnifiques couleurs changeantes, pour profiter de l\'après-midi dans un agréable restaurant au bord du lac en dégustant un café ou un thé.</p><p style="text-align:justify;">&nbsp;</p><p style="text-align:justify;">La randonnée se poursuit vers <strong>Waruga Sawangan</strong>, avec un arrêt à l\'ancienne tombe du peuple Minahasa (âge de pierre géant). Prenez la route vers Tangkoko. (Si vous arrivez dans l\'après-midi, passez l\'excursion aux hauts plateaux de Minahasa et rendez-vous directement au village de Batu Putih à Tangkoko.) Le homestay de Tangkoko sera votre lieu de résidence pour la nuit.&nbsp;</p>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `updated_at` = NOW();

