-- paket 25 hari 3 (itinerary 6894)
INSERT INTO `itinerary_translations` (`itinerary_id`, `locale`, `title`, `description`, `created_at`, `updated_at`)
VALUES ('6894', 'fr', 'Transfert vers l\'Aéroport', '<p style="text-align:justify;">Après le petit-déjeuner à l\'hôtel, départ. Visite en ville pour le shopping de souvenirs si le temps le permet. Ensuite, vous serez accompagné par notre guide vers l\'aéroport pour le transfert de départ. L\'excursion est terminée, merci.&nbsp;</p>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `updated_at` = NOW();

-- paket 13 hari 1 (itinerary 6895)
INSERT INTO `itinerary_translations` (`itinerary_id`, `locale`, `title`, `description`, `created_at`, `updated_at`)
VALUES ('6895', 'fr', 'Arrivée – Circuit de la Ville de Manado – Colline de Makatete – SunBae Manado', '<p style="text-align:justify;">Dès l\'arrivée à l\'aéroport Sam Ratulangi de Manado, le groupe sera accueilli par le guide et commencera un circuit dans la ville de Manado. Visite du centre-ville, du <strong>quartier chinois</strong>, et du <strong>temple Ban Hin Kiong</strong> - le plus ancien temple de Manado, construit au 18e siècle (environ 300 ans).&nbsp;Poursuite en passant par l\'<strong>église Sentrum</strong>, la première église protestante du Nord Sulawesi datant de l\'époque néerlandaise, et le <strong>Monument de la Seconde Guerre mondiale</strong>, qui commémore la destruction de Manado en 1942 par les forces japonaises.&nbsp;</p><p style="text-align:justify;">&nbsp;</p><p style="text-align:justify;">Le circuit se poursuit ensuite vers la zone de Ring Road de <strong>CitraLand</strong> pour admirer le <strong>Monument de Jésus Bénissant</strong>, une statue de Jésus construite dans une position penchée en avant unique, surplombant la ville de Manado.&nbsp;Ensuite, visite de la <strong>colline de Makatete</strong> - située à 200 mètres au-dessus du niveau de la mer, offrant des vues panoramiques sur la ville de Manado, l\'<strong>île de Manado Tua</strong>, l\'<strong>île de Bunaken</strong>, l\'<strong>île de Siladen</strong>, la mer ouverte, et le <strong>mont Klabat</strong>, le plus haut sommet du Nord Sulawesi.</p><p style="text-align:justify;">&nbsp;</p><p style="text-align:justify;">Dîner en option dans un restaurant local. Après le dîner, visite de <strong>SunBae</strong>, l\'un des lieux de rendez-vous branchés en bord de mer de Manado, où les visiteurs peuvent profiter de l\'ambiance du soir avec diverses collations et boissons proposées par de nombreux stands (en option). Ensuite, transfert vers l\'hôtel pour l\'enregistrement et le repos.</p>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `updated_at` = NOW();

-- paket 13 hari 2 (itinerary 6896)
INSERT INTO `itinerary_translations` (`itinerary_id`, `locale`, `title`, `description`, `created_at`, `updated_at`)
VALUES ('6896', 'fr', 'Circuit d\'Observation de Bunaken – Coopérative de Café Locale – Circuit Shopping', '<p style="text-align:justify;">Après le petit-déjeuner à l\'hôtel, les participants seront pris en charge par le guide et se dirigeront vers l\'<strong>île de Bunaken</strong>. Depuis l\'hôtel, transfert vers le quai de Megamas et traversée vers Bunaken en bateau pendant environ 30 minutes. L\'île de Bunaken dispose désormais du nouveau <strong>quai touristique de Bunaken (New Bunaken)</strong>, offrant un endroit plus charmant et photogénique pour les photos et vidéos.</p><p style="text-align:justify;">&nbsp;</p><p style="text-align:justify;">Ensuite, les participants seront emmenés explorer la beauté du <strong>Parc Marin de Bunaken</strong>, réputé pour ses récifs coralliens colorés et sa vie marine tropicale diversifiée. Les participants pourront profiter d\'activités <i>en option</i><strong> de snorkeling ou de plongée</strong>, ou simplement faire une promenade tranquille en profitant de l\'atmosphère de la plage de Bunaken.&nbsp; Déjeuner en option dans un restaurant local. Après le déjeuner, les visiteurs auront du temps libre supplémentaire pour le snorkeling/la plongée en option.</p><p style="text-align:justify;">&nbsp;</p><p style="text-align:justify;">Retour au quai de Megamas et visite d\'une <strong>coopérative locale de production de café</strong>, où les participants pourront goûter les saveurs authentiques du café du Nord Sulawesi. Ensuite, poursuite vers une <strong>zone de shopping de souvenirs</strong> proposant une grande variété de spécialités de Manado (ou retour à l\'hôtel puis nouvelle prise en charge avant le dîner). Dîner en option dans un restaurant local, puis transfert de retour vers l\'hôtel.</p>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `updated_at` = NOW();

-- paket 13 hari 3 (itinerary 6897)
INSERT INTO `itinerary_translations` (`itinerary_id`, `locale`, `title`, `description`, `created_at`, `updated_at`)
VALUES ('6897', 'fr', 'Transfert vers l\'Aéroport – Départ', '<p style="text-align:justify;">Après le petit-déjeuner et l\'enregistrement de départ à l\'hôtel, les participants seront pris en charge par le guide et transférés directement à l\'aéroport pour leur vol de retour. Fin de l\'excursion.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</p>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `updated_at` = NOW();

-- paket 12 hari 1 (itinerary 6898)
