ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `updated_at` = NOW();

-- paket 12 hari 2 (itinerary 6899)
INSERT INTO `itinerary_translations` (`itinerary_id`, `locale`, `title`, `description`, `created_at`, `updated_at`)
VALUES ('6899', 'fr', 'Circuit des Hauts Plateaux de Minahasa', '<p style="text-align:justify;">Après le petit-déjeuner à l\'hôtel, les participants seront pris en charge par le guide pour une excursion d\'une journée complète vers les <strong>Hauts Plateaux de Minahasa</strong>, en passant par la zone de Tinoor où les visiteurs pourront profiter de vues panoramiques sur la ville de Manado depuis une altitude de 500 mètres.&nbsp;</p><p style="text-align:justify;">&nbsp;</p><p style="text-align:justify;">À l\'arrivée à Tomohon, visite du <strong>Taman Wisata Pelangi</strong>, où les participants pourront admirer la beauté de diverses fleurs colorées. Poursuite vers le <strong>marché extrême de Tomohon</strong>, où les visiteurs pourront voir divers types de viandes d\'animaux sauvages comme des chauves-souris, des rats des forêts, des serpents et d\'autres animaux exotiques. Dans un autre lieu, les visiteurs pourront également assister au processus de <strong>préparation en direct</strong> de collations traditionnelles de Manado comme le <i>kue cucur</i>, l\'<i>apang gula merah</i>, le <i>dodol</i>, et d\'autres délices locaux.</p><p style="text-align:justify;">&nbsp;</p><p style="text-align:justify;">Le circuit se poursuit vers <strong>Tuur Maasering</strong>, une forêt d\'aren (palmiers) offrant plusieurs spots photo dignes d\'Instagram. Ici, les participants pourront également observer la fabrication traditionnelle de la liqueur locale <strong>« Cap Tikus »</strong>, produite par fermentation et distillation de la sève de l\'arbre aren.</p><p style="text-align:justify;">&nbsp;</p><p style="text-align:justify;">Déjeuner en option dans un restaurant local. Après le déjeuner, direction <strong>Bukit Kasih</strong>, une attraction naturelle unique dotée de cratères de soufre actifs et d\'escaliers menant au sommet de la colline, offrant des vues panoramiques et une expérience culturelle distinctive. La zone possède également des sources chaudes soufrées naturelles où les visiteurs peuvent se baigner ou se tremper les pieds pour se détendre (en option).</p><p style="text-align:justify;">&nbsp;</p><p style="text-align:justify;">Ensuite, visite du <strong>lac Linow</strong>, un lac de soufre réputé pour ses eaux changeant de couleur et son paysage magnifique, où un café ou un thé sera servi. Retour à la ville de Manado. Dîner en option dans un restaurant local, puis transfert de retour vers l\'hôtel.</p>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `updated_at` = NOW();

