-- paket 8 hari 3 (itinerary 6903)
INSERT INTO `itinerary_translations` (`itinerary_id`, `locale`, `title`, `description`, `created_at`, `updated_at`)
VALUES ('6903', 'fr', 'Circuit des Hauts Plateaux de Minahasa', '<p style="text-align:justify;">Après le petit-déjeuner à l\'hôtel, les participants seront pris en charge par le guide pour une excursion d\'une journée complète vers les <strong>Hauts Plateaux de Minahasa</strong>, en passant par la zone de Tinoor où les visiteurs pourront profiter de vues panoramiques sur la ville de Manado depuis une altitude de 500 mètres.&nbsp;</p><p style="text-align:justify;">&nbsp;</p><p style="text-align:justify;">À l\'arrivée à Tomohon, visite du <strong>Taman Wisata Pelangi</strong>, où les participants pourront admirer la beauté de diverses fleurs colorées. Poursuite vers le <strong>marché extrême de Tomohon</strong>, où les visiteurs pourront voir divers types de viandes d\'animaux sauvages comme des chauves-souris, des rats des forêts, des serpents et d\'autres animaux exotiques. Dans un autre lieu, les visiteurs pourront également assister au processus de <strong>préparation en direct</strong> de collations traditionnelles de Manado comme le <i>kue cucur</i>, l\'<i>apang gula merah</i>, le <i>dodol</i>, et d\'autres délices locaux.</p><p style="text-align:justify;">&nbsp;</p><p style="text-align:justify;">Le circuit se poursuit vers <strong>Tuur Maasering</strong>, une forêt d\'aren (palmiers) offrant plusieurs spots photo dignes d\'Instagram. Ici, les participants pourront également observer la fabrication traditionnelle de la liqueur locale <strong>« Cap Tikus »</strong>, produite par fermentation et distillation de la sève de l\'arbre aren.</p><p style="text-align:justify;">&nbsp;</p><p style="text-align:justify;">Déjeuner en option dans un restaurant local. Après le déjeuner, direction <strong>Bukit Kasih</strong>, une attraction naturelle unique dotée de cratères de soufre actifs et d\'escaliers menant au sommet de la colline, offrant des vues panoramiques et une expérience culturelle distinctive. La zone possède également des sources chaudes soufrées naturelles où les visiteurs peuvent se baigner ou se tremper les pieds pour se détendre (en option).</p><p style="text-align:justify;">&nbsp;</p><p style="text-align:justify;">Ensuite, visite du <strong>lac Linow</strong>, un lac de soufre réputé pour ses eaux changeant de couleur et son paysage magnifique, où un café ou un thé sera servi. Retour à la ville de Manado. Dîner en option dans un restaurant local, puis transfert de retour vers l\'hôtel.</p>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `updated_at` = NOW();

-- paket 8 hari 4 (itinerary 6904)
INSERT INTO `itinerary_translations` (`itinerary_id`, `locale`, `title`, `description`, `created_at`, `updated_at`)
VALUES ('6904', 'fr', 'Transfert vers l\'Aéroport – Départ', '<p style="text-align:justify;">Après le petit-déjeuner et l\'enregistrement de départ à l\'hôtel, les participants seront pris en charge par le guide et transférés directement à l\'aéroport pour leur vol de retour. Fin de l\'excursion.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</p>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `updated_at` = NOW();

-- paket 9 hari 1 (itinerary 6905)
INSERT INTO `itinerary_translations` (`itinerary_id`, `locale`, `title`, `description`, `created_at`, `updated_at`)
VALUES ('6905', 'fr', 'Arrivée – Circuit de la Ville de Manado – Colline de Makatete – SunBae Manado', '<p style="text-align:justify;">Dès l\'arrivée à l\'aéroport Sam Ratulangi de Manado, le groupe sera accueilli par le guide et commencera un circuit dans la ville de Manado. Visite du centre-ville, du <strong>quartier chinois</strong>, et du <strong>temple Ban Hin Kiong</strong> - le plus ancien temple de Manado, construit au 18e siècle (environ 300 ans).&nbsp;</p><p style="text-align:justify;">&nbsp;</p><p style="text-align:justify;">Poursuite en passant par l\'<strong>église Sentrum</strong>, la première église protestante du Nord Sulawesi datant de l\'époque néerlandaise, et le <strong>Monument de la Seconde Guerre mondiale</strong>, qui commémore la destruction de Manado en 1942 par les forces japonaises.&nbsp;</p><p style="text-align:justify;">&nbsp;</p><p style="text-align:justify;">Le circuit se poursuit ensuite vers la zone de Ring Road de <strong>CitraLand</strong> pour admirer le <strong>Monument de Jésus Bénissant</strong>, une statue de Jésus construite dans une position penchée en avant unique, surplombant la ville de Manado.&nbsp;</p><p style="text-align:justify;">&nbsp;</p><p style="text-align:justify;">Ensuite, visite de la <strong>colline de Makatete</strong> - située à 200 mètres au-dessus du niveau de la mer, offrant des vues panoramiques sur la ville de Manado, l\'<strong>île de Manado Tua</strong>, l\'<strong>île de Bunaken</strong>, l\'<strong>île de Siladen</strong>, la mer ouverte, et le <strong>mont Klabat</strong>, le plus haut sommet du Nord Sulawesi.</p><p style="text-align:justify;">&nbsp;</p><p>Dîner en option dans un restaurant local. Après le dîner, visite de <strong>SunBae</strong>, l\'un des lieux de rendez-vous branchés en bord de mer de Manado, où les visiteurs peuvent profiter de l\'ambiance du soir avec diverses collations et boissons proposées par de nombreux stands (en option). Ensuite, transfert vers l\'hôtel pour l\'enregistrement et le repos.</p>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `updated_at` = NOW();

-- paket 9 hari 2 (itinerary 6906)
INSERT INTO `itinerary_translations` (`itinerary_id`, `locale`, `title`, `description`, `created_at`, `updated_at`)
VALUES ('6906', 'fr', 'Circuit d\'Observation de Bunaken – Coopérative de Café Locale – Circuit Shopping', '<p style="text-align:justify;">Après le petit-déjeuner à l\'hôtel, les participants seront pris en charge par le guide et se dirigeront vers l\'<strong>île de Bunaken</strong>. Depuis l\'hôtel, transfert vers le quai de Megamas et traversée vers Bunaken en bateau pendant environ 30 minutes.</p><p style="text-align:justify;">&nbsp;</p><p style="text-align:justify;">L\'île de Bunaken dispose désormais du nouveau <strong>quai touristique de Bunaken (New Bunaken)</strong>, offrant un endroit plus charmant et photogénique pour les photos et vidéos.</p><p style="text-align:justify;">&nbsp;</p><p style="text-align:justify;">Ensuite, les participants seront emmenés explorer la beauté du <strong>Parc Marin de Bunaken</strong>, réputé pour ses récifs coralliens colorés et sa vie marine tropicale diversifiée. Les participants pourront profiter d\'activités <i>en option</i><strong> de snorkeling ou de plongée</strong>, ou simplement faire une promenade tranquille en profitant de l\'atmosphère de la plage de Bunaken.&nbsp;</p><p style="text-align:justify;">&nbsp;</p><p style="text-align:justify;">Déjeuner en option dans un restaurant local. Après le déjeuner, les visiteurs auront du temps libre supplémentaire pour le snorkeling/la plongée en option.</p><p style="text-align:justify;">&nbsp;</p><p style="text-align:justify;">Retour au quai de Megamas et visite d\'une <strong>coopérative locale de production de café</strong>, où les participants pourront goûter les saveurs authentiques du café du Nord Sulawesi. Ensuite, poursuite vers une <strong>zone de shopping de souvenirs</strong> proposant une grande variété de spécialités de Manado (ou retour à l\'hôtel puis nouvelle prise en charge avant le dîner).</p><p style="text-align:justify;">&nbsp;</p><p style="text-align:justify;">Dîner en option dans un restaurant local, puis transfert de retour vers l\'hôtel.</p>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `updated_at` = NOW();

-- paket 9 hari 3 (itinerary 6907)
INSERT INTO `itinerary_translations` (`itinerary_id`, `locale`, `title`, `description`, `created_at`, `updated_at`)
VALUES ('6907', 'fr', 'Île de Lihaga – Village Touristique de Budo', '<p style="text-align:justify;">Après le petit-déjeuner à l\'hôtel, les participants seront pris en charge par le guide et se rendront dans la région de Likupang, à environ 1 heure 20 du centre-ville de Manado. Le premier arrêt est le <strong>port de Serei</strong>, et à l\'arrivée, poursuite en bateau pendant environ 15 minutes vers l\'<strong>île de Lihaga</strong>.</p><p style="text-align:justify;">&nbsp;</p><p style="text-align:justify;">Sur l\'<strong>île de Lihaga</strong>, les participants pourront profiter de ses plages de sable blanc et poudreux à couper le souffle, explorer l\'île, et prendre des photos dans divers spots magnifiques et dignes d\'Instagram. Les visiteurs pourront également se joindre à des activités en option comme le snorkeling, le canoë ou la plongée. Le déjeuner sera servi sur l\'île. Après le déjeuner, les participants auront du temps libre supplémentaire pour se détendre sur la plage.</p><p style="text-align:justify;">&nbsp;</p><p style="text-align:justify;">Sur le trajet de retour vers Manado, arrêt au <strong>village touristique de Budo</strong>, où les visiteurs pourront profiter d\'un magnifique coucher de soleil accompagné de douceurs locales comme la banane frite et la noix de coco fraîche.&nbsp;</p><p style="text-align:justify;">&nbsp;</p><p style="text-align:justify;">Dîner en option dans un restaurant local, puis transfert de retour vers l\'hôtel.</p>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `updated_at` = NOW();

