-- paket 10 hari 4 (itinerary 6916)
INSERT INTO `itinerary_translations` (`itinerary_id`, `locale`, `title`, `description`, `created_at`, `updated_at`)
VALUES ('6916', 'fr', 'Île de Lihaga – Village Touristique de Budo', '<p style="text-align:justify;">Après le petit-déjeuner à l\'hôtel, les participants seront pris en charge par le guide et se rendront dans la région de Likupang, à environ 1 heure 20 du centre-ville de Manado. Le premier arrêt est le <strong>port de Serei</strong>, et à l\'arrivée, poursuite en bateau pendant environ 15 minutes vers l\'<strong>île de Lihaga</strong>.</p><p style="text-align:justify;">&nbsp;</p><p style="text-align:justify;">Sur l\'<strong>île de Lihaga</strong>, les participants pourront profiter de ses plages de sable blanc et poudreux à couper le souffle, explorer l\'île, et prendre des photos dans divers spots magnifiques et dignes d\'Instagram. Les visiteurs pourront également se joindre à des activités en option comme le snorkeling, le canoë ou la plongée. Le déjeuner sera servi sur l\'île. Après le déjeuner, les participants auront du temps libre supplémentaire pour se détendre sur la plage.</p><p style="text-align:justify;">&nbsp;</p><p style="text-align:justify;">Sur le trajet de retour vers Manado, arrêt au <strong>village touristique de Budo</strong>, où les visiteurs pourront profiter d\'un magnifique coucher de soleil accompagné de douceurs locales comme la banane frite et la noix de coco fraîche. Dîner en option dans un restaurant local, puis transfert de retour vers l\'hôtel.</p>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `updated_at` = NOW();

-- paket 10 hari 5 (itinerary 6917)
INSERT INTO `itinerary_translations` (`itinerary_id`, `locale`, `title`, `description`, `created_at`, `updated_at`)
VALUES ('6917', 'fr', 'Transfert vers l\'Aéroport – Départ', '<p style="text-align:justify;">Après le petit-déjeuner et l\'enregistrement de départ à l\'hôtel, les participants seront pris en charge par le guide et transférés directement à l\'aéroport pour leur vol de retour. Fin de l\'excursion.</p>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `updated_at` = NOW();

-- paket 28 hari 1 (itinerary 6922)
INSERT INTO `itinerary_translations` (`itinerary_id`, `locale`, `title`, `description`, `created_at`, `updated_at`)
VALUES ('6922', 'fr', 'Arrivée à Manado - Paradise Golf Resort', '<p style="text-align:justify;">Dès l\'arrivée à l\'aéroport international Sam Ratulangi de Manado, notre équipe vous accueillera et vous transférera directement au Paradise Hotel &amp; Golf Resort, situé sur la côte du Nord Sulawesi dans un cadre calme et un paysage rafraîchissant.</p><p style="text-align:justify;">Le trajet vers le complexe dure environ 60 à 90 minutes. À l\'arrivée, enregistrement et le reste de la journée est libre pour vous reposer ou profiter des installations du complexe. Profitez de l\'atmosphère détendue, de l\'air frais et des vues sur le parcours de golf s\'étendant à travers un magnifique paysage tropical.</p><p style="text-align:justify;">Nuit au Paradise Hotel &amp; Golf Resort.</p>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `updated_at` = NOW();

-- paket 28 hari 2 (itinerary 6923)
INSERT INTO `itinerary_translations` (`itinerary_id`, `locale`, `title`, `description`, `created_at`, `updated_at`)
VALUES ('6923', 'fr', 'Expérience Paradise Golf (18 Trous)', '<p style="text-align:justify;">Après le petit-déjeuner à l\'hôtel, il est temps de profiter d\'une partie sur l\'un des plus beaux parcours de golf du Nord Sulawesi.</p><p style="text-align:justify;">Jouez 18 trous complets avec voiturette de golf et caddie inclus. Le parcours combine des fairways stimulants avec des panoramas naturels saisissants, offrant une partie agréable aussi bien aux golfeurs expérimentés qu\'aux débutants.</p><p style="text-align:justify;">Après la partie, vous êtes libre de vous détendre au complexe, d\'admirer les environs, ou de passer du temps avec votre famille et vos compagnons de voyage.</p><p style="text-align:justify;">Nuit au Paradise Hotel &amp; Golf Resort.</p>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `updated_at` = NOW();

-- paket 28 hari 3 (itinerary 6924)
INSERT INTO `itinerary_translations` (`itinerary_id`, `locale`, `title`, `description`, `created_at`, `updated_at`)
VALUES ('6924', 'fr', 'Évasion Sable Blanc de l\'Île de Lihaga', '<p style="text-align:justify;">Après le petit-déjeuner, poursuite vers le port de Serei et traversée en bateau privé vers l\'île de Lihaga, l\'une des plus belles îles tropicales du Nord Sulawesi, connue pour son sable blanc exceptionnellement fin et ses eaux turquoise cristallines.</p><p style="text-align:justify;">Profitez d\'un moment pour vous détendre sur la plage, nager, prendre des photos, ou simplement admirer la beauté préservée de l\'île. Pour celles et ceux qui souhaitent plus d\'activité, snorkeling, canoë et bateau à fond de verre sont disponibles en option pour explorer le paysage sous-marin autour de l\'île.</p><p style="text-align:justify;">Le déjeuner est servi sur l\'île avec une spécialité du Nord Sulawesi de poisson grillé frais accompagné du sambal dabu-dabu signature de Manado. Après avoir profité de l\'île de Lihaga, retour au port de Serei et poursuite vers l\'hôtel.</p><p style="text-align:justify;">L\'après-midi est libre pour se reposer et profiter de l\'atmosphère du complexe.</p><p style="text-align:justify;">Nuit au Paradise Hotel &amp; Golf Resort.</p>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `updated_at` = NOW();

-- paket 28 hari 4 (itinerary 6925)
INSERT INTO `itinerary_translations` (`itinerary_id`, `locale`, `title`, `description`, `created_at`, `updated_at`)
VALUES ('6925', 'fr', 'Départ de Manado', '<p style="text-align:justify;">Après le petit-déjeuner et l\'enregistrement de départ à l\'hôtel, vous aurez du temps libre avant le départ.</p><p style="text-align:justify;">À l\'heure convenue, notre équipe vous transférera vers l\'aéroport international Sam Ratulangi de Manado pour votre vol de continuation.</p><p style="text-align:justify;">Alors que ce voyage touche à sa fin, nous espérons que le golf et la beauté de l\'île de Lihaga resteront un souvenir agréable de vos vacances au Nord Sulawesi.</p><p style="text-align:justify;"><strong>Fin du Programme</strong></p>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `updated_at` = NOW();

-- paket 34 hari 1 (itinerary 6936)
INSERT INTO `itinerary_translations` (`itinerary_id`, `locale`, `title`, `description`, `created_at`, `updated_at`)
VALUES ('6936', 'fr', 'Arrivée à Manado', '<p style="text-align:justify;">Dès l\'arrivée à l\'aéroport international Sam Ratulangi de Manado, notre équipe vous accueillera et vous transférera vers votre hôtel ou complexe sélectionné pour l\'enregistrement. Le trajet vers votre hébergement dure environ 30 à 60 minutes selon son emplacement.</p><p style="text-align:justify;">Le reste de la journée vous appartient pour vous reposer, profiter des installations de l\'hôtel, ou vous détendre dans l\'atmosphère côtière du Nord Sulawesi en préparation de l\'aventure sous-marine qui débute le matin suivant.</p><p style="text-align:justify;">Nuit à votre hôtel ou complexe sélectionné.</p>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `updated_at` = NOW();

-- paket 34 hari 2 (itinerary 6937)
INSERT INTO `itinerary_translations` (`itinerary_id`, `locale`, `title`, `description`, `created_at`, `updated_at`)
VALUES ('6937', 'fr', 'Expérience de Plongée à Bunaken', '<p style="text-align:justify;">Après le petit-déjeuner, poursuite vers le Parc Marin de Bunaken, largement considéré comme une des meilleures destinations de plongée d\'Indonésie. En bateau de plongée, vous visiterez une sélection de sites pour explorer des parois de corail spectaculaires, des jardins de corail colorés, et un écosystème marin riche en vie.</p><p style="text-align:justify;">Bunaken est réputé pour sa remarquable plongée sur paroi, son excellente visibilité, et la chance de voir des tortues vertes et des tortues imbriquées, une grande variété de poissons tropicaux de récif, et des prédateurs comme des barracudas et des requins de récif. Après les plongées, retour à l\'hôtel pour le déjeuner et du temps libre.</p>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `updated_at` = NOW();

-- paket 34 hari 3 (itinerary 6938)
INSERT INTO `itinerary_translations` (`itinerary_id`, `locale`, `title`, `description`, `created_at`, `updated_at`)
VALUES ('6938', 'fr', 'Expérience de Plongée à Bunaken', '<p style="text-align:justify;">Petit-déjeuner avant de retourner explorer la beauté sous-marine de Bunaken. Aujourd\'hui vous visiterez différents sites de plongée, chacun avec son propre caractère, combinant jardins de corail, parois de récif, et une vie marine abondante.</p><p style="text-align:justify;">Profitez de l\'occasion pour observer une grande variété d\'espèces marines tropicales, des poissons de récif colorés aux petites créatures se cachant parmi les coraux. Après le programme de plongée, retour à l\'hôtel pour vous reposer et profiter d\'un après-midi détendu.</p>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `updated_at` = NOW();

-- paket 34 hari 4 (itinerary 6939)
INSERT INTO `itinerary_translations` (`itinerary_id`, `locale`, `title`, `description`, `created_at`, `updated_at`)
VALUES ('6939', 'fr', 'Cascade de Tunan &amp; Circuit Faune Sauvage de Tangkoko', '<p style="text-align:justify;">Après le petit-déjeuner, trajet vers la zone de Talawaan pour visiter la cascade de Tunan, cachée au cœur d\'une forêt tropicale. Tombant d\'une hauteur d\'environ 86 mètres, elle offre un cadre naturel rafraîchissant et est un des joyaux cachés du Nord Sulawesi.</p><p style="text-align:justify;">Le voyage se poursuit vers la Réserve Naturelle de Tangkoko, la zone de conservation de faune sauvage la plus connue du Nord Sulawesi. Accompagné d\'un ranger local expérimenté, vous ferez une randonnée légère à travers la forêt tropicale à la recherche d\'espèces endémiques comme le Yaki (macaque noir à crête de Sulawesi), le tarsier, le calao, et le couscous vivant librement dans leur habitat naturel.</p><p style="text-align:justify;">Après cette expérience unique de faune sauvage, retour à Manado et à votre hôtel.</p>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `updated_at` = NOW();

-- paket 34 hari 5 (itinerary 6940)
INSERT INTO `itinerary_translations` (`itinerary_id`, `locale`, `title`, `description`, `created_at`, `updated_at`)
VALUES ('6940', 'fr', 'Départ de Manado', '<p style="text-align:justify;">Après le petit-déjeuner et l\'enregistrement de départ, vous serez pris en charge et transféré vers l\'aéroport international Sam Ratulangi de Manado conformément à votre horaire de vol.</p><p style="text-align:justify;">Alors que ce voyage touche à sa fin, nous espérons que l\'exploration de la beauté sous-marine de Bunaken et la rencontre avec la faune endémique de Sulawesi à Tangkoko resteront un souvenir inoubliable de votre séjour au Nord Sulawesi.</p><p style="text-align:justify;"><strong>Fin du Programme</strong></p>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `updated_at` = NOW();

-- paket 16 hari 1 (itinerary 6973)
INSERT INTO `itinerary_translations` (`itinerary_id`, `locale`, `title`, `description`, `created_at`, `updated_at`)
VALUES ('6973', 'fr', 'Itinéraire', '<p style="text-align:justify;">Tous les participants seront pris en charge pour une excursion vers la <strong>cascade de Tunan</strong>, située dans le <strong>village de Talawaan</strong>. La source de la cascade de Tunan provient d\'une rivière de montagne qui se déverse avec force le long d\'une falaise abrupte d\'environ <strong>86 mètres de haut</strong>. La forêt intacte et l\'environnement naturel rehaussent la beauté de ce site touristique naturel.</p><p style="text-align:justify;">&nbsp;</p><p style="text-align:justify;">Les participants dégusteront ensuite un déjeuner dans un restaurant local. Le voyage se poursuit vers la <strong>réserve naturelle de Tangkoko</strong>. Installez-vous confortablement et profitez du paysage en traversant de petits villages en route vers une des zones de conservation les plus importantes d\'Indonésie.</p><p style="text-align:justify;">&nbsp;</p><p style="text-align:justify;">Située à environ <strong>20 kilomètres au nord-ouest de Bitung</strong>, la réserve se trouve entre collines et vallées. À l\'arrivée, un <strong>ranger local</strong> vous accueillera et vous guidera à travers la forêt à la recherche de diverses espèces sauvages évoluant librement dans leur habitat naturel. Gardez votre appareil photo prêt — vous pourriez rencontrer le <strong>macaque noir à crête de Sulawesi (Yaki)</strong>, le <strong>tarsier (le plus petit primate du monde)</strong>, ainsi que des <strong>calaos</strong> et des <strong>couscous (marsupiaux aux grands yeux)</strong>.&nbsp;</p><p style="text-align:justify;">&nbsp;</p><p style="text-align:justify;">Après cette exploration de la faune, retour à Manado. Fin de l\'excursion.</p>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `updated_at` = NOW();

-- paket 38 hari 1 (itinerary 7358)
INSERT INTO `itinerary_translations` (`itinerary_id`, `locale`, `title`, `description`, `created_at`, `updated_at`)
VALUES ('7358', 'fr', 'Itinéraire', '<p style="text-align:justify;">Après le petit-déjeuner, notre équipe viendra vous chercher à votre hôtel de la ville de Manado. Le trajet se poursuit vers le quai de Serei Likupang, avec des paysages côtiers et campagnards typiques du Nord Sulawesi tout au long du chemin. À l\'arrivée au quai, embarquez sur un bateau privé vers l\'île de Lihaga, une île tropicale connue pour son sable blanc fin, ses eaux turquoise et son cadre préservé.</p><p style="text-align:justify;">Sur l\'île de Lihaga, profitez de temps libre pour vous détendre sur la plage, nager dans les eaux claires, ou faire le tour de l\'île pour capturer sa beauté naturelle depuis ses plus beaux points de vue. Pour celles et ceux qui souhaitent une activité plus dynamique, snorkeling, canoë et plongée sont disponibles en option pour découvrir le paysage sous-marin bien préservé. Le déjeuner est servi sur l\'île dans le calme des tropiques.</p><p style="text-align:justify;">Dans l\'après-midi, retour en bateau vers le quai de Serei Likupang puis direction la ville de Manado. Avant de retourner à votre hôtel, arrêt au centre de souvenirs de Manado pour acheter des spécialités locales, de l\'artisanat et des souvenirs du Nord Sulawesi. Après le shopping, vous serez transféré vers votre hôtel.</p><p style="text-align:justify;"><strong>Fin de l\'Excursion</strong></p>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `updated_at` = NOW();

-- paket 18 hari 1 (itinerary 7359)
INSERT INTO `itinerary_translations` (`itinerary_id`, `locale`, `title`, `description`, `created_at`, `updated_at`)
VALUES ('7359', 'fr', 'Itinéraire', '<p style="text-align:justify;">Les participants seront pris en charge le matin pour une excursion au <strong>mont Mahawu</strong>, situé à environ 1 heure 15 de la ville de Manado. Le mont Mahawu est une attraction populaire auprès des touristes et randonneurs visitant Manado. Le sentier de randonnée compte environ 150 marches cimentées, ce qui rend l\'ascension relativement facile. En chemin, les participants trouveront des rambardes métalliques pouvant servir d\'appui pendant la montée. En atteignant le sommet, les participants pourront admirer des vues panoramiques spectaculaires sur l\'île de Manado Tua, Bunaken et la ville de Manado.&nbsp;</p><p style="text-align:justify;">&nbsp;</p><p style="text-align:justify;">L\'excursion se poursuit ensuite vers le <strong>sommet</strong> de la <strong>colline de Tetetana</strong>, une destination touristique récemment développée à Tomohon. Outre des vues panoramiques sur quatre régions de la province du Nord Sulawesi, les visiteurs peuvent également admirer la beauté de la colline, entourée de jardins de fleurs colorés.&nbsp;</p><p style="text-align:justify;">&nbsp;</p><p style="text-align:justify;">Le groupe se dirigera ensuite vers un restaurant local pour le déjeuner. Après le repas, les participants retourneront à la ville de Manado et seront déposés au point de prise en charge indiqué. Fin de l\'excursion.</p>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `updated_at` = NOW();

-- paket 37 hari 1 (itinerary 7474)
INSERT INTO `itinerary_translations` (`itinerary_id`, `locale`, `title`, `description`, `created_at`, `updated_at`)
VALUES ('7474', 'fr', 'Arrivée à Manado', '<p style="text-align:justify;">Dès l\'arrivée à l\'aéroport international Sam Ratulangi de Manado, notre équipe vous accueillera et vous transférera vers votre hôtel ou complexe sélectionné pour l\'enregistrement.</p><p style="text-align:justify;">Le reste de la journée vous appartient pour vous reposer après le voyage, profiter des installations du complexe, ou vous détendre dans l\'atmosphère tropicale du Nord Sulawesi. Les visiteurs séjournant sur l\'île de Bunaken poursuivront par un transfert en bateau vers le complexe, suivi de temps libre pour profiter de la beauté de l\'île et de la mer environnante.</p><p style="text-align:justify;">Nuit à votre hôtel ou complexe sélectionné.</p>', NOW(), NOW())
