-- paket 37 hari 2 (itinerary 7475)
INSERT INTO `itinerary_translations` (`itinerary_id`, `locale`, `title`, `description`, `created_at`, `updated_at`)
VALUES ('7475', 'fr', 'Expérience de Plongée à Bunaken', '<p style="text-align:justify;">Après le petit-déjeuner, l\'aventure de plongée débute avec une sélection des meilleurs sites du Parc Marin de Bunaken. La zone est réputée pour ses spectaculaires parois de corail verticales, ses jardins de corail colorés, et son extraordinaire biodiversité marine.</p><p style="text-align:justify;">Pendant les plongées, vous pourrez voir des tortues vertes et des tortues imbriquées se reposant contre les parois de corail, une grande variété de poissons tropicaux, et des prédateurs comme des barracudas et des requins de récif passant à proximité. Après le programme de plongée et le déjeuner, retour au complexe pour vous détendre sur la plage ou profiter des installations du complexe.</p>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `updated_at` = NOW();

-- paket 37 hari 3 (itinerary 7476)
INSERT INTO `itinerary_translations` (`itinerary_id`, `locale`, `title`, `description`, `created_at`, `updated_at`)
VALUES ('7476', 'fr', 'Découvrir Davantage le Paradis Sous-Marin de Bunaken', '<p style="text-align:justify;">Petit-déjeuner avant de continuer à explorer le monde sous-marin de Bunaken. Aujourd\'hui vous visiterez d\'autres sites de plongée au caractère différent, des vastes jardins de corail et belles pentes de récif aux parois profondes pour lesquelles le Parc Marin de Bunaken est réputé.</p><p style="text-align:justify;">Outre sa vie marine plus imposante, Bunaken abrite également de nombreuses petites créatures fascinantes comme des nudibranches, des poissons-lions, des hippocampes, des crevettes et des poissons-scorpions se cachant parmi les coraux. Après les plongées, retour au complexe et temps libre pour vous détendre dans le cadre paisible de l\'île.</p>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `updated_at` = NOW();

