-- paket 23 hari 1 (itinerary 7481)
INSERT INTO `itinerary_translations` (`itinerary_id`, `locale`, `title`, `description`, `created_at`, `updated_at`)
VALUES ('7481', 'fr', 'Arrivée – Découverte de la Cascade de Tunan', '<p style="text-align:justify;">Arrivée à Manado le matin. Rencontre avec notre guide, puis prise en charge pour se rendre à&nbsp;<strong>la cascade de Tunan</strong>, cette cascade se trouve au&nbsp;<strong>village de Talawan</strong>. La source de la&nbsp;<strong>cascade de Tunan</strong>&nbsp;provient de la rivière en amont de la montagne qui s\'écoule assez rapidement à travers des falaises abruptes d\'une hauteur d\'environ 86 mètres. L\'atmosphère de la forêt naturelle encore intacte et préservée ajoute à la beauté autour du site touristique naturel de la&nbsp;<strong>cascade de Tunan</strong>.</p><p style="text-align:justify;">&nbsp;</p><p style="text-align:justify;">&nbsp;Nous roulons directement vers le&nbsp;<strong>Parc National de Tangkoko</strong>&nbsp;<i>(si vous arrivez dans l\'après-midi, passez l\'excursion à la cascade de Tunan et rendez-vous directement au village de Batu Putih à Tangkoko)</i>. En fin d\'après-midi, une courte randonnée dans la forêt à la recherche de la grande vedette du parc : le tarsier, le plus petit mammifère de la planète. La Villa Sanctuaire de Tangkoko sera votre lieu de résidence pour la nuit.</p>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `updated_at` = NOW();

-- paket 23 hari 2 (itinerary 7482)
INSERT INTO `itinerary_translations` (`itinerary_id`, `locale`, `title`, `description`, `created_at`, `updated_at`)
VALUES ('7482', 'fr', 'Journée Complète à Tangkoko', '<p style="text-align:justify;">Après le petit-déjeuner au homestay, commencez à explorer les espèces endémiques du Nord Sulawesi à la réserve naturelle de Tangkoko. Recherchez le macaque noir à crête (singe noir indigène du Nord Sulawesi), un autre tarsier (le plus petit primate du monde), l\'ours couscous, et de nombreux oiseaux. Le parc national abrite la plus forte densité de calaos au monde, incluant le calao rhinocéros.&nbsp;</p><p style="text-align:justify;">&nbsp;</p><p style="text-align:justify;">Après le déjeuner, nous partirons pour une autre excursion dans la jungle de Tangkoko dans l\'après-midi. Nuit au homestay.&nbsp;</p>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `updated_at` = NOW();

-- paket 23 hari 3 (itinerary 7483)
INSERT INTO `itinerary_translations` (`itinerary_id`, `locale`, `title`, `description`, `created_at`, `updated_at`)
VALUES ('7483', 'fr', 'Waruga Sawangan – Circuit des Hauts Plateaux de Minahasa', '<p style="text-align:justify;">Après le petit-déjeuner, départ et route vers les hauts plateaux, puis direction&nbsp;<strong>Waruga Sawangan</strong>, avec un arrêt à l\'ancienne tombe du peuple Minahasa (âge de pierre géant). Déjeuner au&nbsp;<strong>lac Tondano</strong>. Poursuite vers Tomohon pour voir le&nbsp;<strong>marché traditionnel</strong>, puis l\'industrie des maisons en bois démontables du&nbsp;<strong>village de Woloan</strong>&nbsp;(les habitants y créent de magnifiques maisons en bois de style minahasa qui sont démontées et expédiées hors du village), et&nbsp;<strong>Kai\'santi Tomohon</strong>&nbsp;qui est un arrêt photo avec en toile de fond le mont Lokon et de verdoyantes rizières.&nbsp;</p><p style="text-align:justify;">&nbsp;</p><p style="text-align:justify;">Nous passons l\'après-midi au&nbsp;<strong>lac Linow</strong>&nbsp;à déguster un café ou un thé. Enregistrement dans votre chambre dans un complexe hôtelier à Tomohon.&nbsp;</p>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `updated_at` = NOW();

-- paket 23 hari 4 (itinerary 7484)
INSERT INTO `itinerary_translations` (`itinerary_id`, `locale`, `title`, `description`, `created_at`, `updated_at`)
VALUES ('7484', 'fr', 'Trekking au Mont Mahawu – Île de Bunaken', '<p style="text-align:justify;">Après le petit-déjeuner à l\'hôtel, départ. Rencontre avec notre guide, puis direction le&nbsp;<strong>cratère du mont Mahawu</strong>. Après une randonnée de 10 minutes jusqu\'au bord du cratère, vous serez récompensé par une vue à couper le souffle sur Tomohon et Manado, ainsi que sur les îles au-delà ; au fond du cratère, les visiteurs peuvent apercevoir un lac fumant et sentir le soufre s\'échappant des bassins. Après le déjeuner, transfert en bateau vers l\'île de Bunaken (environ 45 minutes de bateau).&nbsp;</p><p style="text-align:justify;">&nbsp;</p><p style="text-align:justify;">Le&nbsp;<strong>Parc Marin de Bunaken</strong>&nbsp;est un parc marin du Nord Sulawesi, en Indonésie, à l\'est de l\'île de Bunaken. Ce parc marin est réputé pour son paysage sous-marin à couper le souffle. Le Parc Marin de Bunaken, d\'une superficie d\'environ 89 065 hectares, est une destination prisée des plongeurs et adeptes du snorkeling du monde entier. Le logement sera assuré dans des complexes hôteliers sur l\'île de Bunaken.&nbsp;</p>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `updated_at` = NOW();

-- paket 23 hari 5 (itinerary 7485)
INSERT INTO `itinerary_translations` (`itinerary_id`, `locale`, `title`, `description`, `created_at`, `updated_at`)
VALUES ('7485', 'fr', 'Île de Bunaken (Baignade / Snorkeling)', '<p style="text-align:justify;">Nous profitons librement des plaisirs de la mer sur l\'un des plus beaux sites de snorkeling d\'Indonésie. Nous sommes au cœur d\'un écosystème magnifique comptant plus de 500 types de coraux et environ 1 500 espèces de poissons, des requins de récif inoffensifs, et des tortues sont fréquemment observées autour de l\'île.</p><p style="text-align:justify;">&nbsp;</p><p style="text-align:justify;"><strong>Remarque :</strong> <i>en option, il est possible de louer du matériel de snorkeling et de le pratiquer depuis la plage ou de réserver une excursion en bateau. Des sorties de plongée sont également possibles (réservation et paiement sur place)&nbsp;</i></p>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `updated_at` = NOW();

-- paket 23 hari 6 (itinerary 7486)
INSERT INTO `itinerary_translations` (`itinerary_id`, `locale`, `title`, `description`, `created_at`, `updated_at`)
VALUES ('7486', 'fr', 'Transfert vers l\'Aéroport', '<p style="text-align:justify;">Après le petit-déjeuner à l\'hôtel, départ. Transfert en bateau vers Manado, puis vous serez accompagné par notre guide vers l\'aéroport pour le transfert de départ. L\'excursion est terminée, merci.&nbsp;</p>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `updated_at` = NOW();

-- paket 40 hari 1 (itinerary 7763)
INSERT INTO `itinerary_translations` (`itinerary_id`, `locale`, `title`, `description`, `created_at`, `updated_at`)
VALUES ('7763', 'fr', 'Itinéraire', '<p style="text-align:justify;">Après le petit-déjeuner, vous serez pris en charge à votre hôtel au centre de la ville de Manado et conduit au <strong>quai de Bahowo</strong>. Depuis le quai, le trajet se poursuit en bateau privé vers l\'<strong>île de Manado Tua</strong>.</p><p style="text-align:justify;">À l\'arrivée sur l\'île, l\'aventure commence avec une ascension du mont Manado Tua d\'environ 3 heures. Le sentier traverse une forêt tropicale et des plantations villageoises de muscade, de girofle, de noix de coco, de banane, de mangue et d\'autres cultures tropicales. En chemin, vous pourrez admirer le cadre naturel et, avec un peu de chance, apercevoir la faune endémique de Sulawesi comme le <strong>tarsier, le Yaki (macaque noir à crête) et divers oiseaux endémiques</strong>.</p><p style="text-align:justify;">Après le trekking, le trajet se poursuit en bateau vers le <strong>Parc National de Bunaken</strong>. Profitez d\'un moment pour explorer la beauté de la mer de Bunaken, avec le snorkeling ou la plongée disponibles en option. Un déjeuner sous forme de panier-repas sera servi et pourra être dégusté à bord du bateau.</p><p style="text-align:justify;">Après Bunaken, retour au <strong>quai de Bahowo</strong>, puis transfert vers votre hôtel dans la ville de Manado.</p>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `updated_at` = NOW();

-- paket 41 hari 1 (itinerary 7765)
INSERT INTO `itinerary_translations` (`itinerary_id`, `locale`, `title`, `description`, `created_at`, `updated_at`)
VALUES ('7765', 'fr', 'Itinéraire', '<p style="text-align:justify;"><strong>Matin &ndash; Prise en Charge &amp; Waruga Sawangan</strong><br>Vous serez pris en charge à votre hôtel dans la région de la ville de Manado et vous vous dirigerez vers <strong>Waruga Sawangan</strong>, un ancien complexe funéraire minahasa abritant des centaines de waruga en pierre. Vous pourrez y découvrir de plus près l\'histoire, les traditions et le patrimoine culturel du peuple Minahasa.</p><p style="text-align:justify;"><strong>Batu Angus &amp; Snorkeling</strong><br>Le voyage se poursuit vers <strong>Batu Angus</strong>, une zone côtière unique formée par d\'anciennes coulées de lave volcanique. Après le déjeuner dans un restaurant local, profitez d\'un moment pour explorer les eaux de Batu Angus par le snorkeling. L\'eau claire vous permettra d\'admirer les récifs coralliens, les poissons tropicaux et une vie marine diversifiée.</p><p style="text-align:justify;"><strong>Après-midi &ndash; Retour à Manado</strong><br>Après avoir profité de la plage et du snorkeling, retour vers la ville de Manado. Vous serez transféré à votre hôtel et l\'excursion se termine.</p><p style="text-align:justify;"><strong>Fin de l\'Excursion.</strong></p>', NOW(), NOW())
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `updated_at` = NOW();
COMMIT;

